/* ÇEVİRİ ru · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ru","olay",{
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Реформа корпуса хумбараджи по европейскому образцу и основание Humbarahâne", "d980cf2a"], "d": ["Хумбараджи Ахмед-паша, француз по происхождению, поступивший на османскую службу, при поддержке великого визиря Хекимоглу Али-паши превратил корпус хумбараджи в оплачиваемую часть, устроенную на европейский лад. Трёхсот солдатам, набранным в Боснии, давалось регулярное обучение, основанное на арифметике и геометрии; были подготовлены новые уставы об организации, снаряжении и выходе в отставку, а современными способами изготовлено сто бомбовых орудий и пятьдесят тысяч бомб. Humbarahâne, где преподавалась геометрия, считается первым зародышем современного военно-инженерного образования в Османской империи.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Смерть Ахмеда III", "455f7fba"], "d": ["Ахмед III, низложенный в 1730 году восстанием Патроны Халила, последние шесть лет жизни провёл в покоях дворца Топкапы, отведённых низложенным падишахам, и умер в шестьдесят три года. Он был погребён в Bahçekapı, в мавзолее своей бабушки Турхан-султан рядом с Йени-Джами.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Константинопольский договор — уступка Южного Закавказья Ирану", "8c205aab"], "d": ["Четырёхлетняя вторая война с Ираном закончилась договором, подписанным после разгрома при Арпачае и потери Гянджи и Тифлиса. Османское государство ушло со всех земель Южного Закавказья и Западного Ирана, занятых с 1723 года, и граница вернулась к линии Касре-Ширинского договора 1639 года. От тринадцати лет восточных походов остались тяжёлое финансовое бремя и опустевшая казна; зато закрытие восточного фронта ради начинавшейся новой войны с Россией было жизненно важным выигрышем.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Падение крепости Очаков (Ochakov) в руки русских", "f93e61f3"], "d": ["Русская армия под командованием фельдмаршала Миниха осадила крепость Очаков в устье Днепра; оборона рухнула после взрыва арсенала, и крепость пала с большими потерями. Потеря Очакова, считавшегося замком северо-западного побережья Чёрного моря, открыла русским путь на Крым и вызвала в Стамбуле большую панику. Крепость на следующий год была оставлена русскими из-за эпидемии и трудностей снабжения и вновь перешла к Османам.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Победа при Баня-Луке — освобождение Боснии", "f603865a"], "d": ["Когда австрийские силы вошли в Боснию и осадили Баня-Луку, боснийский наместник Хекимоглу Али-паша поспешил на выручку с силами, набранными из местного населения, и нанёс тяжёлое поражение превосходившему числом врагу. Эта победа с первого же хода сорвала австрийский план оккупации Боснии, и север эялета был полностью возвращён. Баня-Лука стала одним из переломных моментов, поднявших боевой дух османской армии, постоянно отступавшей перед Австрией после 1683 года.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Победа при Гроцке — открытие пути на Белград", "2101cdff"], "d": ["Австрийская армия, двигавшаяся на защиту Белграда, была заманена в засаду в узком ущелье на берегу Дуная и понесла тяжёлые потери в бою, длившемся целый день. Пока силы фельдмаршала Валлиса беспорядочно отходили к Белграду, османская армия подошла к крепости и начала осаду. Гроцка была самой решительной победой в полевом сражении над Австрией со времён Карловицкого мира и непосредственно обеспечила возвращение Белграда.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Нишский договор — мир с Россией, нейтрализация Азова и прекращение набегов из Крыма", "674f974e"], "d": ["Оставшаяся в одиночестве после того, как Австрия согласилась на мир под Белградом, Россия при посредничестве французского посла Вильнёва была вынуждена закончить войну. Укрепления крепости Азов были разрушены, и область объявлена нейтральной территорией между двумя государствами; Россия приняла условие не держать на Чёрном море военных и торговых судов. Таким образом цель России выйти к морю была отложена ещё на одно поколение, а Османское государство в последний раз в XVIII веке вышло из-за стола переговоров с выигрышем.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Очаков возвращён из-под русской оккупации: после мира 1739 года крепость сдана после разрушения", "7ecc2bef"], "d": ["Русские взяли Очаков 11 июля 1737 года. Согласно миру с Россией в 1739 году крепость была вновь передана османам после разрушения её укреплений; османы удерживали Очаков до 1788 года, до Ясского мира.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Оборона Мосула — отражение Надир-шаха", "c03ffbc1"], "d": ["Надир-шах, взяв Киркук и Эрбиль и подойдя к Мосулу, сорок дней обстреливал город из орудий и одну за другой предпринимал общие атаки. Оборона, которую вёл наместник Хусейн-паша аль-Джалили, вооружив и жителей города, вынудила иранскую армию снять осаду с тяжёлыми потерями. Удержание Мосула предотвратило потерю всего Ирака и на целое столетие укрепило влияние семьи Джалили в городе.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Союз в Дирии — основание первого Саудовского эмирата в Неджде", "188751bf"], "d": ["Эмир Мухаммад ибн Сауд, взявший под покровительство в Дирии изгнанного из Уяйны учёного Мухаммада ибн Абд аль-Ваххаба, заключил с ним союз, ставивший политическую власть на службу религиозному призыву. Это соглашение открыло для семьи Саудов новую историю и объединило разрозненные оазисные эмираты Неджда вокруг единого движения. Эта сила, которой предстояло за полвека дотянуться до Кербелы, Мекки и Медины, вынудила Османское государство отстаивать своё господство в Хиджазе.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Договор в Кердене — конец османо-иранских войн", "1d3a919e"], "d": ["Договором, подписанным после последней четырёхлетней войны, граница, установленная в Касре-Ширине в 1639 году, была подтверждена без изменений; ни одна из сторон не добилась территориальных приобретений. Настойчивое требование Надир-шаха признать джафаризм пятым мазхабом осталось без ответа, зато было решено, что иранские паломники могут свободно совершать хадж и что стороны будут обмениваться послами. Так османо-иранские войны, продолжавшиеся более двух веков, фактически закончились; эта граница в основном сохраняется и поныне.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Смерть Махмуда I и восшествие на престол Османа III", "30203700"], "d": ["Махмуд I, вернувший за двадцатичетырёхлетнее правление земли, потерянные по Белградскому договору, и поддерживавший реформу корпуса хумбараджи, скончался, возвращаясь с пятничного селамлыка. Ему наследовал брат Осман III, до пятидесяти восьми лет проживший в «клетке». Началось недолгое и беспокойное правление; при Османе III, за три года сменившем шесть великих визирей, в делах государства господствовал заметный застой.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Смерть Османа III и восшествие на престол Мустафы III", "3ac10f85"], "d": ["После смерти Османа III, правившего три года, на престол вступил Мустафа III, открытый реформаторским идеям и проявлявший пристальный интерес к делам государства. Новый падишах, опираясь на опыт великого визиря Коджа Рагиб-паши, пытался поправить финансы и обновить армию; в это время были созданы скорострельные артиллеристы барона де Тотта. Однако вступление в 1768 году в войну с Россией должно было затмить все достижения этого семнадцатилетнего правления.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Объявление войны России — Балтский инцидент и начало войны 1768–1774 годов", "9c6aabe0"], "d": ["После того как русские и казацкие отряды, преследуя Барскую конфедерацию в Польше, ворвались в пограничный с Османской империей городок Балта и сожгли его, Диван принял решение о войне, а русский посол был заключён в Семибашенный замок. Война, начатая без серьёзной военной подготовки и объявленная за шесть месяцев вперёд, с самого начала пошла плохо. Эта борьба, которой предстояло длиться шесть лет, обернулась — вместе с нападением на Чесму, разгромом при Кагуле и оккупацией Крыма — одной из самых тяжёлых цепей поражений в османской истории.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Потеря крепости Хотин в пользу русских", "66d43ea4"], "d": ["Хотя две попытки русской армии под командованием князя Голицына были отбиты, после разгрома, постигшего великого визиря между Каменцем и Хотином, армия отступила, и стража оставила крепость. Потеря без сопротивления сильнейшего османского укрепления к северу от Дуная открыла русским ворота Валахии и Молдавии. Оба княжества были заняты в том же году; Хотин удалось вернуть лишь в 1774 году по Кючук-Кайнарджийскому миру.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Разгром на равнине Кагул", "6f408eaf"], "d": ["Через три недели после сожжения флота при Чесме главная османская армия на Дунае была рассеяна на равнине Кагул дисциплинированными, но гораздо более малочисленными войсками фельдмаршала Румянцева. Лагерь, обозы и сотни орудий достались врагу; бежавшие части понесли большие потери при переправе через Дунай. Уничтожение за одно лето и флота, и сухопутной армии привело к падению одна за другой Килии, Аккермана, Измаила и Бендер и к оккупации Крыма.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Русская оккупация Крымского полуострова", "217837b0"], "d": ["Русские армии, год назад занявшие Буджак, под командованием князя Долгорукова прорвались через Перекоп и заняли весь Крымский полуостров. Хан был низложен, на престол поставили прорусски настроенного Сахиб Герая, и таким образом был сделан первый шаг к отрыву ханства от Османов. Потеря Крыма, на протяжении трёх веков служившего северным щитом Османской империи, стала началом процесса, приведшего к независимости в 1774 году и к прямой аннексии в 1783 году.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Смерть Мустафы III и восшествие на престол Абдул-Хамида I", "42cba8e2"], "d": ["На место Мустафы III, скончавшегося в самый тяжёлый момент русской войны, в сорок девять лет взошёл его брат Абдул-Хамид I, проведший сорок три года в дворцовой «клетке». Новый падишах, унаследовавший один из самых трудных периодов в жизни государства, был вынужден столкнуться с тяжёлыми условиями Кючук-Кайнарджийского договора, который будет подписан в том же году. Его пятнадцатилетнее правление прошло в потере Крыма и новой русской войне и закончилось параличом, постигшим его в 1789 году при чтении известия о падении Очакова.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Разгром при Козлудже — поражение, приведшее к Кючук-Кайнарджи", "8e0542f9"], "d": ["Османские силы, собравшиеся под Шумной, были разбиты при Козлудже соединёнными колоннами Суворова и Каменского, и бо́льшая часть армии рассеялась. После этого разгрома на Балканах не осталось силы, способной сопротивляться; русские авангарды осадили Шумен, и ставка великого визиря оказалась под угрозой. Усаживание за стол переговоров в Кючук-Кайнарджи менее чем через месяц и принятие чрезвычайно тяжёлых условий — прямое следствие этого поражения.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Уступка Буковины (Северной Молдавии) Австрии", "190f9caa"], "d": ["Австрия, воспользовавшись слабостью, вызванной Кючук-Кайнарджийским миром, потребовала область Буковину, соединяющую Молдавию с Трансильванией, и добилась этой земли без вступления в войну — угрозами и подкупом. Потеря этой плодородной и стратегически важной области к юго-западу от Хотина фактически разделила Молдавское княжество надвое. Эта уступка, свершившаяся без единого выстрела, считалась одним из ярчайших свидетельств того, что Османское государство утратило способность к сдерживанию.", "dc1e97dd"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Захват Басры Ираном", "0161e709"], "d": ["Садык-хан, брат зендского правителя Керим-хана, после годичной осады взял Басру, и Османское государство потеряло важнейший порт в Персидском заливе. Оккупация непосредственно подорвала индийский торговый путь, доходы от фиников и жемчуга и южную оборону Ирака. Город удалось вернуть лишь в 1779 году, во время борьбы за престол, начавшейся в Иране со смертью Керим-хана.", "838306ba"]},
"OLAYLAR_EK5:1779-03-10:0":{"b": ["Айналыкавакская конвенция — временное соглашение по Крыму", "9b3b0468"], "d": ["Два государства, оказавшиеся на пороге войны из-за того, кто встанет во главе Крымского ханства, при посредничестве Франции подписали в дворце Айналыкавак разъяснительный текст. Россия согласилась вывести из Крыма войска, а Османское государство — признать ханство прорусски настроенного Шахин Герая; право падишаха как религиозного халифа в отношении Крыма было подтверждено. Это хрупкое равновесие, которому предстояло продлиться четыре года, полностью рухнуло в 1783 году, когда Россия прямо аннексировала полуостров.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Строительство крепости Анапа — Кавказская оборонительная линия", "be92a80f"], "d": ["Когда с Кючук-Кайнарджи был потерян Крым, чтобы сохранить османское влияние на Кавказе, приступили к строительству новой крепости в устье реки Кубань. Анапа, построенная на остатках генуэзской колонии, с базаром, банями и более чем двумястами пятьюдесятью лавками, вскоре стала городом, обеспечивающим связь с черкесскими племенами. Крепость в течение сорока восьми лет оставалась самым передовым постом османов против выхода России на Кавказ.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Смещение и казнь великого визиря Халил Хамид-паши", "c44001ca"], "d": ["Халил Хамид-паша, великий визирь-реформатор, которому Абдул-Хамид I по разным случаям выказывал удовлетворение его службой, под утро 31 марта 1785 года был внезапно смещён и сослан в Галлиполи, а всё его имущество конфисковано. Сначала ему были пожалованы эялет Хабеш, санджак Джидда и звание шейх-уль-харама Мекки; проведя апрель 1785 года на Тенедосе в приготовлениях к пути, он был смещён и с этого наместничества, и по полученному фирману о казни убит Каракетхудазаде Али, одним из людей Джезаирли Гази Хасан-паши. Его отрубленная голова была отправлена в Стамбул и выставлена в Ortakapı. По TDV, это внезапное падение истолковывалось обвинением в заговоре с целью низложения падишаха и возведения на престол шехзаде Селима, но настоящими причинами, должно быть, были возмущение его молчанием по поводу аннексии Крыма, враждебность кругов, задетых его реформами, и оппозиция Гази Хасан-паши.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Объявление войны России — началась османо-русская война 1787–1792 годов", "3bfb870c"], "d": ["Когда Екатерина II совершила пышное путешествие в Крым и взяла Грузию под своё покровительство, Диван принял решение о войне с целью отмены аннексии, и русский посол вновь был заключён в Семибашенный замок. Однако армия не была готова, казна была пуста, а поиски союзника не дали результата. Война, которой предстояло длиться пять лет, закончилась падением Очакова с резнёй, потерей Измаила и тяжёлыми условиями Ясского мира.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Вступление Австрии в войну — борьба на два фронта", "ae912290"], "d": ["В силу тайного союза с Россией 1781 года австрийский император Иосиф II объявил войну Османскому государству и двинулся в направлении Белграда и Боснии. Османской армии пришлось внезапно сражаться сразу на двух фронтах: с Россией на севере и с Австрией на западе. Несмотря на победы над австрийцами при Лазарете, Мехадии и Шебеше, с потерей Белграда в 1789 году рухнул и западный фронт.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Османо-прусский союз", "03b88e51"], "d": ["Селим III, едва взойдя на престол, стал искать в Европе союзников и подписал с Пруссией союзный договор, предусматривавший взаимную помощь; Пруссия обязалась объявить войну России и Австрии, а Османское государство — не заключать мира, пока Крым не будет возвращён. Это был первый в османской истории подлинный текст взаимного союза с европейским государством, и он показывал, что отброшено классическое представление, по которому союза с неверными быть не может. Пруссия в войну не вступила, но, принудив Австрию к миру, расчистила путь к Систовскому договору.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Падение крепости Измаил и резня", "6a296b0c"], "d": ["Крепость Измаил, считавшаяся сильнейшим укреплением дельты Дуная, была взята за один день кровавым общим штурмом, устроенным генералом Суворовым; гарнизон и жители города в значительной мере были преданы мечу. Эта резня, нашедшая широкий отклик в Европе, вызвала глубокий шок в османском общественном мнении и сломила хребет дунайской оборонительной линии. Крепость будет возвращена через год по Ясскому миру, но судьба войны была уже решена.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Систовский договор — закрытие австрийского фронта", "58741f1d"], "d": ["Благодаря давлению Пруссии и тому, что Французская революция занимала Австрию на западе, два государства пришли к миру на основе довоенных границ. Австрия вернула все занятые места, включая Белград; Османское государство согласилось лишь на небольшие исправления на хорватской границе. Закрытие западного фронта на таких условиях позволило Османскому государству сосредоточить все силы против России и ограничило потери по Ясскому миру.", "45643640"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Ясский мир — окончательная потеря Крыма и граница по Днестру", "a56fd194"], "d": ["Договором, подписанным по окончании пятилетней войны, границей была признана река Днестр (Turla); левый берег реки остался за Россией, правый — за Османами, а Очаков с округой был окончательно потерян. Османское государство полностью отказалось от надежды вернуть Крым и юридически признало аннексию 1783 года; Валахия и Молдавия были возвращены с двухлетним освобождением от налогов. С принятием обязательства выплатить военную контрибуцию в двенадцать миллионов курушей север Чёрного моря был навсегда уступлен России. Другие места, присоединённые в тот же день: Измаил.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Оставление Орана испанцами и передача Алжиру", "9f95cee6"], "d": ["Когда в результате землетрясения 1790 года крепость и город были в значительной мере разрушены, Испания, уже не способная нести расходы на гарнизон, содержавшийся три века, договорилась с алжирским оджаком и без войны передала Оран и Мерс-эль-Кебир. Так была ликвидирована и последняя европейская позиция на североафриканском побережье. Османский Алжир в течение тридцати восьми лет, оставшихся до французской оккупации, владел всем побережьем.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Фактическое правление Пазвандоглу Османа в Видине", "0ce70361"], "d": ["Пазвандоглу Осман, восставший против установлений Низам-ы Джедид, заставил видинского наместника бежать, захватил город и укрепил его по берегу Дуная глубокими рвами. В 1797 году, на вершине силы, собрав около восьмидесяти тысяч человек, он взял под контроль Никопол, Систов, Рущук, София и Ниш и представлял себя не мятежником, а реформатором. Многомесячная осада Высокой Порты в 1798–1799 годах осталась безрезультатной, и до самой смерти в 1807 году он правил Северной Болгарией на правах полунезависимого властителя.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Открытие Mühendishâne-i Berrî-i Hümâyun", "e9a3a34b"], "d": ["В Hasköy открыто сухопутное инженерное училище для подготовки артиллерийских, инженерно-сапёрных и картографических офицеров для армии Низам-ы Джедид; оно было сухопутным аналогом Морского инженерного училища, основанного в 1773 году. В программе преподавались алгебра, геометрия, механика, фортификация и баллистика, с европейских языков переводились книги по математике и артиллерии. Это училище, считающееся истоком современного инженерного образования в Турции, признаётся началом нынешнего Стамбульского технического университета.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Объявление войны Франции и союз с Россией и Англией", "80e95bd7"], "d": ["После вторжения Наполеона в Египет Османское государство нарушило традиционную французскую дружбу, длившуюся два с половиной века, и объявило войну Франции. В ходе тех же событий оно впервые в своей истории заключило союз с Россией и позволило русскому флоту пройти через Проливы в Средиземное море; затем был подписан союз и с Англией. Благодаря этим союзам Ионические острова были отняты у французов, однако открытие Проливов для иностранного флота создало прецедент, за который впоследствии пришлось дорого заплатить.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Взятие Превезы у французов — сражение при Никополе", "d8e5e892"], "d": ["Когда в 1797 году Венецианская республика была уничтожена, Ионические острова и материковые Превеза, Парга, Воница достались Франции. Янинский наместник Али-паша Тепеленский, воспользовавшись войной, начавшейся из-за вторжения Франции в Египет, двинулся на Превезу и нанёс тяжёлое поражение французскому гарнизону среди развалин Никополя за пределами города. Так эта гавань, оставленная Венеции по Пожаревацкому миру, через восемьдесят лет вошла в османское управление.", "eeebcaf6"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Оборона Акко — отражение Наполеона", "56b5c45b"], "d": ["Наполеон, двигавшийся из Египта в Сирию, осадил Акко и два месяца подряд предпринимал одну за другой атаки; город защищали Джаззар Ахмед-паша, при поддержке британского флота и присланных из Стамбула частей Низам-ы Джедид. Наполеон, вынужденный снять осаду и отойти в Египет, похоронил перед этими стенами мечту дотянуться до Востока. Известие было встречено в Стамбуле с большой радостью и сочтено доказательством того, что только что созданная обученная армия выдержала первое серьёзное испытание.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Набег ваххабитов на Кербелу", "522341ed"], "d": ["Ваххабитские силы, выступившие из Неджда, вошли в Кербелу, разграбили город, разрушили гробницу имама Хусейна и убили более трёх тысяч человек. Мамлюкские наместники Османского государства в Ираке не смогли предотвратить набег; событие вызвало сильную реакцию и в Иране, и в Стамбуле. Это нападение возвестило, что саудовское движение уже перестало быть оазисным эмиратом и превратилось в региональную силу, угрожающую священным городам Османов.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-12:0":{"b": ["Картли-Кахетинское царство присоединено к России", "3b650c5e"], "d": ["Картли-Кахетинское царство, принявшее в 1783 году русское покровительство и подвергшееся в 1795 году разорительному походу Ирана, было упразднено; распоряжением от 12 сентября 1801 года оно было объявлено губернией России, и началось внедрение русской системы управления. Грузия с этой даты потеряла независимость; в течение нескольких лет под русское господство перешли также Мегрелия (1803), Имеретия и Гурия (1804), и Россия вышла к османской кавказской границе.", "957f5cd5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Эвакуация французов из Египта", "00cfdc8c"], "d": ["В результате совместных действий османских и английских сил с суши и с моря были приняты сначала Каир, а затем Александрия, и французские войска были отправлены на кораблях на родину. С окончанием трёхлетней оккупации Египет на бумаге вернулся под османское управление, но борьба за господство между мамлюкскими беями и албанскими отрядами ввергла страну в хаос. Этот вакуум в течение нескольких лет подготовил почву для возвышения Мухаммеда Али из Кавалы.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Парижский договор — восстановление мира с Францией", "1b76991f"], "d": ["Договором, подписанным после эвакуации Египта, состояние войны между Османским государством и Францией было официально прекращено, а старые капитуляции возобновлены. Французским торговым судам было разрешено входить в Чёрное море; взамен Франция признала территориальную целостность Османской империи. Установление мира вернуло простор для манёвра внешней политике Селима III, зажатой между Россией и Англией.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Взятие ваххабитами Таифа", "7b791359"], "d": ["Ваххабитские силы под командованием Сауда ибн Абд аль-Азиза первым ударом по Хиджазу осадили и разграбили Таиф; город пал как первые ворота, открывающиеся в священные земли. Для османского падишаха, носившего звание покровителя Двух святынь, это был удар, непосредственно подрывавший законность власти. Через два с половиной месяца та же армия двинется на Мекку.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Первое взятие Мекки ваххабитами", "21157c05"], "d": ["Через два с половиной месяца после падения Таифа ваххабитские силы вошли в Мекку, разрушили гробницы и установили порядок в соответствии со своими взглядами; шариф Галиб был вынужден отойти в Джидду. Закрытие путей хаджа отозвалось во всём исламском мире и заставило Стамбул просить военной помощи у египетского наместника Мехмеда Али. Это первое господство продлится всего три месяца.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Возвращение Мекки шарифом Галибом", "83d08dff"], "d": ["Шариф Галиб, отошедший в Джидду, с собранными силами осадил Мекку и после двадцатипятидневной осады вернул город у ваххабитов; хутба вновь читалась от имени Османов. Это второе господство также не будет долговечным: силы Сауда вновь возьмут город в 1806 году.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Начало Первого сербского восстания", "0f6e8767"], "d": ["После того как мятежные янычарские дахии, захватившие власть в Белграде, устроили массовую резню сербских старейшин, под предводительством Карагеоргия началось вооружённое сопротивление. Движение, поначалу остававшееся верным падишаху и направленное лишь против дахий, вскоре переросло в национальное восстание, требовавшее автономии и независимости. Сербские силы взяли Белград в 1806 году; это восстание стало первым звеном националистических движений за независимость на Балканах.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Занятие Медины ваххабитами", "84e310d7"], "d": ["После Мекки и Медина перешла в руки ваххабитских сил; сокровищница Равза-и Мутаххара была разделена, а куполообразные гробницы в городе разрушены. Так оба священных города сразу вышли из-под османского контроля, и паломнические караваны из Дамаска и Египта в течение многих лет не могли отправиться в путь. Медина была возвращена лишь семь лет спустя, в 1812 году, египетской армией под командованием Тосун-паши, сына Мехмеда Али-паши.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Начало войны с Россией (османо-русская война 1806–1812 годов) и закрытие Проливов", "ea170804"], "d": ["После того как Селим III, сблизившийся с Францией после победы Наполеона под Аустерлицем, вопреки русскому давлению сместил господарей Валахии и Молдавии, русские армии заняли оба княжества, и началась война. Османское государство закрыло Проливы для русского флота; в ответ Англия также встала на сторону России и послала в Стамбул эскадру. Эта война, которой предстояло длиться шесть лет, переплелась с мятежом Кабакчи и низложением Селима III и закончилась потерей Бессарабии по Бухарестскому миру 1812 года.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Появление английского флота у Стамбула (экспедиция Дакворта)", "195bb58f"], "d": ["Англия, желавшая принудить Османское государство порвать связи с Францией, провела эскадру под командованием адмирала Дакворта через Дарданеллы и бросила якорь перед Стамбулом. Под руководством в том числе французского посла Себастиани население Стамбула мобилизовалось, прибрежные батареи были усилены в течение нескольких дней, и эскадра была вынуждена отойти, не успев обстрелять город; на обратном пути она понесла у Дарданелл тяжёлые потери. То, что столице впервые настолько близко угрожал иностранный флот, поставило вопрос о Проливах в центр европейской дипломатии.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Удушение Мустафы IV", "eeb75c20"], "d": ["После того как Алемдар Мустафа-паша подвергся нападению и погиб, а мятежники захотели идти на дворец, низложенный Мустафа IV был задушен по приказу брата Махмуда II. Его тело было погребено в Bahçekapı в мавзолее отца, Абдул-Хамида I; среди мятежников распространился слух, что гроб пуст.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Каласи-Султание (Дарданелльский) договор — мир с Англией и правило о Проливах", "fe282117"], "d": ["Договором, подписанным с Англией после неудачи экспедиции Дакворта, война между двумя государствами была прекращена, а прежние привилегии английских купцов возвращены. Содержащееся в тексте положение, называемое «древним правилом», закрепляло, что в мирное время никакой иностранный военный корабль не может проходить через Проливы. Этот принцип стал юридической основой всех международных установлений, определявших режим Проливов в течение XIX века.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Разгром при Слободзее — окружение Дунайской армии", "54b60fd1"], "d": ["Бо́льшая часть османской армии, переправившейся через Дунай у Рущука, была зажата в Слободзее манёвром окружения Кутузова с противоположного берега реки и обречена на голод. Тысячи солдат были вынуждены сдаться; силы великого визиря фактически растаяли, и Высокая Порта через месяц вынуждена была просить перемирия. Это поражение — непосредственная причина согласия на отдачу Бессарабии по Бухарестскому миру 1812 года.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Возвращение Белграда и подавление Первого сербского восстания", "06f56f52"], "d": ["Сербские повстанцы, лишённые русской поддержки по Бухарестскому миру, не смогли устоять перед совместными действиями сил из Боснии и Румелии; Хуршид Ахмед-паша вошёл в Белград, и девятилетнее восстание было полностью подавлено. Карагеоргий бежал в Австрию, Смедеревский санджак вновь был непосредственно подчинён османскому управлению. Однако суровые меры, применённые затем, через два года вызвали второе, уже прочное восстание под предводительством Милоша Обреновича.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Второе сербское восстание и звание старшего князя Милоша Обреновича", "e6e82ad2"], "d": ["В ответ на тяжёлые меры, последовавшие за подавлением первого восстания, вспыхнуло новое восстание под предводительством Милоша Обреновича; на этот раз Высокая Порта предпочла силе соглашение. По достигнутому соглашению Милош был признан в звании «старшего князя», а право сбора налогов и ведения внутренних дел было оставлено сербским князьям. Это первое зерно фактической автономии стало отправной точкой процесса, шедшего к фирману 1830 года и независимости 1878 года.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Валашское восстание — переход Ипсиланти через Прут и восстание Владимереску", "67d46a98"], "d": ["Александр Ипсиланти, генерал русской армии, от имени Этники Этерия перешёл через Прут и попытался начать в Валахии и Молдавии всеобщее греческое восстание; в те же дни Тудор Владимереску также поднял местных крестьян. Два движения не смогли соединиться: на призыв Ипсиланти вместе воевать против турок Владимереску ответил: «Я восстал не против турок, а против греков», и вскоре был убит людьми Ипсиланти. Восстание было подавлено османскими силами в мае, но фанариотский порядок господарства прекратился, а пламя восстания перекинулось на Морею.", "935b260a"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Основание Второго Саудовского государства в Эр-Рияде", "34dad3bd"], "d": ["Через шесть лет после падения Дирии в 1818 году и разрушения первого Саудовского государства Турки ибн Абдаллах вывел египетские гарнизоны из Неджда и основал новый саудовский эмират с центром в Эр-Рияде. Новая структура избегала распространения на Хиджаз, предпочла остаться в Неджде и держалась в стороне от прямого столкновения с османско-египетскими силами. Это второе государство продлится до конца века и станет вторым звеном в цепи, ведущей к основанию нынешней Саудовской Аравии. Другие поселения, утраченные в тот же день: Дирия (Неджд).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Аккерманская конвенция — уступки Сербии и княжествам", "c75f15d0"], "d": ["Османское государство, оставшееся без армии сразу после упразднения корпуса янычар, перед ультиматумом России было вынуждено принять соглашение с тяжёлыми условиями. Было подтверждено обещанное Сербии самоуправление, признано, что господари Валахии и Молдавии не могут быть смещены без русского согласия, а русским торговым судам предоставлена полная свобода в Проливах. Когда два года спустя Высокая Порта из-за греческого вопроса объявила, что не признаёт соглашения, Россия сочла это поводом к войне.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Ликвидация тимарной системы", "84d5d1d6"], "d": ["Через год после упразднения корпуса янычар около 5200 тимариотов-сипахи в пятидесяти трёх санджаках Румелии и Анатолии вместе с доходами от тимаров были превращены в кавалерию Асакир-и Мансуре. Так тимарный режим, четырёхвековой хребет османского земельного, налогового и военного устройства, фактически прекратил существование. Опустевшие тимары были переданы казне, и открылся путь к переходу на центральную оплачиваемую армию и денежную налоговую систему.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Основание Tıphâne-i Âmire — начало современного медицинского образования", "ac3e57c0"], "d": ["Для подготовки врачей и хирургов для вновь созданной армии Асакир-и Мансуре по предложению лейб-медика Мустафы Бехджета эфенди в Шехзадебаши была открыта Tıphâne-i Âmire. Занятия были организованы по европейской программе, и обучение сначала велось на французском языке; через несколько лет была создана и Cerrahhâne-i Âmire, и два учреждения были объединены. Это училище, считающееся началом современного медицинского образования в Турции, признаётся истоком нынешнего Стамбульского медицинского факультета.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Начало османо-русской войны 1828–1829 годов", "9dff4e05"], "d": ["После сожжения флота при Наварине и объявления Высокой Портой о непризнании Аккерманской конвенции Россия начала войну сразу на двух фронтах. Поскольку корпус янычар был только что упразднён, а новая армия находилась в стадии создания, османская оборона была слабой с самого начала; русские, переходя Дунай, на востоке взяли Карс и Ахалцихе. Русская армия, за год дошедшая до Эдирне, навязала тяжёлые условия Адрианопольского мира 1829 года и независимость Греции.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Первый договор с Соединёнными Штатами Америки", "d737516f"], "d": ["По торговому и мореходному договору, подписанному после многолетних контактов, США получили на османской территории статус наибольшего благоприятствования и право торгового прохода через Проливы. Отдельная секретная статья предусматривала, что по желанию Османов они смогут строить корабли на американских верфях и покупать готовые суда и лес; Сенат США договор ратифицировал, но эту секретную статью отклонил 27 голосами против 18. Тем не менее путь для кораблей не закрылся: Генри Экфорд в 1831 году продал Османам привезённый им корабль, а американские мастера, работавшие в Aynalıkavak, дали флоту суда нового типа. Этот договор стал документом первых всеобъемлющих отношений Османского государства с государством за пределами Европы.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Прекращение мамлюкского правления в Багдаде", "7e1d38a3"], "d": ["Махмуд II, проводивший политику централизации, объявил мятежником багдадского наместника Давуд-пашу, не присылавшего требуемых денег и убившего посланного из центра чиновника. Силы под командованием Али Рыза-паши после девяностодневной осады взяли город, и почти все мамлюки были уничтожены. Так закончилось полунезависимое мамлюкское правление, продолжавшееся с 1704 года, и Ирак вновь оказался в непосредственном подчинении центру.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Основание Mekteb-i Harbiye в казарме Maçka", "bf31c7d9"], "d": ["Чтобы обеспечить Асакир-и Мансуре-и Мухаммадие офицерами, подготовленными по-европейски, в казарме Maçka была открыта Mekteb-i Fünûn-ı Harbiyye. Учащимся преподавались математика, картография, фортификация и иностранные языки; вскоре для усиления кадров были посланы учащиеся в Вену и Париж. Это училище стало местом рождения традиции офицеров, получивших школьное образование, и тем самым нового поколения военных-интеллигентов, которое появится в конце XIX века.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Непосредственное подчинение Триполи центру — конец династии Караманлидов", "faabcb96"], "d": ["Из-за борьбы за престол внутри семьи Караманлидов и усилившегося европейского давления после оккупации Францией Алжира в 1830 году Высокая Порта вмешалась в Триполи непосредственно. Присланный из Стамбула флот вошёл в город, последний бей из Караманлидов был смещён и доставлен в Стамбул, а эялет передан назначаемому из центра наместнику. С окончанием 124-летнего династического периода был укреплён последний участок Северной Африки, непосредственно управляемый Османским государством.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Упразднение дефтердарства и учреждение Министерства финансов (Maliye Nezâreti)", "89f8125e"], "d": ["Должность дефтердара, главы классического османского финансового устройства, была упразднена, и создано Maliye Nezâreti — министерство европейского образца, а разрозненные казначейства объединены в одних руках. В том же году прочие подразделения Высокой Порты были также реорганизованы под названием нызарет, и осуществлён переход к структуре современного совета министров. Это устройство было одним из важнейших шагов, подготовивших административную основу Танзиматского указа, который будет провозглашён через год.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Утверждение англичан в Адене", "ddbd556b"], "d": ["Англия, опираясь на торговое и дружественное соглашение, заключённое в 1802 году с султаном Лахджа Ахмедом ибн Абд аль-Керимом, высадила войска в порту Аден и взяла город под контроль. Этот порт, запирающий вход в Красное море, превратился в ключевой пункт английской имперской стратегии как угольная база на пути в Индию. Хотя притязание Османского государства на Йемен продолжало существовать на бумаге, фактическое господство на южном побережье после этой даты более не возвращалось.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Возвращение на побережье Тихама: взятие Ходейды, Забида и Моки", "353982d2"], "d": ["На йеменское побережье, оставшееся бесхозным после отхода египетской армии в 1840 году, высадились силы под командованием Тевфик-паши под надзором мекканского шарифа и подчинили османскому управлению порты Ходейда, Забид и Моха. Хотя хотели дойти до Саны, из-за сопротивления населения вернулись в Ходейду; так нагорья остались у зейдитских имамов, и османское господство в течение двадцати трёх лет сохранялось лишь на полосе Тихама. Внутренний Йемен будет возвращён лишь в 1872 году походом Ахмеда Мухтар-паши.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Балта-Лиманская конвенция: совместный османо-русский протекторат над Валахией и Молдавией", "d3bb22e9"], "d": ["Когда революции 1848 года перекинулись на Валахию и Молдавию, османские и русские силы совместно заняли княжества. Конвенцией, подписанной в Балта-Лимане, было решено, что господари назначаются не по выбору, а падишахом на семь лет и что оба государства устанавливают в области совместный контроль. Соглашение, сохранив на бумаге суверенитет Османов, предоставило России право фактического партнёрства и ускорило отрыв дунайских княжеств от Османов.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Вопрос о венгерских беженцах: убежище Кошута и его соратников в Османской империи", "1c7d7ef4"], "d": ["После подавления венгерской революции 1848–1849 годов русско-австрийским вмешательством Лайош Кошут и тысячи венгерских и польских беженцев укрылись на османской земле. Австрия и Россия резко потребовали выдачи беженцев; Высокая Порта при поддержке Англии и Франции отказала в выдаче и поселила группу в Кютахье. Окружение Кошута пробыло здесь около восемнадцати месяцев, сотни беженцев приняли ислам и поступили на османскую службу. Событие было сочтено одной из редких дипломатических побед, поднявших престиж Османской империи эпохи Танзимата в европейском общественном мнении.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Основание Encümen-i Dâniş: первая османская академия в Стамбуле", "6fda1365"], "d": ["Encümen-i Dâniş, учреждённая решением Meclis-i Maârif-i Umûmiyye, — первая османская научная академия, созданная для подготовки научных и учебных книг на турецком языке. 18 июля 1851 года она была торжественно открыта в здании Dârülmaârif; среди её местных и иностранных членов был и Ахмед Джевдет-паша. Хотя она просуществовала недолго, такие труды Джевдета-паши, как Târih и Kavâid-i Osmâniyye, стали плодом этого учреждения, и она считается краеугольным камнем превращения турецкого языка в язык науки.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Победа при Олтенице: первый османский успех на Дунайском фронте", "a660ad2f"], "d": ["На начальном этапе Крымской войны сердар-экрем Омер Лютфи-паша, перейдя Дунай, отбросил русские силы при Олтенице с тяжёлыми потерями. Победа, остановив русское продвижение в самом начале войны, показала Европе силу, приобретённую османской армией благодаря обучению после Танзимата. Этот успех подготовил психологическую почву, облегчившую решение Англии и Франции вступить в войну на стороне Османов.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Союзный договор с Англией и Францией в Стамбуле", "04809278"], "d": ["Союзный договор, подписанный в ходе Крымской войны между Османским государством, Англией и Францией против России, постановлял, что три государства ведут совместные действия и что союзники не заключают сепаратного мира до окончания войны. Так Османское государство впервые в своей истории вступило в военный союз с великими европейскими державами как равная сторона. Этот договор через два года создал и юридическую почву для официального принятия Османов в европейскую систему государств в Париже.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Учреждение Стамбульского Şehremaneti: первая современная муниципальная организация", "be4af27f"], "d": ["Союзные солдаты, скопившиеся в Стамбуле во время Крымской войны, и вызванный ростом населения кризис инфраструктуры обнажили недостаточность классического городского управления, построенного вокруг кадиев. Благодаря Şehremaneti, созданному по европейским образцам, вопросы чистоты, твёрдых цен, надзора за рынками и благоустройства были сосредоточены в одних руках; на следующий год в Бейоглу-Галате как пилотный район был организован Altıncı Daire-i Belediye. Этот шаг считается началом современного муниципального дела у османов.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Парижский договор: конец Крымской войны и принятие Османов в европейскую систему государств", "4aee0e2a"], "d": ["По Парижскому договору, закончившему Крымскую войну, Османское государство было объявлено равноправным членом европейского международного права, а его территориальная целостность поставлена под общую гарантию великих держав. Чёрное море было нейтрализовано, притязание России на покровительство над православными подданными, приобретённое со времён Кючук-Кайнарджи, признано недействительным, а юг Бессарабии (казы Килия, Кагул, Измаил и Болград) передан Молдавии. Однако тот же договор, сделав Указ о реформах международным обязательством, приоткрыл и дверь вмешательству во внутренние дела.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Открытие дворца Долмабахче: перенос центра управления из Топкапы", "71ad26d0"], "d": ["Дворец, заказанный Абдул-Меджидом в 1842 году семье Балян, был открыт после четырнадцатилетнего строительства, и административный центр государства переместился из Топкапы, служившего четыре века, на берег Босфора. Своим европейским стилем, хрустальной лестницей и Залом церемоний дворец стал каменным выражением западнического притязания Танзимата. Его огромная стоимость стала одной из самых критикуемых статей тех лет, когда османские финансы вступили в спираль внешних заимствований.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Объединение Валахии и Молдавии под управлением Кузы: рождение Румынии", "baef4da5"], "d": ["На выборах, проведённых после Парижского договора, оба княжества избрали господарем полковника Александру Иоана Кузу и осуществили фактическое объединение. Хотя Высокая Порта и Австрия возражали, пришлось признать свершившийся факт, поддержанный Францией. Это объединение, остававшееся на бумаге зависимым от Османов, примет в 1862 году название Румыния, а в 1877 году в одностороннем порядке провозгласит независимость; это поворотный пункт в распаде османского господства по берегам Дуная.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Дело Кулели: первая попытка переворота против Абдул-Меджида в Стамбуле", "e3653b21"], "d": ["Тайное общество смешанного военно-гражданского состава, возмущённое политикой Танзимата и равенством, которое Указ о реформах предоставил немусульманам, было накрыто на собрании в мечети Кылыч Али-паши, когда планировало свергнуть падишаха. Поскольку обвиняемых судили в казарме Кулели, событие стало называться этим именем; смертные приговоры были заменены ссылкой. Оно считается первой попыткой дворцового переворота в османской истории, предпринятой организацией, созданной по идеологическим мотивам.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Друзско-маронитская гражданская война на Горе Ливан и события в Дамаске", "5595fdd6"], "d": ["Столкновения, вспыхнувшие в мае 1860 года из-за убийства двух друзов близ Сайды, переросли в самую кровавую друзско-маронитскую гражданскую войну в горах, а в июле перекинулись на Дамаск и закончились гибелью тысяч христиан. После высадки французских войск Высокая Порта послала в область Фуад-пашу с чрезвычайными полномочиями; была проведена жёсткая карательная акция. События стали поводом для европейского вмешательства и непосредственной причиной получения Ливаном особого статуса.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Начало издания Tercümân-ı Ahvâl: первая частная турецкая газета в Стамбуле", "24792957"], "d": ["Tercümân-ı Ahvâl, издававшаяся Агях эфенди и редактировавшаяся Шинаси, — первая турецкая газета, выходившая без государственной поддержки. В предисловии к первому номеру было отстаивано право народа высказываться о своих делах, а публикацией по частям пьесы Шинаси Şair Evlenmesi газета приоткрыла дверь и современной турецкой литературе. Рождение понятия общественного мнения и оппозиционной прессы в Османской империи относят к этой дате.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Устав Горы Ливан: привилегированный статус мутасаррифата для Ливана", "bf375603"], "d": ["Устав, подготовленный после резни 1860 года под давлением великих держав, сделал Гору Ливан привилегированным мутасаррифатом, непосредственно подчинённым Высокой Порте и управляемым административным советом, составленным с учётом равновесия между конфессиями. Было поставлено условие, чтобы мутасарриф был католиком-христианином, подданным Османов, а его назначение представлялось на утверждение великих держав; первым мутасаррифом стал Давуд-паша. Этот порядок продлится до 1915 года и составит ядро современного ливанского государства.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Смерть Абдул-Меджида и восшествие на престол султана Абдул-Азиза", "27204d7c"], "d": ["После смерти от чахотки Абдул-Меджида, подписавшего за двадцатидвухлетнее правление указы Танзимата и о реформах, на престол взошёл его брат Абдул-Азиз. Новый падишах в первые годы внушал надежды мерами экономии и скромным образом жизни; он сделал флот одной из немногих сильнейших в мире. Однако к концу его правления тяжёлый внешний долг, банкротство 1875 года и балканские восстания накопились и подготовили почву для низложения 1876 года.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Принятие объединёнными княжествами названия Румыния", "d960e3fc"], "d": ["Валахия и Молдавия, фактически объединившиеся в 1859 году с двойным избранием Кузы, в 1862 году собрали в Бухаресте под одной крышей свои собрания и правительства и официально приняли название Румыния. Хотя Османское государство юридически сохранило положение сюзерена и ежегодную дань, фактически оно утратило контроль над княжеством. Окончание четырёхвекового османского влияния к северу от Дуная символизируется этой датой.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Присоединение Суакина, Массауа и Дахлака к Египту", "a0924860"], "d": ["Массауа, отданная в 1846 году султаном Абдул-Меджидом хедиву Египта Мухаммеду Али-паше вместе с Суакином в виде салиане (назначенного дохода), при хедиве Исмаил-паше была включена вместе с Дахлаком и Суакином в египетские владения и организована со статусом каймакамства. Так три порта на африканском берегу Красного моря, оставаясь юридически османской землёй, в административном отношении перешли непосредственно от Высокой Порты к Каиру — в тот же зависимый слой, что и соседние Египет и Судан.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Начало Критского восстания (1866–1869)", "3679b861"], "d": ["Широкомасштабное восстание, вспыхнувшее на острове при открытой поддержке Греции, впервые сделало международным вопросом требование критских греков об энозисе (присоединении к Греции). Трёхлетняя ожесточённая горная война нанесла османской армии тяжёлые потери и вызвала большой отклик в европейском общественном мнении. Восстание удалось погасить лишь в 1868 году, когда Али-паша отправился на остров и ввёл в действие устав, предоставивший широкие привилегии.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Вывод последних османских гарнизонов из Белграда и сербских крепостей", "b34217db"], "d": ["Под давлением великих держав и по настойчивому требованию князя Михаила Высокая Порта согласилась оставить последние военные базы, остававшиеся у неё в Сербии; 18 апреля 1867 года османский санджак в Белградской крепости был спущен, а ключи переданы князю. Так закончилось фактическое османское военное присутствие, продолжавшееся с 1521 года, и последнее большое препятствие на пути Сербии к независимости было устранено. Сюзеренитет падишаха свёлся лишь к символическому флагу и вопросу о дани.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Присвоение правителям Египта титула хедива", "09e10c12"], "d": ["В результате усиленного лоббирования Исмаил-паши, представителя третьего поколения династии Мухаммеда Али, и денег, пущенных им в Стамбул, правителю Египта был присвоен титул хедива, подчёркивавший его превосходство над прочими наместниками. В те же годы порядок наследования был изменён так, чтобы власть переходила от отца к сыну, а Египту предоставлены полномочия суверенного характера: внешние займы, награждение орденами, содержание консульств. Эти шаги — первое звено цепи, ускорившей юридический отрыв Египта от Османов.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Критский устав: широкие административные привилегии острову", "12052262"], "d": ["Чтобы положить конец трёхлетнему восстанию, великий визирь Али-паша лично отправился на остров, и по уставу, изданному с одобрения падишаха, критянам были предоставлены смешанные административные советы, местные суды, использование греческого языка в официальных делах и налоговые льготы. Это устройство продлило османское господство на острове ещё на тридцать лет. Однако привилегии, предоставленные христианскому населению, ослабили положение мусульман-критян и заложили семена кризиса 1896–1898 годов.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Открытие Şûrâ-yı Devlet: создание османского Государственного совета", "70b16497"], "d": ["Высочайшим указом от 5 марта 1868 года Meclis-i Ahkâm-ı Adliyye был разделён надвое: административно-законодательные дела отошли к Şûrâ-yı Devlet, судебные — к Dîvân-ı Ahkâm-ı Adliyye; учреждение было торжественно открыто в Высокой Порте, и первым его председателем стал Мидхат-паша. На него были возложены подготовка законопроектов, разрешение административных споров и ведение судебных дел чиновников. Благодаря смешанному составу из мусульман и немусульман оно считается первым институциональным воплощением идеи разделения властей у османов.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Открытие Суэцкого канала: сокращение индийского пути через Египет", "377ccd04"], "d": ["Строительство, начатое в 1859 году, шло десять лет, и канал длиной 163 километра, соединивший Средиземное море с Красным, был торжественно введён в эксплуатацию. Когда путь, связывающий Европу с Индией, сократился на тысячи миль, Египет разом стал ключевым пунктом мировой торговли. Эта геостратегическая ценность станет главной причиной оккупации Египта Англией через тринадцать лет после открытия канала; долг же, возложенный каналом на Египет, довёл хедиват до банкротства.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Учреждение Болгарского экзархата: отделение болгарской церкви от Фанара", "33a8272c"], "d": ["Султанским фирманом была учреждена самостоятельная болгарская церковь (экзархат), отдельная от Греческой патриархии, а вопрос о том, какие казы будут подчинены экзархату, был оставлен на народное голосование. Хотя Высокая Порта сделала этот шаг, чтобы сломить греческое влияние, результат оказался обратным: церковь превратилась в организованный центр болгарской национальной идентичности и болгарских притязаний на Македонию. Так была заложена институциональная основа болгарско-греко-сербского соперничества на Балканах и восстаний 1876 года.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Взятие Асира под непосредственное управление", "4559e099"], "d": ["Когда с открытием Суэцкого канала возросла стратегическая ценность Красного моря, стало ясно, что горы Асир посреди сухопутной дороги в Йемен нельзя оставлять без контроля. Силы Редиф-паши, отправившегося в Йеменский поход, вошли в Абху, подчинили область непосредственному османскому управлению, и был создан санджак Асир. Из-за гористой местности и влияния Идрисидов это господство никогда не установилось полностью.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Поход Мидхат-паши в Неджд: восстановление османского господства в Эль-Хасе", "7db51461"], "d": ["Багдадский наместник Мидхат-паша, воспользовавшись борьбой за престол внутри семьи Саудов, направил войска на западный берег Персидского залива и подчинил область Эль-Хаса вилайету Басра под названием санджака Неджд. Абдалла ибн Фейсал был назначен мутасаррифом, и османское господство было установлено на бумаге. Поход имел целью остановить распространение английского влияния в заливе и в том же году привёл также к переходу Катара под османский контроль.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Смерть великого визиря Али-паши: конец кадров Танзимата", "1cf0141c"], "d": ["После смерти Фуад-паши в 1869 году Али-паша в одиночку нёс политику Танзимата, и с его смертью поколение искусных дипломатов, тридцать лет руководивших внешней политикой государства, исчерпалось. Прорусское и своевольное правление пришедшего ему на смену Махмуд Недим-паши укрепило единоличное управление Абдул-Азиза. В течение пяти лет после смерти Али-паши финансы обанкротились, Балканы восстали, и смена власти стала неизбежной.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Установление османского контроля в Катаре", "3b453165"], "d": ["По приглашению шейха Касима ибн Сани, находившегося под английским давлением, османские силы высадились на Катарском полуострове, и осенью 1871 года в области был установлен османский контроль. Катар был организован как каза в составе санджака Неджд, а шейх назначен каймакамом. Этот шаг стал самым конкретным достижением передовой политики Мидхат-паши в заливе против Англии; османский флаг развевался на полуострове до 1913 года.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Фирман о престолонаследии в Тунисе — бейлик семье Мухаммеда ас-Садик-паши", "1509ebb0"], "d": ["Воспользовавшись поражением Франции от Пруссии, тунисский бей Мухаммед ас-Садик-паша, по инициативе Хайр ад-Дин-паши, отправленного им в Стамбул, получил фирман, по которому Тунис был отдан Мухаммеду ас-Садик-паше и его потомству в порядке наследования с сохранением непосредственной зависимости от Стамбула. Без разрешения падишаха нельзя было вести переговоры о войне и мире, ни одна земля страны не могла быть отдана другому, а требование Османов о войсках должно было удовлетворяться. Франция фирман не признала; через десять лет она оккупировала Тунис.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Взятие Саны: восстановление османской власти в Йемене", "978e20a0"], "d": ["Когда с открытием Суэцкого канала возросла стратегическая ценность Красного моря, Высокая Порта направила в Йемен армию fırka-i ihtiyâtiyye под командованием Ахмеда Мухтар-паши. С взятием Саны власть государства была восстановлена во внутреннем Йемене, фактически потерянном два века назад, а область стала вилайетом. Однако борьба с зейдитскими имамами так и не закончилась; восстания 1891, 1898 и 1904 годов составили самый дорогой и самый долгий внутренний фронт Османов. Другие места, присоединённые в тот же день: Сана, Таиз.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Начало Герцеговинского восстания: новое разгорание Восточного вопроса", "571b18ec"], "d": ["Восстание христианских крестьян вокруг Невесинья из-за тяжёлых налогов и давления аянов вскоре распространилось на всю Герцеговину и питалось добровольцами из Сербии и Черногории. Восстание, вызвавшее навязывание реформ Австрией и Россией, на следующий год спровоцировало болгарские восстания и объявление войны Сербией и Черногорией. Так было разорвано первое звено большой цепи, ведущей к войне 93-го года и потере Балкан по Берлинскому трактату.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Банкротство османских финансов: сокращение выплат по внешнему долгу вдвое", "2cac2fa5"], "d": ["Займы, берущиеся один за другим с 1854 года, расходы Крымской войны, строительство дворцов и анатолийский голод 1873–1874 годов превратили бюджетный дефицит в пропасть свыше пяти миллионов лир. Правительство Махмуд Недим-паши, объявив, что выплаты процентов и основной суммы долга будут на пять лет сокращены вдвое, фактически объявило мораторий. Это решение, вызвавшее сильную реакцию на европейских биржах, положило начало процессу, который через шесть лет закончился Декретом Мухаррема и созданием Управления оттоманским государственным долгом.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Низложение Мурада V и восшествие на престол Абдул-Хамида II", "cffb2271"], "d": ["Мурад V, взошедший на престол после свержения Абдул-Азиза, оказался неспособен исполнять обязанности из-за душевного здоровья, подорванного смертью дяди и делом Черкеса Хасана; из его девяностотрёхдневного правления рассудок был ясным лишь семь дней. По фетве шейх-уль-ислама он был низложен, и на его место поставлен брат Абдул-Хамид II. Новый падишах взошёл на престол, пообещав Мидхат-паше провозгласить конституцию; начиналась эпоха, которой предстояло длиться тридцать три года.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Константинопольская конференция: навязывание великими державами балканских реформ", "b5006a2c"], "d": ["Конференция, собранная великими державами в Стамбуле для разрешения балканского кризиса, потребовала разделить Болгарию на две автономные провинции и ввести в Боснии и Герцеговине реформы под международным контролем. Высокая Порта в день открытия конференции возвестила орудийными залпами о провозглашении Основного закона, пытаясь ответить на навязываемое конституционной реформой. Делегаты сочли это затягиванием и разъехались 20 января 1877 года; через четыре месяца Россия объявила войну.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Открытие первой Палаты депутатов в Долмабахче", "429bb279"], "d": ["115 депутатов, избранных в соответствии с Основным законом, впервые собрались 19 марта 1877 года на церемонии в Зале церемоний дворца Долмабахче; так в османской истории начался период представительного собрания. Мусульманские и немусульманские депутаты резко допрашивали правительство, обсуждали ведение войны и ответственность министров. Эта смелая оппозиция стала главной причиной сокращения жизни палаты.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Начало обороны Плевны: сопротивление Гази Осман-паши", "0e04a878"], "d": ["Осман-паша, двинувшийся из Видина к Плевне, чтобы перерезать путь на Стамбул русской армии, перешедшей Дунай в войне 93-го года, укрепил городок бастионами и окопами и начал легендарную пятимесячную оборону. Три больших русско-румынских штурма подряд были отбиты с тяжёлыми потерями, и армия, которой лично руководил царь Александр II, была вынуждена перейти к осаде. Плевна вошла в историю как самый блестящий оборонительный успех османской армии в XIX веке.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Падение Плевны: крах Дунайского фронта", "185e7602"], "d": ["Осман-паша, у которого после пятимесячной осады закончились припасы, предпринял прорыв через реку Вит; когда он был ранен и попал в плен, город сдался. Русские командиры приветствовали взятого в плен пашу, вернув ему саблю, и Осман-паше было присвоено звание «Гази». С падением Плевны путь русской армии был открыт; в течение двух месяцев пали София, Пловдив и Эдирне, русские авангарды дошли до Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Занятие Софии русскими силами", "ef369d22"], "d": ["Русская армия, преодолев Балканы после падения Плевны, вошла в оставшуюся без защиты Софию. Город уже не вернётся под османское управление; в конце 1878 года он станет столицей автономного Болгарского княжества, а в 1879 году — и фактически. На карте София с этой даты выходит из непосредственного османского управления и переходит под временную русскую оккупацию, а затем под автономное болгарское управление.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Адрианопольское перемирие: молчание оружия в войне 93-го года", "1f899180"], "d": ["После последовательного падения Софии, Пловдива и Эдирне и выхода русской армии к берегам Мраморного моря Высокая Порта была вынуждена просить перемирия. Прекращение огня, подписанное в Эдирне, заставило Османов принять предварительные условия мира: автономию Болгарии, независимость Черногории, Сербии и Румынии и тяжёлую военную контрибуцию. Через месяц эти условия превратятся в текст договора в Сан-Стефано.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Бессрочный роспуск Палаты депутатов Абдул-Хамидом II", "e770b540"], "d": ["После резкой критики депутатов, возложивших ответственность за катастрофический исход войны на правительство и дворец, Абдул-Хамид II, опираясь на предоставленное ему Основным законом полномочие, бессрочно распустил палату. Так закрылся первый османский парламент, проработавший около одиннадцати месяцев, и начался период деспотизма, которому предстояло длиться тридцать лет. Палата смогла собраться вновь лишь после революции 1908 года.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Сан-Стефанский мир: проект Великой Болгарии", "2c7cc611"], "d": ["Сан-Стефанский мир, закончивший войну 93-го года, создавал огромную автономную Болгарию, простиравшуюся до Эгейского моря и включавшую Македонию; признавал независимость Сербии, Черногории и Румынии; оставлял России Карс, Ардаган, Батум и Баязет и, сверх того, возлагал невыполнимую военную контрибуцию. Этот текст, выводивший Россию к Средиземному морю, вызвал бурную реакцию Англии и Австрии. Не будучи приведён в исполнение, он в течение четырёх месяцев был пересмотрен Берлинским конгрессом; тем не менее он остался документом, возвестившим конец Османской Румелии.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Карс, Ардаган и Батум оставлены России — elviye-i selâse", "99bdfad2"], "d": ["По Берлинскому трактату Османское государство уступило России Карс, Ардаган и Батум в счёт части военной контрибуции; долина Баязета и Алашкерта, отданная России в Сан-Стефано, осталась у Османов. Хотя Батум был передан как свободный порт, этот статус он смог сохранять лишь до 1886 года. Русские сделали Карс областью в составе Закавказского генерал-губернаторства с центром в Тифлисе; население elviye-i selâse численностью до 100 000 человек было вынуждено переселиться в сторону Эрзурума.", "e5049807"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Оккупация Боснии и Герцеговины и Нови-Пазара Австро-Венгрией", "e5f901df"], "d": ["На основании полномочия, данного Берлинским трактатом, австро-венгерские армии вошли в Боснию; хотя османское правительство согласилось не сопротивляться, местное мусульманско-православное население в Сараеве и Мостаре взялось за оружие и три месяца оказывало упорное сопротивление. Оккупация была завершена лишь 20 октября 1878 года. Юридический суверенитет падишаха на бумаге сохранялся до 1908 года, но четырёхвековая османская Босния была фактически потеряна, и началась большая волна мусульманской эмиграции. Другие поселения, утраченные в тот же день: Баня-Лука.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Декрет Мухаррема и создание Управления оттоманским государственным долгом (Düyûn-ı Umûmiyye)", "02b7cc03"], "d": ["Переговоры, которые после банкротства 1875 года велись с представителями государств-кредиторов, закончились декретом от 28 мухаррама 1299 года (20 декабря 1881 года): основная сумма долга была сокращена более чем наполовину, взамен наиболее доходные статьи — соляной, табачный, шёлковый, гербовый и рыбный сборы — были переданы Управлению оттоманским государственным долгом, которым непосредственно руководили кредиторы. Это управление, на службе которого состояли тысячи чиновников, превратилось в отдельную финансовую организацию внутри государства. Эта дата считается датой фактического конца османской финансовой независимости.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Суакин — единственный порт, не доставшийся Махди", "5a37b198"], "d": ["С февраля 1884 года, когда все районы восточного Судана, кроме Суакина, перешли под власть Мухаммада Ахмада аль-Махди, порт держался благодаря военной защите английского трёхбатальонного отряда под командованием генерала Грэма. Это было началом периода, когда фактическое и юридическое положение разошлись: хотя побережье фактически находилось под английским военным контролем, административная связь будет отнята у Египта в 1885 году и непосредственно привязана к вилайету Йемен, то есть к Высокой Порте — этот порядок продолжался до оккупации Францией Зейлы в 1888 году.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Убийство Мидхат-паши в темнице Таифа", "f4562261"], "d": ["Мидхат-паша, архитектор Основного закона и символ Первой конституции, был признан виновным в деле, связанном со смертью Абдул-Азиза, на суде в Йылдызе, приговорён к смерти, которая была заменена ссылкой, и отправлен в Таиф. По записи TDV, в ночь с 7 на 8 мая 1884 года он был задушен в своей камере, а официальной причиной названа болезнь «ширпенче». Его смерть стала символом уничтожения конституционной оппозиции при Абдул-Хамиде II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Предоставление немцам концессии на железную дорогу Хайдарпаша–Анкара", "5705b163"], "d": ["Высочайшим указом концессия на строительство и эксплуатацию линии Хайдарпаша–Анкара была предоставлена банкиру Альфреду фон Каулла, представлявшему Deutsche Bank, и было создано Общество Анатолийской железной дороги. Эта концессия стала поворотным пунктом, сломавшим английско-французскую монополию в османских путях сообщения и внешней политике и утвердившим германское влияние. Вместе с концессией на Багдадскую линию, которая будет предоставлена тому же обществу через одиннадцать лет, родилась мечта о «Берлин–Багдад», ставшая одной из главных осей соперничества великих держав накануне Первой мировой войны.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Основание Общества османского единства (İttihâd-ı Osmânî) в Стамбуле", "b7187939"], "d": ["Четверо студентов Военно-медицинского училища основали Общество османского единства как тайную организацию против деспотического управления; эта структура вскоре превратилась в Комитет единства и прогресса, собравший под своей крышей все оппозиционные элементы младотурецкого движения. Организация, основанная на принципе ячеек, объединилась с изгнанниками в Европе и офицерами в Салониках. Из этой небольшой студенческой ячейки вышел кадровый состав, который в 1908 году добьётся провозглашения Второй конституции, а после 1913 года будет единолично управлять государством.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Захват Оттоманского банка: акция дашнаков в Галате", "08b3095f"], "d": ["Вооружённая группа армянской организации «Дашнакцутюн», стремясь привлечь внимание Европы к армянскому вопросу, захватила главное здание Оттоманского банка в Галате, взяла заложников и пригрозила взорвать здание. Кризис закончился после вмешательства послов — в обмен на вывоз участников акции из страны на корабле. Кровавые события в Стамбуле в дни после захвата стали решающими в превращении армянского вопроса в рычаг международного вмешательства.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Начало османо-греческой войны 1897 года: фессалийский фронт", "33e490ab"], "d": ["После высадки Грецией на Крите флота и войск и нападений банд на румелийской границе Османское государство объявило войну. Османская армия, обученная германской реформаторской миссией, стремительно продвинулась в Фессалии и за месяц взяла Yenişehir, Çatalca и Dömeke; греческая армия рассеялась. Под вмешательством великих держав завоёванные земли были возвращены, но война осталась единственной решительной военной победой эпохи Абдул-Хамида II и не смогла предотвратить фактическую потерю Крита.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Предоставление немцам концессии на линию Конья–Багдад", "fd8b6cbd"], "d": ["После визита кайзера Вильгельма II в Стамбул и Дамаск в 1898 году Обществу Анатолийской железной дороги была предоставлена предварительная концессия на линию, которая протянется от Коньи до Багдада и Басры. Проект Багдадской железной дороги означал для Османов укрепление центрального контроля над арабскими вилайетами, а для Германии — выход к Персидскому заливу. Этот проект, против которого резко возражали Англия и Россия, стал одним из самых спорных досье империалистического соперничества, шедшего к Первой мировой войне.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Начало строительства Хиджазской железной дороги в Дамаске", "62f58f68"], "d": ["Линия, повеленная указом Абдул-Хамида II от 2 мая 1900 года, была начата строительством 1 сентября 1900 года на официальной церемонии в Дамаске. Проект, осуществлённый целиком на пожертвования, собранные со всего исламского мира, и силами османских инженеров-военных, сократил путь паломников Дамаск–Медина с сорока дней до пяти. Это было и престижным творением, укреплявшим духовный авторитет халифата, и стратегической инвестицией, усиливавшей военный контроль над Хиджазом.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Мюрцштегская программа: международный реформенный контроль в Македонии", "4c7464da"], "d": ["После Илинденского восстания российский и австрийский императоры встретились в Мюрцштеге и подготовили для Македонии новый пакет реформ. Программа предусматривала приставление к османскому генеральному инспектору двух иностранных гражданских агентов, реорганизацию жандармерии европейскими офицерами и изменение административных границ по национальному принципу. Хотя Высокая Порта сопротивлялась, считая, что нарушаются права суверенитета, перед общим давлением она была вынуждена согласиться; программа стала одним из основных факторов, ускоривших организацию младотурок среди молодых офицеров.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Смерть Мурада V", "396659a7"], "d": ["Мурад V, пробывший на престоле около трёх месяцев в 1876 году и низложенный, после попыток вернуть его на престол жил двадцать восемь лет узником под строгой охраной и умер от диабета. Он был погребён рядом с матерью в мавзолее Cedîd Havâtîn в Йени-Джами. Он вошёл в историю как османский падишах, пробывший на престоле меньше всех.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Потеря Саны в пользу имама Яхьи", "e7f876cb"], "d": ["Восстание зейдитского имама Яхьи Хамид ад-Дина, начатое в 1904 году, закончилось в апреле 1905 года падением Саны после осады; город вышел из османского управления, и в течение осады начались голод и эпидемия. Горная география Йемена, длина линий снабжения и местная легитимность зейдитского имамата делали османское господство здесь хрупким с самого его основания. Город будет возвращён через пять месяцев ценой тяжёлых потерь, однако йеменский вопрос не закрылся до 1918 года.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Покушение в Йылдызе: бомбовое нападение на Абдул-Хамида II", "1ee2e1a6"], "d": ["Организация «Дашнакцутюн» устроила покушение, взорвав набитую часовой бомбой ландо рядом с каретой падишаха, выходившего из пятничного селамлыка; жизнь Абдул-Хамида спасла задержка на несколько минут из-за разговора с шейх-уль-исламом. При взрыве погибли двадцать шесть человек, более пятидесяти были ранены. Событие ещё сильнее ужесточило одержимость падишаха безопасностью и деспотическое правление, опиравшееся на сыскную организацию; оно стало также темой стихотворения Тевфика Фикрета «Bir Lahza-i Taahhur».", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Возвращение Саны: подавление восстания имама Яхьи", "dec3b8f9"], "d": ["Восстание, начатое в 1904 году под предводительством зейдитского имама Яхьи, закончилось падением Саны в апреле 1905 года, и в городе начались голод и эпидемия. Подкрепления под командованием Али Рыза-паши и Ахмеда Фейзи-паши в походе с 15 июля по 1 сентября 1905 года, поддержанном и силами в Таизе, вернули город ценой тяжёлых потерь, и восстание было подавлено. Йеменская кампания принесла османской армии десятки тысяч потерь и огромное финансовое бремя; страх «ссылки в Йемен» среди офицеров в Румелии был одной из главных жалоб, питавших организацию младотурок.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Созыв первой Палаты депутатов Второй конституции", "e7fd2716"], "d": ["Палата, сформированная двухступенчатыми выборами после тридцатилетнего перерыва, была открыта 17 декабря 1908 года речью падишаха, и её председателем был избран лидер младотурецкого движения Ахмед Рыза-бей. Палата, составленная из депутатов-турок, арабов, албанцев, греков, армян и евреев, стала последней большой попыткой воплощения идеала османизма. Однако независимость Болгарии, аннексия Боснии и объявление Крита о присоединении к Греции омрачили этот оптимизм ещё до открытия палаты.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Армия действия и низложение Абдул-Хамида II: восшествие на престол Мехмеда V Решада", "6a65a704"], "d": ["После инцидента 31 марта Армия действия, выступившая из Салоник, в ночь на 22–23 апреля вошла в Стамбул четырьмя колоннами, и 24 апреля дворец Йылдыз сдался. 27 апреля Национальное собрание решило низложить Абдул-Хамида II; падишах был отправлен в Салоники, а на престол поставлен его брат Мехмед V Решад. Так закончилось тридцатитрёхлетнее личное правление, но его место занял новый период, когда падишах стал символом, а Комитет единства и прогресса правил при поддержке армии.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Албанское восстание: вооружённое сопротивление в Косове и Шкодере", "93ed30c6"], "d": ["Централизаторская налоговая политика правительства младотурок, кампания по сбору оружия и спор об латинском алфавите подняли албанские племена, до того считавшиеся одними из самых преданных государству элементов. Хотя армия под командованием Махмуд Шевкет-паши жёстко подавила восстание, волнения вспыхнули вновь в 1911 и 1912 годах. Эти восстания и истощили османскую армию накануне Балканской войны, и ускорили рождение албанского национального движения.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Договор в Уши: уступка Триполитании и Бенгази Италии", "4ffa1fd2"], "d": ["Высокая Порта, не решаясь воевать на два фронта перед лицом военных приготовлений балканских государств, подписала в швейцарском городке Уши тайный мир с Италией и оставила Триполитанию и Бенгази. Так Османское государство потеряло свою последнюю землю в Африке; хотя в обмен было обещано возвращение занятых Италией Родоса и Додеканеса, это обещание не было выполнено никогда. К моменту подписания договора Балканская война уже давно началась.", "d54a35d9"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Занятие Лемноса Грецией", "9555af1d"], "d": ["В Первой Балканской войне греческий флот занял Лемнос; порт острова Мудрос стал базой для блокады пролива Дарданеллы. Остров был оставлен Греции в Лозанне (24 июля 1923 года).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Занятие Тасоса Грецией", "6c03c7f0"], "d": ["В Первой Балканской войне Греция заняла Тасос и Самофракию.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Занятие Самофракии Грецией", "911e82a3"], "d": ["В Первой Балканской войне Греция заняла Самофракию.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Занятие Лесбоса Грецией", "6b2b07ba"], "d": ["Греческий флот высадился на Лесбосе; остров в конце Первой Балканской войны был взят греческой армией и флотом. Лондонская конференция (май 1913 года) подтвердила положение.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Греческая высадка на Хиосе", "901c6539"], "d": ["На Хиос, подвергшийся бомбардировке 7 апреля 1912 года в Первой Балканской войне, высадились греки; османский гарнизон сдался 3 января 1913 года. Остров был оставлен Греции по Лозаннскому договору (24 июля 1923 года).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Убийство великого визиря Махмуд Шевкет-паши в Стамбуле", "68e60e63"], "d": ["Махмуд Шевкет-паша, назначенный великим визирем после нападения на Высокую Порту, был убит выстрелами по его карете близ Çarşıkapı по дороге в Военное министерство. Комитет единства и прогресса, возложив вину за покушение на оппозицию, начал широкую волну арестов и казней, и партия «Свобода и согласие» была фактически ликвидирована. С этим событием окончательно установилась однопартийная диктатура младотурок, опиравшаяся на триумвират Энвер–Талаат–Джемаль.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Начало Второй Балканской войны: спор союзников о разделе", "48d088a2"], "d": ["Балканские союзники, не сумевшие поделить земли, отнятые у Османов по Лондонскому договору, перессорились; с нападением Болгарии на сербские и греческие позиции началась вторая война. Когда на стороне против Болгарии выступили также Румыния и Черногория, болгарская армия рухнула. Османское государство, воспользовавшись этой возможностью, перешло линию Мидия–Энос, проведённую Лондонским договором, и вернуло Восточную Фракию вместе с Эдирне.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Константинопольский договор: мир с Болгарией и закрепление Эдирне", "c8c18b2d"], "d": ["Договор, подписанный между Османским государством и Болгарией после Второй Балканской войны, признав границей реку Мариту, юридически закрепил за Османами Эдирне, Кыркларели, Дидимотихон и Восточную Фракию. Дедеагач был оставлен Болгарии (Кавала же перешла к Греции в июле 1913 года после болгарской оккупации осени 1912 года и была закреплена за Грецией Бухарестским миром 10 августа 1913 года); были урегулированы взаимный обмен населением между двумя странами и права мусульман в Болгарии. Гарантией единственного клочка земли, который удалось вернуть после балканской катастрофы, является этот текст. Другие места, присоединённые в тот же день: Комотини.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Возвращение Тенедоса и Имброса — Афинский договор", "ec084d09"], "d": ["Из северных эгейских островов, занятых Грецией в Балканской войне, Тенедос и Имброс, держащие вход в пролив, в ходе Афинских переговоров были сочтены незаменимыми для обороны Чанаккале и возвращены Османам. Остальные острова остались у Греции. Эти два острова стали последними землями, которые империя удерживала в Эгейском море, и в Лозанне также были оставлены Турции.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Афинский договор: мир с Грецией и передача Салоник и Янины", "8e94def7"], "d": ["Договор, подписанный между Османским государством и Грецией, официально признал переход к Греции Салоник, Янины и Южной Македонии, потерянных в Балканской войне, и османские права на Крит были оставлены. Подробно были урегулированы религиозные и имущественные права мусульман, оставшихся в Греции, статус вакуфов и назначение муфтиев. Статус островов Эгейского моря остался нерешённым и остался источником постоянной напряжённости между двумя государствами.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Подписание в Стамбуле тайного османско-германского союзного договора", "0472efb3"], "d": ["Как только в Европе вспыхнула война, в особняке великого визиря Саид Халим-паши был подписан тайный союзный договор между Османским государством и Германией; текст предусматривал, что в случае вступления России в войну против Германии Османы также встанут на сторону Германии. Договор скрывали даже от кабинета, о нём знали всего четыре человека. Через три месяца нападением на Чёрном море Османское государство будет фактически втянуто в войну, и судьба империи окажется связана этим документом.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Односторонняя отмена капитуляций", "ec773d18"], "d": ["Османское правительство в момент, когда Европа была занята войной, объявило об одностороннем упразднении с 1 октября 1914 года капитуляций, предоставлявших иностранцам судебные, финансовые и таможенные привилегии. Прекращение этого четырёхвекового порядка привилегий было встречено внутри страны большим подъёмом чувства независимости, и в Стамбуле прошли торжества. Все государства, включая союзную Германию, протестовали против решения; капитуляции окончательно станут историей лишь в 1923 году в Лозанне.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Набег на Чёрном море: бомбардировка османским флотом русских портов", "8ad4ef61"], "d": ["«Гёбен» и «Бреслау» (Явуз и Мидилли), бежавшие из Германии и вошедшие в состав османского флота как будто «купленными», вышли в Чёрное море под командованием адмирала Сушона, обстреляли русские порты и потопили суда. Этот приказ Энвер-паши, отданный втайне от кабинета, фактически покончил с нейтралитетом. В течение недели Россия, Англия и Франция объявили войну, и Османское государство необратимо вступило в Первую мировую войну.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Взятие Фао англо-индийскими силами — открытие Иракского фронта", "08663813"], "d": ["На следующее утро после дня, когда государства Антанты объявили войну Османскому государству, англо-индийская бригада, ожидавшая в Бахрейне, высадилась в Фао в устье Шатт-эль-Араба. Небольшой османский отряд в разрушенной крепости Фао отошёл под огнём военных кораблей, и станция индийской телеграфной линии досталась англичанам. Так был открыт Иракский фронт.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Объявление Великого джихада: чтение фетвы о джихаде в мечети Фатих", "2a6174e8"], "d": ["Пять фетв, выданных шейх-уль-исламом Юргюплю Хайри эфенди, были прочитаны от имени халифа-падишаха в мечети Фатих, и все мусульмане были призваны к джихаду против государств Антанты. Этот шаг, на который Германия возлагала большие надежды, имел целью поднять мусульман в английских и французских колониях. Ожидавшегося всеобщего восстания не произошло; напротив, восстание мекканского эмира шарифа Хусейна при английской поддержке два года спустя горько показало пределы политического влияния халифата.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Сдача Курны англичанам", "621d36b0"], "d": ["Силы басрского наместника Субхи-бея, отошедшие после падения Басры в Курну, где сливаются Тигр и Евфрат, сдались утром 9 декабря 1914 года после боёв 4–8 декабря.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["Взятие Египта под английский протекторат и провозглашение султаната", "55d4e520"], "d": ["После вступления Османского государства в войну Англия объявила, что официально берёт под свой протекторат Египет, фактически находившийся под её оккупацией с 1882 года; хедив Аббас Хильми-паша, оставшийся верным Османам, был смещён, и на его место с титулом «султана» поставлен Хусейн Камиль. Так юридический османский суверенитет, продолжавшийся с 1517 года, был прекращён в одностороннем порядке. Высокая Порта решение не признала и через два месяца Канальной операцией попыталась вернуть Египет.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Сарыкамышская операция: катастрофа на Кавказском фронте", "5cbde7f0"], "d": ["Энвер-паша, стремясь вернуть Карс–Ардаган–Батум, потерянные в 1878 году, и поднять турок на Кавказе, зимой бросил III армию в манёвр через горы Аллахуэкбер, имевший целью окружить русские силы. Из-за недостатка зимнего снаряжения, иссякшего снабжения и метели при морозе до минус тридцати градусов армия растаяла ещё до вступления в бой; десятки тысяч солдат погибли от холода. Операция стала одной из самых тяжёлых катастроф османов в войне и на два года оставила восточный фронт беззащитным.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Первая Канальная операция: наступление на Суэц через пустыню Синай", "02dd72f5"], "d": ["Командующий IV армией Джемаль-паша организовал наступление через пустыню Синай, имевшее целью избавить Египет от английской оккупации и закрыть Суэцкий канал для судоходства. Хотя османские части вышли на восточный берег канала и часть сумела переправиться, из-за английского превосходства и того, что ожидавшегося народного восстания в Египте не произошло, они отошли. Операция не достигла цели, но создала косвенный стратегический эффект, вынудив Англию держать в Египте крупные силы.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Принятие закона о переселении и расселении (Sevk ve İskân; Tehcir)", "2f2bc22c"], "d": ["После Ванского восстания и русского продвижения правительство издало временный закон, позволявший командующим армиями переселять в другие области население, признанное нарушающим безопасность в тылу фронта, и падишах утвердил его 27 мая 1915 года. В результате применения закона большая часть армянского населения восточных и южных вилайетов Анатолии была направлена в сторону Сирии и Мосула; во время переселения из-за болезней, голода и нападений были огромные людские потери. Это решение остаётся самым тяжёлым и поныне самым спорным вопросом последних лет Османов.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Османские части вернули Муш из-под русской оккупации", "fb1be113"], "d": ["Через шесть месяцев после первой русской оккупации Муша османский 16-й корпус вошёл в городок в ходе Битлис-Мушского контрнаступления.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Муш вновь перешёл в руки русских", "43ad8a03"], "d": ["Из-за русского контрнаступления османский отряд оставил Муш; городок вновь оказался под русской оккупацией между 22 и 25 августа 1916 года и оставался в её руках до весны 1917 года.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Муш окончательно освобождён от русской оккупации", "f0e89703"], "d": ["Муш, оказавшийся под русской оккупацией в Первую мировую войну, 1 мая 1917 года был окончательно возвращён османскими силами.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Смерть Абдул-Хамида II во дворце Бейлербей", "c9662582"], "d": ["Абдул-Хамид II, низложенный в 1909 году, доставленный сначала в Салоники, а после потери города в Балканской войне — в Стамбул и содержавшийся под домашним арестом во дворце Бейлербей, скончался. За тридцатитрёхлетнее правление он пытался выиграть время, держа государство вдали от войн, но запомнился и деспотическим правлением. Его похоронили при огромном стечении народа в мавзолее Махмуда I на Divanyolu; его смерть пришлась на военный год, когда установленный им порядок был давно ликвидирован.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Брест-Литовский мир: возвращение Карса, Ардагана и Батума", "da82636f"], "d": ["Договор, подписанный между вышедшей из войны после большевистской революции Россией и державами Четверного союза, закрыл Восточный фронт и вернул Османскому государству Карс, Ардаган и Батум (Elviye-i Selâse), потерянные по Берлинскому трактату 1878 года. Это было единственное территориальное приобретение в османской истории после сорокалетнего перерыва. Однако после Мудросского перемирия область вновь будет потеряна, а окончательное решение придёт с Карсским договором 1921 года.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Османские части вошли в Артвин", "ca7d1778"], "d": ["Османские части, 25 марта перешедшие границу 1914 года, двинулись на Elviye-i Selâse, которым Брест-Литовск вернул границу до 1878 года, и 28 марта 1918 года вошли в Артвин. Артвин в составе Батумского санджака был оставлен России в 1878 году; статья TDV об Артвине пишет о возвращении лишь «март 1918 года», день указывает Сары.", "224ac850"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ардаган перешёл в руки турецкой армии", "7fd9e3db"], "d": ["В операции Elviye-i Selâse османская армия после Артвина взяла Ардаган 3 апреля 1918 года; Ардаган пал в войне 93-го года в 1877 году и был оставлен России в 1878 году. Карс будет взят через месяц, 25 апреля.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Возвращение Батума", "d37a1a0d"], "d": ["Османская армия, двинувшаяся на восток после выхода России из войны по Брест-Литовскому миру, через сорок лет вернула порт Батум, потерянный в 1878 году. Этот порт на восточной оконечности Чёрного моря был морским выходом бакинской нефти. Приобретение продлилось лишь семь месяцев; после Мудросского перемирия область была эвакуирована.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Карс перешёл под османское управление", "02cbf0b3"], "d": ["В Брест-Литовске было решено вернуть три санджака — Карс, Ардаган и Батум, — потерянные по Берлинскому трактату 1878 года; османская армия вошла в Ардаган 3 апреля, в Батум 14 апреля, в Карс 25 апреля 1918 года, и управление было фактически установлено. Эти земли, называемые «Elviye-i Selâse», считались возмещением потери, продолжавшейся со времён войны 93-го года. После перемирия они вновь будут потеряны и окончательно присоединены к Турции лишь Карсским договором 1921 года.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Игдыр взят — продвижение в долине Аракса", "87ebf4d3"], "d": ["В рамках наступления, начавшегося в феврале 1918 года, турецкие части разбили армянские части у Сардарапата к северу от Аракса и взяли Игдыр 20 мая 1918 года. Игдыр не входил в Elviye-i Selâse, а был Сурмалинским уездом Эриванской губернии; примерно через 180 лет здесь было установлено первое османское управление.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Смерть Мехмеда V Решада и восшествие на престол Мехмеда VI Вахидеддина", "d302ba07"], "d": ["Мехмед V Решад, чьё девятилетнее правление прошло в Триполитанской, Балканских и Мировой войнах, скончался в самый критический период войны, и на престол взошёл его брат Вахидеддин под именем Мехмед VI. Новый падишах пытался освободиться от опеки младотурецких кадров; через четыре месяца, когда было подписано перемирие, ему предстояло руководить ликвидацией империи. Он был тридцать шестым и последним падишахом османской династии.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Появление флота Антанты перед Стамбулом и фактическая оккупация города", "d10cb14d"], "d": ["После Мудросского перемирия союзный флот из более чем шестидесяти судов — английских, французских, итальянских и греческих — бросил якорь перед Долмабахче, и Стамбул фактически оказался под оккупацией. Через четыреста шестьдесят пять лет столица впервые оказалась под контролем иностранных солдат. В тот же день слова, которые, по преданию, произнёс Мустафа Кемаль-паша, сойдя в Хайдарпаша и увидев картину, — «Как пришли, так и уйдут», — станут одной из символических фраз Национально-освободительной борьбы.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Отход в районе Аракса: Игдыр оставлен", "57572ab4"], "d": ["В соответствии с положением Мудросского перемирия об отходе за границу 1914 года Якуп Шевки-паша приказом от 21 ноября распорядился отвести к 4 декабря части, находящиеся за пределами границы Брест-Литовска; Игдыр и его окрестности были в эту дату полностью оставлены. Затем в конце декабря 1918 года Аракское турецкое правительство было уничтожено армянами.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Англичане обосновались в Артвине", "e2cb3153"], "d": ["Поскольку Мудросское перемирие 30 октября 1918 года требовало отхода османской армии за границу 1914 года, Артвин был оставлен и 17 декабря 1918 года занят англичанами. По статье TDV об Артвине английская оккупация продолжалась до апреля 1920 года.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Британское управление в Батуме после Мудроса", "9dd768fc"], "d": ["По Мудросскому перемирию 30 октября 1918 года Османское государство было вынуждено уйти из Батума; город 24 декабря 1918 года был занят британскими частями. Батум, сделанный в апреле 1918 года центром отдельного санджака, с этой даты до июля 1920 года оставался под английским контролем.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ардаган перешёл под грузинскую власть", "97cf47f6"], "d": ["Ардаган, оставленный после Мудроса, был занят грузинскими силами 20 апреля 1919 года, в дни, когда англичане разгоняли Правительство Юго-Запада Кавказа. Грузинское господство продолжалось до 23 февраля 1921 года.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Престон передал управление Карсом армянскому губернатору", "efa81cb0"], "d": ["Английский командующий Престон, 12–13 апреля 1919 года разогнавший Правительство Юго-Запада Кавказа, 30 апреля 1919 года ликвидировал временное правительство-совет (шура) и передал управление городом армянину Карганову, назначенному карсским губернатором; в Карсе начался период армянского управления, продолжавшийся до победы Казыма Карабекира 30 октября 1920 года.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Эрзурумский конгресс: решение о национальном сопротивлении восточных вилайетов", "41ef0457"], "d": ["Конгресс, созванный Обществом защиты прав Восточной Анатолии, после отсрочки из-за английского давления был открыт с пятьюдесятью шестью делегатами, и его председателем был избран Мустафа Кемаль-паша, ушедший с военной службы. Конгресс объявил, что родина в национальных границах — единое целое, что мандат и протекторат неприемлемы, что в случае распада правительства народ возьмёт свою судьбу в собственные руки. Эти решения через шесть месяцев составят ядро текста Национального обета.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Сивасский конгресс: объединение национального сопротивления под одной крышей", "0e9ad36b"], "d": ["Конгресс, начавший работу 4 сентября 1919 года в Сивасском султание, объединил общества защиты прав со всех концов страны под названием Общество защиты прав Анатолии и Румелии и избрал Представительный комитет. Предложение об американском мандате после долгих споров было отклонено. Обнародованной 11 сентября декларацией Национально-освободительная борьба стала единоцентричным законным политическим движением, и началась открытая борьба сил с правительством Стамбула.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Амасийский протокол: переговоры правительства Стамбула с Представительным комитетом", "40e6a6ab"], "d": ["После падения Дамат Ферида и образования правительства Али Рыза-паши министр флота Салих-паша был послан в Амасью для переговоров с Представительным комитетом. По достигнутым протоколам стамбульское правительство фактически признало существование анатолийского движения; были приняты созыв Палаты депутатов, свободное проведение выборов и сохранение национальных границ. Это первое официальное политическое достижение Национально-освободительной борьбы перед Стамбулом.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Принятие Национального обета в последней османской Палате", "6322865e"], "d": ["Текст Ahd-i Millî, подписанный 121 депутатом последней османской Палаты депутатов, требовал неделимой целостности земель, оставшихся в пределах линии Мудроса и населённых мусульманско-турецким большинством, плебисцита в арабских вилайетах и Западной Фракии, отмены капитуляций и полной политической и финансовой независимости. Текст был принят единогласно 17 февраля 1920 года и объявлен миру. Эта декларация была политической программой Национально-освободительной борьбы и вместе с тем картой границ, которые будут отстаиваться в Лозанне; она стала непосредственной причиной официальной оккупации Стамбула государствами Антанты 16 марта.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["При уходе англичан Артвин остался в Грузии", "6d086b06"], "d": ["По статье TDV об Артвине английская оккупация продолжалась до апреля 1920 года; уходя, англичане оставили город Грузии. Артвин оставался в руках Грузии до ультиматума ВНСТ от 23 февраля 1921 года.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Батум передан грузинскому управлению", "6523d095"], "d": ["Официальная передача Батума англичанами грузинам состоялась 7 июля 1920 года (статья TDV о Батуме пишет лишь «июль 1920 года»). Анкарское правительство 25 июля протестовало против передачи как против «оккупации».", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Александропольский договор: первый международный договор правительства ВНСТ", "9232c690"], "d": ["После того как армия Восточного фронта под командованием Кязыма Карабекира вернула Сарыкамыш и Карс, Армения запросила мира и по договору, подписанному в Гюмри, признала, что не признаёт Севр, и отказалась от территориальных притязаний на востоке. Этот первый договор, подписанный анкарским правительством, стал первым международным документом, фактически отвергшим Севр, и открыл ВНСТ путь к юридическому признанию. Так была обеспечена восточная граница, и стало возможным переместить силы на Западный фронт.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Первая битва при Инёню: первая победа регулярной армии", "4add3719"], "d": ["Вновь созданная регулярная армия остановила греческие войска, наступавшие со стороны Бурсы, на позициях Инёню и вынудила их отойти. Эта победа, ограниченная по военному масштабу, имела очень большие политические последствия: анкарское правительство было приглашено на Лондонскую конференцию, открылся путь к Московскому договору с Советской Россией, и был принят Закон об основах организации. Внутри страны уверенность в регулярной армии также укрепилась этой победой.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Вторая битва при Инёню: второй раз сломлено греческое наступление", "a974521c"], "d": ["Греческая армия, не получившая результата на Лондонской конференции, перешла к новому наступлению со стороны Бурсы и Ушака, но вновь была остановлена на склонах Инёню и вынуждена была отойти. Телеграмма Мустафы Кемаль-паши Исмет-паше «Вы там победили не только врага, но и злую судьбу нации» была написана после этой победы. Битва подняла международный престиж Национально-освободительной борьбы и ускорила процесс вывода Италии из Анатолии.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Анкарское соглашение: мир с Францией и закрытие южного фронта", "35fc32db"], "d": ["Соглашением, подписанным в Анкаре с Францией после победы на Сакарье, война на южном фронте закончилась; французские войска, оставив Чукурову и Юго-Восток, включая Адану, Антеп, Мараш и Урфу, отошли к сирийской границе. Так одно из государств Антанты фактически признало анкарское правительство, и в Севрском фронте появилась первая трещина. Оружие, принятое из освобождённых областей, и высвободившиеся части сыграли решающую роль в подготовке Великого наступления.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Муданийское перемирие: передача Стамбула и Проливов без войны", "ac0d9baf"], "d": ["После того как после Великого наступления турецкая армия оказалась лицом к лицу с английскими силами в Чанаккале и Измите, конференция, собравшаяся в Мудании, после одиннадцатидневного упорного торга закончилась перемирием. Было принято, что Восточная Фракия до Марицы в течение пятнадцати дней будет эвакуирована Грецией и передана турецкому управлению, а Стамбул и Проливы будут сданы по мирному договору. Так вооружённая фаза Национально-освободительной борьбы закрылась дипломатической победой, одержанной без единого выстрела, и открылась дверь в Лозанну.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Отъезд Мехмеда VI Вахидеддина из Стамбула и избрание Абдул-Меджида эфенди халифом", "8ab0e847"], "d": ["Мехмед VI Вахидеддин, последний падишах, положение которого после упразднения султаната стало спорным, утром в пятницу 17 ноября 1922 года покинул Стамбул на английском броненосце «Малайя» и отбыл на Мальту. Через два дня, 19 ноября, ВНСТ избрало Абдул-Меджида эфенди халифом, не обладающим политической властью. Так фактически закончилось династическое правление османов, продолжавшееся шестьсот двадцать три года; халифат же будет сохраняться ещё пятнадцать месяцев в символической форме. Вахидеддин, перебравшийся на Мальту, а затем в Италию, поселился в вилле «Нобель» в Сан-Ремо; его обращения о принятии в какую-нибудь мусульманскую страну не дали результата, и 16 мая 1926 года он умер там, повторив, что никогда не отказывался от прав на султанат и халифат.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Смерть последнего падишаха Мехмеда VI Вахидеддина в Сан-Ремо", "7149ed0e"], "d": ["Мехмед Вахидеддин, последний османский падишах, поселившийся в итальянском городе Сан-Ремо после отъезда из Стамбула, умер 16 мая 1926 года, не узнав о том, что собрался конгресс по халифату (13 мая 1926 года), на котором он заявлял, что никогда не отказывался от прав на султанат и халифат. Он находился в тяжёлой нужде; он был должен сан-ремским торговцам 60 000 лир, и кредиторы, узнав о его смерти, наложили арест на вещи в его доме.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Завоевание Конуралпом области Болу — Мудурну, Konurapa и Болу", "e245cd27"], "d": ["Конуралп, один из полководцев Орхан-гази, направился в гористую область к востоку от Сакарьи и подчинил османскому управлению Мудурну, Konurapa и область Болу; городок на равнине Дюздже стал называться его именем. Точная дата завоевания неизвестна; рассказ опирается на предание Ашыкпашазаде. Область в то время была пограничной зоной, переходившей из рук в руки между Джандаридами и Византией; завоевание впервые приблизило османов к западному берегу Чёрного моря. После битвы при Анкаре область вновь перейдёт к Джандаридам, но в эпоху Завоевателя будет окончательно возвращена.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Взятие византийских городков к югу от Мраморного моря — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["После взятия Никеи и Измита оставшиеся у Византии к западу от Бурсской равнины городки один за другим перешли под османское управление. Gölyazı вокруг озера Улубат, Kirmasti по реке Сусурлук и Mihaliç завершили коридор, соединявший южный берег Мраморного моря с землями Каресидов. Эти городки сдались без долгой осады, лишь с прекращением связи с окрестностями; византийское присутствие в области таким образом было стеснено в Гемликском заливе.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Коринф перешёл к Морейской деспотии", "392495eb"], "d": ["Коринф, с 1358 года бывший владением флорентийского рода Аччайоли в составе Ахейского княжества, в 1395 году перешёл в руки византийского морейского деспота Феодора. Затем город находился под управлением деспотии вплоть до османского завоевания.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Присоединение бейлика Хаджиэмироглу — Орду и Ünye", "c064f07f"], "d": ["Туркменское бейлик, основанное Байрам-беем в окрестностях Орду и расширенное его сыном Хаджи Эмиром в 1350-х годах, было небольшим, но стратегическим прибрежным государством с центром в нынешнем Eskipazar: единственной независимой областью власти между Самсуном и Трабзоном. Эмир Сулейман в 1398 году заявил о верности в Джаникском походе Баязида Молниеносного, после битвы при Анкаре бейлик вновь стал свободным. При Мураде II, в те же годы, что и ликвидация Таджеддиногуллары, земли бейлика были непосредственно присоединены к османскому управлению, и черноморское побережье от Самсуна до Гиресуна оказалось объединено в одних руках.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Завоевание Коринфа", "87a2bc59"], "d": ["В Морейском походе Мехмеда II Завоевателя крепость Акрокоринф три месяца осаждалась и в конце концов была принята мирным путём. Так к османам перешёл Коринфский перешеек, считавшийся воротами Мореи.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Присоединение Черногории к османскому управлению — Цетине", "7fdb7cc8"], "d": ["Когда правившая Зетой династия Черноевичей в 1496 году оставила власть, горная область Черногория, бывшая задним двором Шкодера, была взята под непосредственное османское управление и организована сначала как отдельный санджак, затем как часть санджака Шкодер. Монастырь Цетине был оставлен на месте как религиозный центр области. Из-за суровости географии управление здесь никогда не действовало так строго, как на равнинах; через два столетия власть владыки, возникшая из того же монастыря, станет ядром фактической независимости.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Признание крепостью Баязет османского господства в походе Irakeyn", "f29e2e17"], "d": ["Когда великий визирь Ибрахим-паша в походе Irakeyn подошёл к окрестностям Бингёля, вместе со многими курдскими племенами области крепости Ван, Toprakkale, Avnik и Баязет согласились войти под османское господство. Баязет присоединился к Османам в 1514 году в походе Явуза, но когда армия ушла, Сефевиды вернули область.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Возвращение Тебриза Сефевидам — на обратном пути из Irakeyn", "80b8b761"], "d": ["В походе Irakeyn армия вошла в Тебриз, но, поскольку главной целью был Багдад, постоянного гарнизона в городе оставлено не было. Когда армия, перезимовав в Багдаде, возвращалась на запад, шах Тахмасп вновь вошёл в опустевший Азербайджан и вернул Тебриз. Это был повторяющийся образец османо-сефевидских войн: Тебриз был взят пять раз, и все пять раз его не удавалось удержать; постоянный долговременный османский гарнизон город получит лишь в 1585 году.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Ван и Erciş оказались в руках Тахмаспа (османское положение закончилось в 1534–35 годах)", "cb93d561"], "d": ["В области, отдавшей Ван османскому господству в 1534 году, Улама-паша держался в крепости Ван против сефевидской осады; крепость перешла в руки Сефевидов, а сефевидские силы, осаждавшие Erciş, отошли с османской помощью. Когда Кануни прибыл в Ахлат (23 сентября 1535 года), Ван был уже в руках Тахмаспа. Ван оставался сефевидским до 1548 года.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Переход санджака Баязет под сефевидское господство (Ван и Erciş уже в 1535 году были сефевидскими)", "806a2cf1"], "d": ["Санджак Баязет посреди османско-сефевидской границы вновь перешёл в руки Ирана (Кая 2017 говорит об этом «вместе с Ваном и Erciş»; однако Ван и Erciş, согласно Караташ 2025 и TDV, вернулись к Сефевидам 22 сентября 1535 года — см. предыдущую запись); при этой смене рук некоторые места санджака были разорены. Санджак до последней четверти XVI века многократно переходил из рук в руки между двумя государствами.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Повторный переход санджака Баязет к османам во время Нахичеванского похода", "cf0171fa"], "d": ["Во время третьего иранского (Нахичеванского) похода Кануни санджак Баязет был вновь взят под османское управление. В походе 1554 года Баязет стал важной базой для армии; санджак в 1578 году окончательно вошёл в османское верховенство.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Потеря Эривани в пользу шаха Аббаса", "34413cf2"], "d": ["Когда в годы, когда восстания Джелали сковали Анатолию, восточный фронт остался беззащитным, шах Аббас, реорганизовавший свою армию по европейскому образцу, перешёл в наступление. Эриванская крепость, построенная Фархад-пашой в 1583 году, сдалась после семимесячной осады. Первое звено кавказской линии, обретённой по договору Фархад-паши, было разорвано, и в следующие три года был потерян весь Южный Кавказ.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Потеря Тифлиса и Гянджи", "3fb51753"], "d": ["После падения Эривани сефевидская армия двинулась вдоль долины Куры; центр Карабаха Гянджа и столица Грузии Тифлис были потеряны одна за другой. Османское государство в то же время вело на австрийском фронте тринадцатилетнюю долгую войну и боролось с Джелали в Анатолии; сил для отправки на восток не было. Так фактически закончился порядок широких кавказских эялетов, созданный договором Фархад-паши 1590 года.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Потеря Ширвана — Шемаха, Баку и Дербент", "81beab11"], "d": ["Ширванский эялет на каспийском берегу, приобретённый в походах Осман-паши Оздемироглу 1578–1585 годов, давал османским финансам значительный доход как главный источник шёлковой торговли. Операция шаха Аббаса, направленная на север, последовательно взяв Шемаху, Баку и Дербент, ликвидировала этот эялет. Потеря была не только территориальной: путь иранского шёлка, шедший в Европу через Османов, также вышел из-под контроля, и государство Сефевидов начало сбывать шёлк через Индийский океан.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Потеря Таиза", "65f20d53"], "d": ["Османы в 1038 (1629) году вместе с господством над Йеменом, оставленным под касимидским правлением в Сане, оставили и Таиз — первый большой шаг в процессе, в котором зейдитские имамы вернули внутренний Йемен.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Потеря Йемена — господство имамов Касимидов", "49e83e3c"], "d": ["Йемен с 1538 года был османским эялетом; однако сопротивление зейдитских имамов никогда не прекращалось. Восстание, начатое имамом Касимом, при его сыне аль-Муайяде Мухаммаде распространилось на всю страну, и османские гарнизоны были один за другим осаждены. В годы, когда Мурад IV был занят Багдадом и Эриванью, подкрепления послать не удалось; Таиз был потерян в 1629 году, а Моха на последней стадии того же краха была оставлена 22 октября 1635 года. В 1635 году последние части в Сане и Забиде также оставили Йемен. Так восточный берег Красного моря на двести тридцать семь лет остался вне империи и был возвращён лишь в 1872 году.", "7d62c00f"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Эвакуация Мохи", "c6b3061a"], "d": ["Мустафа-бей 10 джумада аль-уля 1045 года (22 октября 1635 года) эвакуировал Моху с оставшимися силами и оружием; затем Хасан ибн Касим, сын имама Касима, назначив в Забид и Моху своих людей, установил касимидский контроль и на побережье Тихама.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Потеря Эль-Хасы в пользу эмирата Бану Халид", "a9b6131a"], "d": ["Эль-Хаса была эялетом, созданным в 1550 году, чтобы закрыть для Португалии западный берег Персидского залива; но она находилась очень далеко от Стамбула, на конце единственной пустынной дороги. В годы, когда критская осада истощила ресурсы, племя Бану Халид в этой области под предводительством Баррака ибн Гурайра вывело османский гарнизон и создало собственный эмират. Западный берег залива полтора столетия оставался в племенных эмиратах; в 1795 году он перейдёт к Саудам, в 1871 году — вновь к Османам.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Потеря Превезы и Воницы в пользу Венеции — открытие эпирского побережья", "1201204c"], "d": ["Венеция, вступившая в Священную лигу, до начала Морейского похода взяла две крепости, держащие вход в Амбракийский залив: Превезу и Воницу на противоположном берегу. Тем же летом пала и Айя-Мавра (Лефкада). Эти три позиции позволили безопасно вводить флот с Ионического моря вглубь Греции и стали базой Морейской кампании, которая начнётся в следующем году. Превеза и Воница и по Пожаревацкому миру остались у Венеции; под османское управление они вернутся лишь в 1798 году.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Потеря Сольнока — распад линии Тисы", "51c2c8ef"], "d": ["После падения Нове-Замки в августе габсбургская армия повернула на юг и взяла Сольнок, плацдарм на реке Тиса. Город был единственным безопасным проходом между Будой и Трансильванией; его потеря означала отрыв османских крепостей в восточной половине Венгрии друг от друга. Решающим стало то, что на следующий год при осаде Буды путь снабжения был перерезан.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Потеря Модона в пользу Венеции", "114c9cc0"], "d": ["Модон на юго-западной оконечности полуострова Морея был портом, потерянным Венецией три столетия назад и называемым ею «одним из двух глаз государства». Крепость, осаждённая после падения Корона, была взята ударами одновременно с суши и с моря. Морейская кампания Морозини таким образом овладела всем западным берегом полуострова и открыла дорогу во внутренние области.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Потеря Печа", "99d54cf4"], "d": ["После падения Буды в сентябре габсбургские силы спустились на юг к западу от Дуная и взяли Печ, принадлежавший османам со времён Кануни. Город, известный по мечети Гази Касим-паши, был одним из самых развитых санджаковых центров эялета Буда. Его потеря означала открытие дороги, спускавшейся на Мохачское поле; на следующий год именно здесь произойдёт Второй Мохачский разгром.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Потеря Сегеда", "9fbee1b2"], "d": ["Сегед в месте слияния рек Тиса и Муреш был южными воротами Венгерской равнины и держал дорогу в эялет Тимишоара. Крепость, осаждённая после падения Буды и Печа той же осенью, вскоре сдалась. Потеря трёх крепостей за один сезон была признаком того, что османское административное устройство в Венгрии, существовавшее с 1541 года, начало рушиться.", "63dea9ab"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Потеря Патр — северные ворота Мореи", "b9cff63c"], "d": ["Патры у входа в Коринфский залив были портом, контролировавшим переход между Мореей и Румелией. После взятия города венецианской армией одна за другой пали и крепости на обоих берегах залива, и полуостров был полностью изолирован с суши. В итоге этой кампании вся Морея перешла к Венеции; область до 1715 года будет управляться под названием «Regno di Morea».", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Передача Коринфа Венеции", "9a25b6b9"], "d": ["После падения Патр Коринф был мирным путём передан венецианцам, а мусульманское население покинуло город. В августе 1687 года армия Морозини собиралась в Коринфе для похода на Афины.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Потеря Эгера", "983391aa"], "d": ["Эгер был взят в 1596 году в походе, в котором лично участвовал Мехмед III, и стал центром эялета, носящего его имя. Эта последняя большая османская крепость в Северной Венгрии после Второго Мохачского разгрома год держалась в полной осаде и сдалась из-за голода. С её потерей северный фланг Османского государства в Венгрии был полностью ликвидирован.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Потеря Секешфехервара — коронационного города венгерских королей", "c6147255"], "d": ["Город, где на протяжении веков короновали и хоронили венгерских королей, был взят Кануни в 1543 году и стал одним из важнейших санджаковых центров эялета Буда. Крепость, полностью отрезанная примерно через два года после падения Буды, сдалась. С этой потерей османское присутствие к западу от Дуная было стеснено в области Срема и Осиека.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Потеря Сигетвара", "834910a7"], "d": ["Сигетвар был крепостью, в которой во время осады в 1566 году, в тринадцатом и последнем походе Сулеймана Кануни, скончался султан; поэтому в османской памяти она имела символическое значение. Через сто двадцать три года, после падения всех окрестных крепостей, сдалась и крепость, защищённая болотами. Мавзолей, где были погребены внутренности Кануни, и окружавший его городок были разрушены после перехода под габсбургское управление.", "54f30d14"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Потеря Орадя", "6cce360d"], "d": ["Орадя была ключевой крепостью, открывающейся на Трансильванию, взятой в 1660 году Кёпрюлю Мехмед-пашой и сделанной центром эялета, носящего её имя. Крепость, оставшаяся в полном одиночестве после разгрома при Сланкамене, сдалась из-за голода после блокады, продолжавшейся около двух лет. С её потерей османское влияние в Трансильвании фактически закончилось, и габсбургское господство утвердилось к востоку от Тисы.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Потеря Yanova — закрытие трансильванского пути", "4b5e30d8"], "d": ["Yanova была крепостью, взятой в 1658 году и державшей связь между Орадей и Тимишоарой. Когда сразу после падения Орадя её окружение было перерезано, она также была потеряна. Так эялет Тимишоара оказался полностью изолирован с севера и до Карловиц существовал как единственная остававшаяся у Османов венгерская земля.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Установление власти владык в Черногории — фактический отрыв Цетине", "a924b778"], "d": ["В годы, когда война Священной лиги ослабила османский контроль на Балканах, митрополия во главе монастыря Цетине стала должностью, переходящей от отца к сыну в семье Петровичей, и область фактически получила отдельное управление. Благодаря неприступности гор это владычество на протяжении двух столетий существовало в положении ни полностью независимом, ни полностью зависимом; юридически её независимость будет признана лишь Берлинским трактатом 1878 года.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Возвращение Коринфа", "26f53e3a"], "d": ["Первой крупной остановкой Морейского похода Дамад Али-паши стал Коринф; османы вернули город у венецианцев в июне 1715 года и отсюда двинулись дальше по полуострову.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Наступление Надира: потеря Тебриза, Нахичевани, Хамадана, Керманшаха, Мараги и Касре-Ширина", "d95efd59"], "d": ["Города Западного Ирана, взятые между 1723 и 1727 годами с использованием краха государства Сефевидов, один за другим были потеряны в результате наступления Надир-хана, захватившего фактическую власть в Иране. В Азербайджане Ардебиль и Halhal также оказались в руках Надира. Потеря Хамадана, Керманшаха и Касре-Ширина вызвала в Стамбуле тяжёлый отклик; то, что армия не выступила в поход и ожидала в Ускюдаре, и попытки скрыть потерю стали одной из непосредственных причин восстания Патроны Халила, вспыхнувшего через шесть недель.", "3affcf18"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Разгром при Baghavard (Arpaçay) — потеря Кавказа в пользу Надир-хана", "4262f54c"], "d": ["Кавказские эялеты, взятые в 1723–1725 годах с использованием краха государства Сефевидов, удалось удерживать десять лет. Надир-хан, захвативший фактическую власть в Иране, нанёс османской армии тяжёлое поражение при Baghavard близ Эривани; сердар Абдуллах Кёпрюлю-паша погиб на поле боя. После разгрома Эривань, Тифлис, Гянджа и Ширван были оставлены в течение нескольких месяцев. Восточная граница вернулась к линии Касре-Ширина 1639 года, как это будет подтверждено в 1746 году.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Потеря Бендер в пользу русских", "0daca453"], "d": ["После разгрома на равнине Кагул османская армия отошла к югу от Дуная, и крепости между Молдавией и Очаковом остались в одиночестве. Бендеры, державшие переход через Днестр, после двухмесячной осады были взяты штурмом; город был разграблен. Потеря крепости разорвала среднее звено северочерноморской оборонительной линии, затем пали также Аккерман и Килия. Бендеры будут возвращены по Кючук-Кайнарджи, но в 1806 году будут потеряны вновь.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Переход эмирата Сабах в Кувейте под османское покровительство", "3584dba0"], "d": ["По статье TDV о Кувейте, гавань основало в начале XVIII века племя Утуб, пришедшее из Неджда, а семья Сабах приняла управление ближе к концу века. В те же годы, когда Эль-Хаса перешла в руки Саудов, эмират, у которого перед ваххабитским давлением не оставалось иного выбора, кроме как опереться на Басру, перешёл под османское покровительство. Связь будет оформлена в 1871 году устройством Басры Мидхат-паши, и Кувейт будет считаться одной из трёх каз санджака Басра; последующее территориальное притязание Ирака также опирается на эту запись.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Потеря Мекки в пользу ваххабитов", "2da23acd"], "d": ["Ваххабитское движение, родившееся в Неджде, при Сауде ибн Абд аль-Азизе повернуло на Хиджаз; после Таифа и Медины Мекка была принята вторично — мекканский эмир шариф Галиб сдал город ваххабитам при условии сохранения за собой эмирата. Гробницы были разрушены, а путь паломнических караванов из Дамаска и Каира перерезан; прервалась и сурра, ежегодно отправлявшаяся падишахом в Две святыни, — единственным исключением из этой выплаты, продолжавшейся без перерыва до 1915 года, является период ваххабитского господства. Поскольку звание покровителя Двух святынь было одной из основ законности падишаха, эта потеря, помимо территориальной, стала тяжёлым политическим ударом; возвращение её потребует семи лет и станет возможным лишь с армией Мухаммеда Али из Кавалы.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Конец Дубровницкой республики — французская оккупация", "f8e27bf1"], "d": ["Французы, обосновавшиеся на далматинском побережье по договору Кампо-Формио (1797), 27 мая 1806 года заняли Дубровник и положили конец небольшой торговой республике. Так закончился трёхвековой зависимый статус Дубровника, сохранявшего с 1458 года автономию и торговые привилегии выплатой дани Османам; город и остров Млет республики на карте переходят под непосредственное французское управление.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Потеря Сухума в пользу русских — открытие восточного берега Чёрного моря", "adc96bd4"], "d": ["В османско-русской войне 1806–1812 годов русский флот направился к восточному берегу Чёрного моря и взял Сухум-Кале, на котором держалось османское господство в Абхазии. Крепость была центром связи с кавказскими племенами и прибрежной торговли. С её потерей Россия впервые прочно обосновалась на восточном берегу Чёрного моря; османское влияние на Кавказе было стеснено районом Анапы и Поти.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Оставление Парги османскому управлению", "66e0cc5d"], "d": ["Парга с 1401 года находилась в руках Венеции и никогда не входила в османское управление; после падения Венеции она перешла последовательно к Франции и Англии. Статья TDV об Али-паше Тепеленском резюмирует положение так: город сдался англичанам и лишь в 1819 году был оставлен управлению Али-паши. Передача привела к тому, что большая часть жителей переселилась на Ионические острова. Так последний из трёх — Превеза, Парга и Воница, — оставленных Венеции по Пожаревацкому миру, также был присоединён к империи; Парга пробудет османской девяносто четыре года.", "555a1119"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Переход Коринфа к греческим повстанцам", "892dcdc6"], "d": ["Во время греческой войны за независимость Акрокоринф перешёл в руки повстанцев, а комендант крепости Камиль-бей был взят в плен.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Потеря Нафплиона (Anabolu) в пользу повстанцев", "1a67fa50"], "d": ["Нафплион, порт Мореи с сильнейшими укреплениями, сдался из-за голода после более чем годичной блокады. Крепость с самого начала восстания была последней большой опорой османского контроля на полуострове; с её потерей вся Морея оказалась в руках повстанцев. Город вскоре станет первой столицей нового греческого государства.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-01:0":{"b": ["Переход Лепанто под греческое управление", "c9d19d4b"], "d": ["Лепанто на северном берегу Коринфского залива, остававшееся в османских руках до греческого восстания, было потеряно в апреле 1829 года и вошло в греческое управление; название городка было заменено на античное Навпакт. Мусульманское и еврейское население города полностью исчезло, и он превратился в небольшой городок.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Французское завоевание Алжира — конец трёхвековой оджакской власти", "0be8f568"], "d": ["Под предлогом инцидента с опахалом, возникшего из спора о долге, Франция три года держала алжирское побережье в блокаде, а затем высадила войска у Sidi Ferruc. По окончании трёхнедельной кампании дей Хусейн сдался, и просуществовавший с 1516 года османский Алжирский оджак прекратил существование. Завоевание не ограничилось столицей: в то же лето были потеряны внутренние города Тлемсен, Шершель и Медеа. Взятие под французский контроль всего побережья заняло ещё двадцать четыре года.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Передача Негропонта Греции — вместе с островом (Каристос, Орей)", "7b524aa4"], "d": ["Негропонт, бывший ареной ожесточённых боёв в течение войны за независимость Греции, но оставшийся в османских руках, после вступления в силу мирного договора в 1831 году был передан грекам. Мусульманское население города, бывшего важной морской базой с 1470 года, распродав всё имущество по очень дешёвым ценам, переселилось в османские земли целиком; город долго оставался пустым, а немецкий путешественник Фальмерайер в 1842 году назвал его призрачным городом.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Взятие Орана французами", "a8415d66"], "d": ["Оран, без боя переданный Испанией в 1792 году, был крупнейшим портом на западе Алжира. Через шесть месяцев после падения столицы французские войска вошли в город. Начатое отсюда наступление на запад вскоре столкнулось с пятнадцатилетним сопротивлением эмира Абд аль-Кадира.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Взятие Аннабы (Бона)", "21f37fb1"], "d": ["Аннаба — порт на востоке Алжира близ границы с Тунисом — была занята французскими силами и превращена в базу для похода на Константину. Город был также ближайшим африканским портом напротив острова Сардиния.", "1ca5b213"]},
"OLAYLAR_EK6:1833-03-31:0":{"b": ["Передача Афин новому греческому государству", "98af5572"], "d": ["Афины, принадлежавшие османам с 1456 года, в ходе греческой войны за независимость несколько раз переходили из рук в руки; гарнизон на Акрополе в 1827 году вновь оказался под османским контролем. Поскольку город остался севернее границы, проведённой Лондонским протоколом, он был передан новому королевству, а гарнизон оставил Акрополь. На следующий год Афины были объявлены столицей Греции вместо Нафплиона.", "6fca14a0"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Взятие Беджаи (Бужи)", "a8927e00"], "d": ["Порт Беджая, где горы Кабилии выходят к морю, был последним независимым звеном береговой линии между Алжиром и Аннабой. Он был взят при поддержке морской артиллерии; однако горная местность в его тылу ещё тридцать лет не переходила под французский контроль. Эти прибрежные захваты составляют постепенное, год за годом, сокращение османского Алжира на карте.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Взятие Сетифа", "2073731a"], "d": ["После падения Константины годом ранее французские войска вышли на плато, взяли древнеримский город Сетиф и основали там постоянный гарнизон. Сетиф находился на пересечении караванных путей между побережьем и Сахарой; его занятие показало, что Франция начала контролировать уже не только порты, но и внутреннюю торговую сеть.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Взятие Бискры — потеря ворот Сахары", "d895cad0"], "d": ["Бискра была воротами в Сахару у южных склонов Атласских гор и центром пальмовых оазисов. Благодаря её взятию в годы, когда сопротивление эмира Абд аль-Кадира начало ломаться, французский контроль впервые достиг северного края пустыни. Дальше предстояла пустынная кампания, продвигавшаяся от оазиса к оазису.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Взятие Туггурта — потеря всего Алжира", "33c056e2"], "d": ["Со взятием оазисного города Туггурт на севере Сахары начавшееся в 1830 году завоевание было завершено в северной половине нынешнего Алжира. Османское государство в эти годы воевало в Крымской войне на одной стороне с Францией; формально никогда не отказавшись от своих юридических притязаний на Алжир, фактически оно не смогло сделать ни одного шага. Единственной оставшейся в Северной Африке территорией была Триполитания.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Падение Эль-Обейда — переход Кордофана к силам Махди", "58299f62"], "d": ["Движение, начатое объявившим себя махди Мухаммадом Ахмадом, быстро распространилось против египетского управления в Судане. Эль-Обейд, центр Кордофана, пал после четырёхмесячной осады и стал столицей восстания; сокровищница и оружейные склады города позволили движению превратиться в армию. Судан юридически был землёй Египетского хедивата, всё ещё зависевшего от Османской империи, поэтому эта потеря на карте выпадает из тела империи.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Падение Хартума — потеря всего Судана", "d4b98464"], "d": ["После десятимесячной осады силы Махди вошли в Хартум, расположенный там, где сливаются Голубой и Белый Нил; правитель города Гордон был убит, а отправленный на помощь английский отряд опоздал на два дня. После этой даты весь Судан, включая Сеннар, Донголу и Кордофан, четырнадцать лет оставался под управлением государства Махди. Область лишь в 1899 году перешла под совместное англо-египетское управление, когда османская связь была уже полностью разорвана.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Итальянская оккупация Массауа — потеря западного берега Красного моря", "c333b95b"], "d": ["Порт Массауа, центр эялета Хабеш, был занят Италией, воспользовавшейся хаосом, в который восстание Махди ввергло Судан; он стал ядром итальянской Эритреи. Суакин на севере и архипелаг Дахлак в открытом море были потеряны в ходе того же процесса. Так закончилось османское господство на западном берегу Красного моря, длившееся со времён султана Селима I Грозного, и море перестало быть водоёмом, оба берега которого принадлежали османам.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Итальянская оккупация Родоса", "e08662c5"], "d": ["Италия, желая усадить Османское государство за стол переговоров в ходе Триполитанской войны, перенесла войну в Средиземное море и высадила войска на Родосе. Остров был занят за несколько дней. Родос, взятый Кануни после долгой осады в 1522 году и удерживавшийся триста девяносто лет, тем самым перестал быть крупнейшей островной базой империи в восточной части Средиземного моря; хотя по Договору в Уши оккупация считалась временной, вернуть его больше не удалось.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Итальянская оккупация Додеканеса", "200aacf2"], "d": ["В течение недели после взятия Родоса итальянский флот занял и окрестные острова; этому архипелагу впоследствии дадут имя «Додеканес». Большинство островов находилось в нескольких милях от анатолийского берега и контролировало юго-восточный проход Эгейского моря. По Договору в Уши оккупация считалась временной в обмен на оставление Триполитании, однако Италия так и не освободила острова; в 1947 году они будут переданы Греции.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Оккупация Коса", "ab246c62"], "d": ["Кос — последнее звено кампании на Додеканесе — был плодородным и густонаселённым островом прямо напротив полуострова Бодрум. С его оккупацией все острова юго-восточного угла Эгейского моря оказались под итальянским контролем, а юго-западный берег Анатолии на всём протяжении был окружён чужой цепью островов.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Провозглашение независимости Икарии", "c4452033"], "d": ["На небольшом острове Икария между Самосом и Хиосом население, восставшее в обстановке неопределённости, вызванной итальянскими оккупациями, изгнало с острова османскую жандармерию и провозгласило «свободное государство» со своим флагом, почтовыми марками и собранием, просуществовавшее пять месяцев. В ноябре 1912 года остров присоединился к Греции. Несмотря на малые размеры, это событие ясно показывает, как распадалась центральная власть в Эгейском море.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Выход Самоса из-под османского управления", "3a862f2b"], "d": ["Самос с 1832 года был автономным княжеством, платившим дань Османской империи и управляемым князем, назначавшимся из Стамбула. В вакууме, созданном Триполитанской войной, движение сторонников объединения с Грецией взяло власть, и порядок автономного княжества фактически прекратил существование; в том же году остров объявил о присоединении к Греции. Этот остров, находящийся в двух километрах от анатолийского берега, оказался одной из первых территорий, потерянных в Эгейском море.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Падение Янины — потеря Эпира и Парги", "d42fce18"], "d": ["Янина, осаждённая в ходе Балканской войны на протяжении пяти месяцев, сдалась после падения позиций Бизани; вместе с городом к Греции перешёл весь Эпир. Парга, входившая в санджак Янина, также была потеряна в эту дату, и девяносто четыре года османского управления закончились. Потеря Янины означала закрытие последнего окна империи к Адриатике.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Падение Эдирне к болгарам", "459d2e56"], "d": ["После осады, длившейся пять с половиной месяцев, Эдирне, у которого закончились боеприпасы и провиант, сдался; Шюкрю-паша был взят в плен. Падение города, принадлежавшего османам с 1361 года и девяносто два года служившего столицей, было сочтено самым тяжёлым ударом Балканской войны. Через четыре месяца, во Второй Балканской войне, Эдирне будет возвращён, когда Болгария потерпит крах на других фронтах.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Потеря Янбу в пользу сил шарифа Хусейна", "e291c816"], "d": ["Начатое шарифом Хусейном в июне восстание распространилось на берег Красного моря; Янбу, порт Медины, при поддержке английского флота перешёл в руки повстанцев. Порт стал главными воротами притока оружия и денег извне для восстания. Тем самым сообщение войск Фахреддина-паши в Медине с морем было прервано, и город остался в одиночестве на конце Хиджазской железной дороги.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Третье сражение за Газу — потеря Газы и Хан-Юниса", "c142a069"], "d": ["После двух неудачных попыток Алленби в третьем наступлении прорвал фронт, обойдя его со стороны Беэр-Шевы, и линия Газы, удерживавшаяся шесть месяцев, рухнула. Газа и лежащий к югу от неё Хан-Юнис были оставлены в один день. Этот прорыв стал началом развала Палестинского фронта; Иерусалим падёт через пять недель.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Занятие Комотини — потеря Западной Фракии", "904d813c"], "d": ["Западная Фракия, после Мудроса сначала оказавшаяся под контролем войск Антанты, по решению конференции в Сан-Ремо была отдана Греции, и греческая армия вошла в Комотини. Область, возвращённая от Болгарии в 1913 году, стала последней территорией, потерянной империей в Румелии. Статус турецкого населения региона будет урегулирован три года спустя в Лозанне режимом меньшинств.", "e3d0605f"]},
"OLAYLAR_EK7:1335-12-01:0":{"b": ["Распад государства Хулагуидов: смерть Абу Саид Бахадур-хана", "0f187469"], "d": ["По статье «Ильханы» в TDV İslâm Ansiklopedisi, смерть Абу Саида, не оставившего наследника, привела к распаду государства Хулагуидов, целый век господствовавшего в Иране; эмиры, воспользовавшись борьбой за престол, основали местные династии, такие как Джалаириды, Кара-Коюнлу, Музаффариды, сарбадары Хорасана и бейлик Эретна. Этот распад разделил регион на мозаику бейликов, которая продлится век; в конечном итоге он будет вновь объединён походами Тимура.", "ebf54b53"]},
"OLAYLAR_EK7:1387-11-01:0":{"b": ["Тимур подчинил себе большую часть Ирана", "1cee2b82"], "d": ["По статье «Тимур» в TDV İslâm Ansiklopedisi, Тимур, с начала 1380-х годов один за другим ликвидировавший послеильханидские местные династии, такие как сарбадары, Кертиды и Музаффариды, в ходе «трёхлетнего похода» 1386–1388 годов фактически подчинил себе большую часть Ирана; окончательный конец династии Музаффаридов будет положен в 1393 году. Так регион после векового раздробления вновь был объединён под единой центральной властью.", "aaab87fe"]},
"OLAYLAR_EK7:1406-10-15:0":{"b": ["Победа на Араксе: Кара Юсуф разбил тимурида Абу Бекр-мирзу", "4b61a75a"], "d": ["После смерти Тимура в 1405 году вернувшийся из изгнания предводитель Кара-Коюнлу Кара Юсуф, взяв Avnik и вновь овладев своими землями в Восточной Анатолии, двинулся на внука Тимура Абу Бекр-мирзу, считавшегося владетелем Азербайджана и двух Ираков, и разбил его на берегу Аракса. Эта победа не отдала Тебриз Кара-Коюнлу: TDV `tebriz` пишет, что в 1408 году город находился в руках Абу Бекр-мирзы; битва, давшая Азербайджан, — это Serdrûd 13 апреля 1408 года.", "38fdfcfd"]},
"OLAYLAR_EK7:1408-04-13:0":{"b": ["Победа при Serdrûd: Тебриз и Азербайджан перешли к Кара-Коюнлу", "1f0a429d"], "d": ["Кара Юсуф разбил тимурида Абу Бекр-мирзу вторично после Аракса, при Serdrûd близ Тебриза; эта победа дала Кара-Коюнлу Азербайджан. Затем Кара Юсуф поручил Бистам-бею завоевание Ирака-и Аджами;", "10fb176b"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Эпидемия чумы в Стамбуле и перенос двора в Эдирне", "70c7a163"], "d": ["Согласно статье «Стамбул» в TDV İslâm Ansiklopedisi, быстрое и плотное заселение города время от времени создавало почву для распространения эпидемических болезней; во время эпидемии чумы 1466 года двор и государственные сановники временно удалились в Эдирне. Население города при таких эпидемиях несло серьёзные потери.", "7b20238c"]},
"OLAYLAR_EK7:1469-04-01:0":{"b": ["Узун-Хасан положил конец государству Кара-Коюнлу", "ef68399e"], "d": ["По статье «Узун-Хасан» в TDV İslâm Ansiklopedisi, правитель Ак-Коюнлу Узун-Хасан разбил и убил правителя Кара-Коюнлу Джаханшаха в окрестностях Bingöl-Sancak 12 раби ас-сани 872 года / 10 ноября 1467; сын Джаханшаха Хасан Али был разбит при Merend в сентябре 1468 года и убит перед Хамаданом в апреле–мае 1469 года, и тем самым окончательно было покончено с государством Кара-Коюнлу. Земли перешли под власть Ак-Коюнлу; государство в следующее десятилетие расширится до внутренних областей Ирана.", "8b916ceb"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Открытие медресе Sahn-ı Semân для обучения", "021f2a83"], "d": ["Согласно статье «Sahn-ı Semân» в TDV İslâm Ansiklopedisi, эти восемь медресе, основанные в составе комплекса Фатих, были задуманы как высшее учебное заведение своей эпохи и составили вершину османской иерархии ильмийе. Должность мударриса и окончание этого медресе в последующие века считались самой почётной ступенью в карьере кади и мударриса.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Завершение строительства дворца Топкапы (Saray-ı Cedîd)", "d2db6323"], "d": ["Согласно статье «Топкапы» в TDV İslâm Ansiklopedisi, источники эпохи расходятся относительно начала и конца строительства; по дате 883 (1478) на надписи ворот Bâb-ı Hümâyun, строительство, начатое по приказу Мехмеда II Завоевателя, вероятно, в 1465 году, к этому году было в основном завершено, и дворец занял место государственного центра в старом дворце. Так падишах переехал в новую резиденцию, которой предстояло на три века стать административным и церемониальным сердцем государства.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Воцарение Баязида II в Стамбуле", "9b686d04"], "d": ["Согласно статье «Баязид II» в TDV İslâm Ansiklopedisi, шехзаде Баязид, санджакбей Амасьи, узнав о смерти отца, быстро прибыл в Стамбул и взошёл на престол; выступление его брата Джема из Коньи он опередил при поддержке янычар. При воцарении янычарам была роздана обычная награда за воцарение. Эта смена на троне запалила фитиль и борьбы между двумя братьями.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Провозглашение Джема султаном в Бурсе", "b355168a"], "d": ["Согласно статье «Султан Джем» в TDV İslâm Ansiklopedisi, Джем, дойдя до Бурсы через Караман, овладел городом, провозгласил себя султаном и велел читать хутбу. Это недолгое султанство закончилось тем, что посланные старшим братом Баязидом II силы разбили Джема под Yenişehir. После поражения Джем был вынужден бежать в сторону Египта.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Казнь Гедик Ахмед-паши", "6d75a58c"], "d": ["Согласно статье «Гедик Ахмед-паша» в TDV İslâm Ansiklopedisi, паша, известный походом на Отранто и великим визират, был казнён в Эдирне по приказу Баязида II из-за позиции в деле султана Джема и опасений по поводу его влияния. Смерть одного из самых опытных полководцев эпохи Мехмеда II Завоевателя вызвала широкий отклик во дворце.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Основание первой типографии в Стамбуле", "04475930"], "d": ["Согласно статье «Типография» в TDV İslâm Ansiklopedisi, еврейские эмигранты из Испании, братья Давид и Самуил ибн Нахмиас, основали в Стамбуле первую типографию, печатавшую еврейским шрифтом. Она осталась в истории как первое типографское предприятие, действовавшее на османских землях; печать турецким арабским шрифтом стала возможной гораздо позже, в XVIII веке.", "118df98b"]},
"OLAYLAR_EK7:1501-07-01:0":{"b": ["Взятие Тебриза шахом Исмаилом: основание государства Сефевидов", "014d81e6"], "d": ["По статьям «Сефевиды» и «Ак-Коюнлу» в TDV İslâm Ansiklopedisi, юный шейх ардебильской обители Исмаил с армией, составленной из анатолийских мюридов-кызылбашей, нанёс тяжёлое поражение султану Ак-Коюнлу Алванду в районе Нахичевани; Алванд бежал в Диярбекир, Исмаил вошёл в Тебриз, взошёл на престол и объявил официальной верой двенадцатиимамский шиизм. Так закончились и владычество Ак-Коюнлу, и эпоха постильханидских бейликов региона; было основано государство Сефевидов, которому предстояло просуществовать три века.", "d6b169b7"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Землетрясение «Малый Судный день» в Стамбуле", "53e3b1d6"], "d": ["Согласно статье «Стамбул» в TDV İslâm Ansiklopedisi, сильное землетрясение, поразившее город, в народе было названо «Малым Судным днём»; крепостные стены, мечети и многие здания были тяжело повреждены, было много человеческих жертв. По приказу Баязида II в городе была начата широкая кампания восстановления и благоустройства.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Начало восстания Шахкулу", "3d9a4a90"], "d": ["Согласно статье «Шахкулу Баба Текели» в TDV İslâm Ansiklopedisi, Шахкулу, питавшийся сефевидской пропагандой, собрал вокруг себя широкие туркменские массы в области Теке и поднял крупное восстание религиозно-общественного характера. Восстание, один из самых серьёзных кризисов внутренней безопасности эпохи, глубоко потрясло центральную власть государства.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Смерть Баязида II на пути в Дидимотихон", "c46e98c9"], "d": ["Бывший падишах, покинувший Стамбул после отречения, чтобы отправиться в родной город Дидимотихон, во время движения в носилках, проходивших в день лишь 5–6 км, занемог в селе Abalar близ Чорлу и скончался 25 раби аль-авваля 918 года (10 июня 1512). TDV İslâm Ansiklopedisi считает причину смерти очень подозрительной; указывается на вероятность отравления согласно некоторым местным и иностранным источникам. После тридцатиоднолетнего правления так умер восьмой падишах из рода Османа Гази.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Казнь шехзаде Ахмеда по приказу Селима I Грозного", "65abb2f2"], "d": ["Согласно статье «Селим I» в TDV İslâm Ansiklopedisi, шехзаде Ахмед, любимец отца Баязида II и главный соперник за престол, потерпел поражение на равнине Yenişehir в борьбе, начатой после воцарения брата Селима, и был схвачен и убит при бегстве с поля боя. Этим событием Селим в значительной мере положил конец борьбе за престол между братьями и племянниками.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["Ибрахим-паша назначен великим визирем", "9c94c1e3"], "d": ["Согласно статье «Ибрахим-паша, Макбул» в TDV İslâm Ansiklopedisi, Ибрахим-паша, возвышенный из хас-одабаши в бейлербеи Румелии и в тот же день в великие визири, стал великим визирем 13 шаабана 929 года (27 июня 1523). Это было беспрецедентное назначение прямо со дворцовой службы на пост великого визиря, показывавшее исключительную близость Ибрахим-паши к Кануни.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Барбаросса Хайреддин-паша назначен капудан-пашой", "a0ff6bab"], "d": ["Согласно статье «Барбаросса Хайреддин-паша» в TDV İslâm Ansiklopedisi, Хайреддин-паша, известный успехами в Алжире, 6 апреля 1534 года был вызван в Стамбул и назначен капудан-пашой и бейлербеем Архипелага (Cezayir-i Bahr-i Sefîd). Это назначение считается началом перестройки османского флота и институционализации морской мощи в Средиземном море.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Рустем-паша впервые стал великим визирем", "ddfcc014"], "d": ["Согласно статье «Рустем-паша» в TDV İslâm Ansiklopedisi, после смещения Хадым Сулейман-паши из-за разногласий с одним из визирей Рустем-паша был назначен великим визирем 17 рамадана 951 года (2 декабря 1544). Благодаря браку с Михримах-султан приблизившийся ко двору Рустем-паша с этим назначением стал одним из самых влиятельных государственных деятелей эпохи Кануни.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Эбуссууд-эфенди стал шейх-уль-исламом", "11ed04f8"], "d": ["Согласно статье «Эбуссууд-эфенди» в TDV İslâm Ansiklopedisi, Эбуссууд-эфенди, восемь лет бывший кадиаскером Румелии, был назначен шейх-уль-исламом в шаабане 952 года (октябре 1545) и оставался на этом посту двадцать восемь лет и одиннадцать месяцев. Известный фетвами, согласовывавшими кануны Кануни с шариатским правом, Эбуссууд-эфенди сыграл решающую роль в формировании правовых и образовательных учреждений своего времени.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Смерть Барбароссы Хайреддин-паши", "3378a0bf"], "d": ["Согласно статье «Барбаросса Хайреддин-паша» в TDV İslâm Ansiklopedisi, после непродолжительной болезни он скончался в Стамбуле 6 джумада аль-уля 953 года (5 июля 1546). Его смерть, погребение в тюрбе рядом с построенным им самим медресе в Бешикташе, рассматривалась как конец эпохи в установленном османским флотом господстве в Средиземном море.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Начало строительства мечети и комплекса Сулеймание", "101ec36f"], "d": ["Согласно статье «Мечеть и комплекс Сулеймание» в TDV İslâm Ansiklopedisi, комплекс, фундамент которого был заложен в 1550 году под руководством главного архитектора Мимара Синана, был задуман как большой социальный комплекс, состоящий помимо мечети из медресе, даруш-шифа, имарета и библиотеки. Строительство было одной из крупнейших строительных программ, символизировавших мощь царствования Кануни и благоустройство Стамбула.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["В Стамбуле и его окрестностях началась новая волна чумы", "547d6bf6"], "d": ["Согласно статье «Чума» в TDV İslâm Ansiklopedisi, одна из эпидемий XVI века, поразивших исламский мир, пришлась на 1552–1566 годы и особенно сильно затронула Стамбул, Анатолию, Румелию, Египет и Северную Африку. Расширение торговых путей и рост подвижности населения причисляются к факторам, облегчавшим распространение эпидемий в период наибольшего могущества империи.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Кара Ахмед-паша назначен великим визирем", "a7d7748e"], "d": ["Согласно статье «Кара Ахмед-паша» в TDV İslâm Ansiklopedisi, Кара Ахмед-паша, служивший вторым визирем, после внезапного смещения действующего великого визиря был возведён в великие визири 27 шавваля 960 года (5 октября 1553). Эта перемена указывает на время, совпавшее с казнью шехзаде Мустафы, когда баланс сил внутри дворца быстро переходил из рук в руки.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Казнён капудан-паша Пири Рейс", "3b2ad7a0"], "d": ["Согласно статье «Пири Рейс» в TDV İslâm Ansiklopedisi, когда в Египет дошли обвинения в том, что при снятии осады Ормуза он за взятку разграбил имущество мусульман и бросил свою армию на поле боя, знаменитый мореплаватель и картограф был казнён в Каире в конце 960 года (в конце 1553). Смерть Пири Рейса, чьё имущество было конфисковано, рассматривается как результат соперничества пашей в морской политике эпохи в Басре и Индийском океане.", "c410d0ce"]},
"OLAYLAR_EK7:1555-09-29:0":{"b": ["Кара Ахмед-паша казнён, Рустем-паша вновь стал великим визирем", "9a85076a"], "d": ["Согласно статьям «Рустем-паша» и «Кара Ахмед-паша» в TDV İslâm Ansiklopedisi, на место внезапно казнённого 13 зуль-када 962 года (29 сентября 1555) во время заседания дивана Кара Ахмед-паши в тот же день вторично был назначен великим визирем Рустем-паша при поддержке султанш Хюррем и Михримах. Закулисье этого происшествия в источниках оставлено неясным; оно оценивается как результат дворцовых интриг.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["Умерла Хюррем-султан", "1ae998b5"], "d": ["Согласно статье «Хюррем-султан» в TDV İslâm Ansiklopedisi, Хюррем-султан, многие годы имевшая большое влияние во дворце как хасеки-султан Кануни, скончалась в Стамбуле 26 джумада ас-сани 965 года (15 апреля 1558) и была погребена в своей тюрбе в комплексе мечети Сулеймание. Смерть Хюррем-султан, укрепившей свою власть над гаремом после смерти валиде-султан Хафсы в 1534 году, устранила и уравновешивавшее влияние, сдерживавшее борьбу за престол между её сыновьями Баязидом и Селимом.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["Соколлу Мехмед-паша возведён в великие визири", "896391a2"], "d": ["Согласно статье «Соколлу Мехмед-паша» в TDV İslâm Ansiklopedisi, Соколлу Мехмед-паша, ставший великим визирем после смерти Семиз Али-паши 30 зуль-када 972 года (29 июня 1565), был последним великим визирем Кануни и продолжал занимать этот пост при Селиме II и Мураде III, став одним из великих визирей, дольше всех служивших в османской истории.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["Селим II прибыл в Стамбул и взошёл на престол", "0289ef97"], "d": ["После смерти Кануни Сулеймана в Сигетваре известие, чтобы не нарушить порядок, неделями держалось в тайне Соколлу Мехмед-пашой. По TDV İslâm Ansiklopedisi, Селяники называет датой прибытия Селима в Стамбул 15 раби аль-авваля 974 года (30 сентября 1566), тогда как большинство современных историков считают верным 9 раби аль-авваля (24 сентября). О смерти Кануни официально было объявлено лишь 24–25 октября 1566 года в Белграде.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["Спущен на воду флот, воссозданный Кылыч Али-пашой", "d0fc9f48"], "d": ["После тяжёлого поражения при Лепанто (7 октября 1571) всю зиму на верфях строились корабли. По TDV İslâm Ansiklopedisi, 1 сафара 980 года (13 июня 1572) новый флот, состоявший из 250 галер и около 300 добровольных рейсов-командиров гребных судов, был торжественно спущен на воду.", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["Соколлу Мехмед-паша убит в результате покушения", "6ffa8dec"], "d": ["Соколлу Мехмед-паша, четырнадцать лет бывший великим визирем при трёх падишахах, был заколот кинжалом 20 шаабана 987 года (12 октября 1579) дервишем, подошедшим, словно чтобы подать прошение, к вечернему дивану в его доме. По TDV İslâm Ansiklopedisi, обсуждается, что покушение могло быть связано с местью за казнённого шейха хамзавийя Хамзу Бали.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["Первый торговый ahidnâme с Англией — англичанам дарованы капитуляции", "59c8e3ee"], "d": ["Присланный в Стамбул в октябре 1578 года английский представитель Уильям Харборн при поддержке Соколлу Мехмед-паши и Ходжи Садеддина-эфенди получил от Мурада III ahidnâme 1580 года. Согласно этому ahidnâme английские купцы получили право пользоваться в той же степени торговыми привилегиями (капитуляциями), ранее предоставленными французам и венецианцам. Между королевой Елизаветой I и Мурадом III были обменены письма, и между двумя государствами установились официальные отношения. Сразу после этих привилегий в 1581 году в Лондоне была основана Левантийская компания; англичане вели свою торговлю в регионе через эту компанию до 1825 года.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["Стамбульская обсерватория разрушена по хатт-ы хумаюну", "3bc0c78c"], "d": ["Под влиянием фетвы о том, что обсерватории приносят странам несчастье, и оппозиции во дворце, Стамбульская обсерватория была разрушена вместе со всеми приборами хатт-ы хумаюном от 4 зуль-хиджа 987 года (22 января 1580). По TDV İslâm Ansiklopedisi, это стало недолговечным концом учреждения, основанного Такиюддином ар-Расидом.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["Начало обрезальных празднеств шехзаде Мехмеда на Ипподроме", "c2926d5d"], "d": ["Сын Мурада III шехзаде Мехмед был обрезан с великолепными церемониями, начавшимися 6 джумада аль-уля 990 года (29 мая 1582) и продолжавшимися пятьдесят шесть–пятьдесят семь дней. По TDV İslâm Ansiklopedisi, празднества, устроенные на Ипподроме, были одним из самых пышных дворцовых торжеств своего времени.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["Скончалась валиде-султан Нурбану", "77d0a577"], "d": ["Мать Мурада III Нурбану-султан скончалась 22 зуль-када 991 года (7 декабря 1583). По TDV İslâm Ansiklopedisi, как валиде-султан она вела переписку с дворами Венеции и Франции, а венецианский сенат в том же году согласился отправить ей в благодарность за услуги подарок стоимостью 2000 венецианских золотых.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["Из-за порчи акче разразился Бейлербейский бунт", "db2f2e61"], "d": ["Когда государство стало платить, понизив содержание серебра в акче, сипахи и янычары окружили дворец и подняли кровавое восстание, вошедшее в историю под названием Бейлербейского бунта. Согласно статье «Абдулькадир Шейхи-эфенди» в TDV İslâm Ansiklopedisi, шейх-уль-ислам в связи с этим событием был смещён.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["Мехмед III взошёл на престол, девятнадцать шехзаде задушены", "2cd9a8c5"], "d": ["Мехмед III после смерти отца Мурада III прибыл в Стамбул и взошёл на престол 16 джумада аль-уля 1003 года (27 января 1595), в пятницу. По TDV İslâm Ansiklopedisi, в ту же ночь были задушены девятнадцать шехзаде, из которых четверо были взрослыми (Мустафа, Баязид, Осман и Абдуллах); это было самое массовое братоубийство в османской истории.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["Султанша Сафийе приобрела влияние как валиде-султан", "000bec21"], "d": ["Жена Мурада III и мать Мехмеда III Сафийе-султан с воцарением сына поднялась до решающего положения во дворцовой политике в качестве валиде-султан. По TDV İslâm Ansiklopedisi, в этот период влияние, исходившее от гарема, достигло размеров прямого вмешательства в государственные дела.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["Мехмед III под давлением янычар лично отправился в поход", "d3c50656"], "d": ["Несмотря на возражения великого визиря Дамад Ибрахим-паши, под давлением янычар Мехмед III 20 июня 1596 года выступил из Стамбула в поход как первый после Кануни Сулеймана падишах, лично возглавивший армию. По TDV İslâm Ansiklopedisi, это означало возрождение старой традиции газы.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["Эпидемия чумы, начавшаяся в 1570-х годах, продолжала поражать Стамбул", "eb4ca37a"], "d": ["Согласно статье о чуме в TDV İslâm Ansiklopedisi, эпидемия, начавшаяся в 1570-х годах, продолжала действовать до начала XVII века и поразила прежде всего Стамбул, а также Анатолию, Балканы, Египет и Северную Африку. Эпидемические периоды были хронической угрозой, часто прерывавшей жизнь двора и города.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["Умер Карайазиджи Абдулхалим, повстанческое движение ослабело", "876ca7a6"], "d": ["Карайазиджи Абдулхалим, отступивший раненым после тяжёлого поражения, понесённого 12 августа 1601 года в Sepetli близ Эльбистана, умер в 1010 году (1602). По TDV İslâm Ansiklopedisi, весть о смерти дошла до Стамбула в рамадане 1010 года (феврале–марте 1602); источники указывают, что остаётся спорным, умер ли он от раны или был убит своими людьми.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["Фактическое прекращение обычая братоубийства", "9046c607"], "d": ["При воцарении Ахмед I, в отличие от прежних падишахов, не стал убивать брата шехзаде Мустафу и сохранил ему жизнь; это решение считается началом фактического принятия в османской системе наследования порядка экбер-ершед (старшинство в роде). Статья «Мустафа I» в TDV İslâm Ansiklopedisi сообщает, что после этой даты Мустафа вёл при дворе жизнь затворника. Эта практика фактически положила конец убийствам при воцарении, длившимся веками.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["Заложен фундамент мечети Султанахмет", "1683262f"], "d": ["По приказу Ахмеда I на Ипподроме торжественно был заложен фундамент мечети, которую должен был построить архитектор Седефкяр Мехмед-ага. По статье «Мечеть и комплекс Султан Ахмед» в TDV İslâm Ansiklopedisi, сооружение стало предметом критики своего времени тем, что это была первая крупная султанская мечеть, построенная прямо из казны, без победы в завоевательном походе. Комплекс был задуман так, чтобы наряду с мечетью включать медресе, имарет и тюрбе.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["Убийство Османа Младшего янычарами (Hâile-i Osmâniye)", "324f6582"], "d": ["Янычары и сипахи, восставшие из-за слухов о том, что под предлогом паломничества он выедет из Стамбула и намерен распустить янычарский оджак, низложили Османа II и велели задушить его в застенках Едикуле. По статье «Осман II» в TDV İslâm Ansiklopedisi, это первый случай в османской истории, когда падишах был открыто убит в результате военного мятежа, и он вызвал глубокий разлом в отношениях династии и войска. Его последние часы прошли так: когда попытка укрыться в доме янычарского аги Али-аги не удалась, падишах, по выражению TDV, «в ужасном виде, с непокрытой головой, в растерзанной одежде» был посажен на клячу и под тяжкими оскорблениями доставлен сначала в мечеть Орта, где находился Мустафа I, а после полудня того же дня в Едикуле; по мнению некоторых историков, чтобы доказать его смерть, ему отрезали ухо и нос и показали матери Мустафы I. После этого события Мустафа I был вторично возведён на престол. Событие, называемое «Hâile-i Osmâniye» (Османова катастрофа), навсегда нарушило баланс между дворцом и оджаком и положило начало спорам о легитимности, которые будут продолжаться весь век.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["Вторичное возведение Мустафы I на престол", "34a0b29a"], "d": ["После убийства Османа Младшего янычарами, поскольку в династии не оказалось других взрослых мужчин, Мустафа I был вторично возведён на престол. По статье «Мустафа I» в TDV İslâm Ansiklopedisi, и это второе султанство, как и предыдущее, прошло без возможности фактически вести государственные дела, и управление государством осталось в руках визирей и валиде-султан. Этот четырнадцатимесячный период закончился в 1623 году воцарением Мурада IV.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["Пожар Джибали", "3e42fb08"], "d": ["Начавшийся в Джибали и быстро распространившийся под действием ветра пожар обратил в пепел значительную часть Стамбула; по статье «Стамбул» в TDV İslâm Ansiklopedisi, источники эпохи сообщают, что сгорели тысячи домов. Связь пожара с деревянной застройкой и курением табака стала прямым основанием для вскоре объявленного Мурадом IV сурового запрета табака и кофеен. Катастрофа была лишь одним из повторявшихся в тогдашнем Стамбуле больших пожаров.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["Запрет Мурада IV на табак и кофейни", "5dd71297"], "d": ["После пожара Джибали Мурад IV из соображений пожарной безопасности и общественного порядка запретил курение табака и кофейни; нарушителям запрета применялись тяжёлые наказания, включая смертную казнь. По статье «Мурад IV» в TDV İslâm Ansiklopedisi, падишах проводил столь строгую политику внутренней дисциплины, что лично, переодевшись, обходил городские улицы, чтобы следить за исполнением запрета. Эти суровые меры оцениваются как часть усилий Мурада IV по восстановлению центральной власти.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["Эпидемия чумы в Стамбуле", "f33f58c5"], "d": ["В эпоху Мурада IV Стамбул был потрясён тяжёлой эпидемией чумы, поразившей значительную часть населения; торговля и повседневная жизнь в городе месяцами нарушались. Статья «Стамбул» в TDV İslâm Ansiklopedisi отмечает, что повторявшиеся в XVII веке эпидемии серьёзно влияли на демографический баланс города. Во время эпидемии двор и знать на какое-то время перебирались в загородные сады и кёшки.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["Крылатый полёт Хезарфена Ахмеда Челеби (предание)", "df474c04"], "d": ["По преданию, передаваемому Эвлией Челеби, Хезарфен Ахмед Челеби на сделанных им самим крыльях спрыгнул с Галатской башни и сумел долететь планируя до Ускюдара; хотя историческая достоверность спорна, он стал символом технического воображения. Падишах, сначала наградивший Хезарфена, впоследствии, из-за отклика, вызванного этим событием, отправил его в ссылку в Алжир.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["Усиление влияния Cinci Hoca Хусейн-эфенди при дворе", "41d21572"], "d": ["Заклинатель Хусейн-эфенди, вызванный во дворец для лечения душевных недугов падишаха Ибрахима, вскоре снискал доверие падишаха и поднялся до должности кадиаскера Анатолии. По статье «Хусейн-эфенди, Cinci Hoca» в TDV İslâm Ansiklopedisi, это влияние он использовал для накопления богатства и вмешательства в политические события эпохи. После смерти Ибрахима он был лишён всех должностей и казнён в 1648 году.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["Казнь Кеманкеш Мустафа-паши", "0ecc8030"], "d": ["Кеманкеш Мустафа-паша, бывший великим визирем с эпохи Мурада IV и принёсший казне значительный профицит финансовыми реформами, был задушен и казнён после того, как придворные соперники повлияли на Ибрахима и обвинили его в подстрекательстве к янычарскому мятежу. По статье «Кеманкеш Мустафа-паша» в TDV İslâm Ansiklopedisi, его казнь состоялась 21 зуль-када 1053 года / 31 января 1644: Кеманкеш Кара Мустафа-паша был задушен палачом Кара Али на Hocapaşa Çarşısı и погребён в собственной тюрбе у Çarşıkapı. Его смерть вспоминается как яркий пример нестабильности на посту великого визиря в ту эпоху и положила конец кратковременному периоду жёстких реформ.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["Решение дивана о Критском походе и выход флота", "9076827e"], "d": ["Решение о начале крупного похода на принадлежавший Венеции остров Крит было принято в Диван-ы хумаюн, и османский флот под командованием капудан-паши вышел из Стамбула к Криту. По статье «Крит» в TDV İslâm Ansiklopedisi, это решение стало политическим началом периода долгой осады и войны, который продлится около двадцати пяти лет. Начало похода, самого крупного внешнеполитического предприятия эпохи Ибрахима, вызвало широкие споры среди государственных мужей.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["Воцарение семилетнего Мехмеда IV", "a197a3bc"], "d": ["Сразу после низложения Ибрахима его семилетний сын Мехмед был возведён на престол и стал падишахом под титулом Мехмеда IV. По статье «Мехмед IV» в TDV İslâm Ansiklopedisi, столь юный возраст при воцарении обострил борьбу за влияние во дворце между бабушкой Кёсем-султан и матерью Турхан-султан. Эта борьба за власть закончится убийством Кёсем-султан в 1651 году.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["Реформа бездефицитного бюджета Тархунджу Ахмед-паши", "376fc7f2"], "d": ["Великий визирь Тархунджу Ахмед-паша, чтобы преодолеть финансовый кризис, вызванный годами длительных войн, провёл жёсткую программу экономии, затрагивавшую и дворцовые расходы, и составил первый известный в османской истории бездефицитный бюджет (проект Tarhuncu). По статье «Тархунджу Ахмед-паша» в TDV İslâm Ansiklopedisi, эта реформа принесла казне значительный профицит, но вызвала широкое недовольство в придворных кругах и высшей бюрократии. Это недовольство через год закончится его казнью.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["Çınar Vak'ası (Платановый инцидент; Vak'a-i Vakvakiye)", "4c6ed90f"], "d": ["По статье «Çınar Vak'ası» в TDV İslâm Ansiklopedisi, янычары и сипахи, вернувшиеся из Критского похода без выплаты жалованья, восстали в Стамбуле и потребовали казни государственных деятелей, которых обвиняли в коррупции. Предложение великого визиря Зурназен Мустафа-паши о конфискации и ссылке не было принято; сначала были казнены три чиновника, затем около тридцати государственных деятелей, и их тела были повешены на платанах на площади Султанахмет. Поэтому событие стало называться Çınar Vak'ası.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["Назначение Кёпрюлю Мехмед-паши великим визирем на условиях", "3a6b7f8f"], "d": ["По статье «Кёпрюлю Мехмед-паша» в TDV İslâm Ansiklopedisi, Кёпрюлю Мехмед-паша, которому было почти восемьдесят лет, принял печать лишь после того, как добился принятия выдвинутых перед валиде Турхан-султан и Мехмедом IV тяжёлых условий — не вмешиваться в его назначения и не верить сказанному против него. Он приступил к должности 26 зуль-када 1066 года на место Бойнуэгри Мехмед-паши и принялся жёстко восстанавливать государственную дисциплину.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["Подавление движения кадизаделиев Кёпрюлю Мехмед-пашой", "5ec3ce84"], "d": ["По статье «Кадизаделии» в TDV İslâm Ansiklopedisi, Кёпрюлю Мехмед-паша, едва приступив к должности, занялся религиозным конфликтом между окружением Кадизаде Мехмед-эфенди и приверженцами тарикатов. Посоветовавшись с улемами, он издал указ о казни лидеров движения Устювани Мехмед-эфенди, Тюрк Ахмеда и Диване Мустафы, но это наказание было заменено ссылкой, и все трое были отправлены на Кипр; так закончилась вторая фаза движения.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["Большой пожар в Стамбуле: сгорел Ağakapısı", "b9253b66"], "d": ["По статье «Ağakapısı» в TDV İslâm Ansiklopedisi, во время большого пожара, вспыхнувшего в июле 1660 года в эпоху Мехмеда IV, Ağakapısı, официальная ставка янычарского аги, сгорел полностью и впоследствии был отстроен заново. Этот пожар был одним из больших городских пожаров, неоднократно поражавших тогдашний Стамбул.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["Назначение Кёпрюлюзаде Фазыл Ахмед-паши великим визирем", "c1999b5c"], "d": ["По статье «Кёпрюлюзаде Фазыл Ахмед-паша» в TDV İslâm Ansiklopedisi, после смерти отца Кёпрюлю Мехмед-паши он был назначен великим визирем 8 раби аль-авваля 1072 года (1 ноября 1661). Фазыл Ахмед-паша, в отличие от отца известный мягким нравом, благочестием и покровительством учёным и художникам, за более чем пятнадцатилетнее великое визирство основал библиотеки и благотворительные учреждения в Стамбуле и на завоёванных землях.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["Назначение Вани Мехмед-эфенди проповедником Новой мечети и наставником падишаха", "7ea6aaae"], "d": ["По статье «Мехмед-эфенди, Вани» в TDV İslâm Ansiklopedisi, Вани Мехмед-эфенди, вызванный в Стамбул с приходом к посту великого визиря Кёпрюлюзаде Фазыл Ахмед-паши и представленный Мехмеду IV, вскоре снискал близкое внимание падишаха. В 1665 году он был назначен проповедником Новой мечети (Yeni Cami) и наставником падишаха и стал одним из самых влиятельных духовных лиц дворца.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["Назначение Мерзифонлу Кара Мустафа-паши великим визирем", "3d1e836c"], "d": ["По статье «Мерзифонлу Кара Мустафа-паша» в TDV İslâm Ansiklopedisi, после смерти Фазыл Ахмед-паши он был назначен великим визирем 28 шаабана 1087 года (5 ноября 1676). Будучи зятем и воспитанником рода Кёпрюлю и обладая долгим опытом государственного управления, Мерзифонлу стал одним из самых сильных и влиятельных великих визирей Мехмеда IV.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["Смерть Вани Мехмед-эфенди в ссылке", "cda714aa"], "d": ["По статье «Мехмед-эфенди, Вани» в TDV İslâm Ansiklopedisi, Вани Мехмед-эфенди, считавшийся одним из главных сторонников убеждения падишаха в необходимости Венского похода, после того как поход закончился разгромом, под давлением общественного мнения был отстранён и сослан в местечко Kestel близ Бурсы. Он скончался там 14 зуль-када 1096 года (12 октября 1685) и был погребён у входа в построенную им самим мечеть.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["Назначение Кёпрюлюзаде Фазыл Мустафа-паши великим визирем и его финансовые реформы", "b048570e"], "d": ["По статье «Кёпрюлюзаде Фазыл Мустафа-паша» в TDV İslâm Ansiklopedisi, Фазыл Мустафа-паша, назначенный великим визирем 11 мухаррама 1101 года (25 октября 1689), заново упорядочил сбор джизьи по шариатским основаниям, боролся с инфляцией монеты mangır и укрепил казну, перенаправляя средства из дворцовых учреждений. Кроме того, он усилил провинциальное управление надёжными чиновниками и создал местные советы, подобные центральному дивану.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["Введение системы маликяне", "316b8426"], "d": ["По статье «Маликяне» в TDV İslâm Ansiklopedisi, в последней четверти XVII века рост военных расходов и сокращение доходов из-за потерь территорий ввергли казну в тяжёлый финансовый кризис. В системе маликяне, вступившей в силу в 1106 (1695) году, откупщикам-мультезимам было даровано пожизненное право на фиксированный налог, и вместо краткосрочной эксплуатации был введён стимул к сохранению производства.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["Воцарение Мустафы II", "b53656c7"], "d": ["По статье «Мустафа II» в TDV İslâm Ansiklopedisi, Мустафа II, взошедший на престол в тридцать один год, объявил о своём султанстве, не дожидаясь одобрения великого визиря и шейх-уль-ислама; церемония опоясывания мечом была проведена через несколько дней в мечети Эски (Eski Cami). Падишах, взошедший на престол в эпоху многофронтовых войн, продолжавшихся после венского разгрома, стал последним османским султаном, лично ходившим в походы.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["Вторичное назначение Фейзуллах-эфенди шейх-уль-исламом", "1cf14cff"], "d": ["По статье «Фейзуллах-эфенди, Сейид» в TDV İslâm Ansiklopedisi, после воцарения Мустафы II он был вторично назначен шейх-уль-исламом 11 шавваля 1106 года (25 мая 1695). Его влияние на падишаха постепенно росло в течение более чем восьмилетнего пребывания на этом посту.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["Назначение Фейзуллах-эфенди своих сыновей на высокие должности и накопившееся недовольство", "a6398280"], "d": ["По статье «Фейзуллах-эфенди, Сейид» в TDV İslâm Ansiklopedisi, шейх-уль-ислам получил от Мустафы II беспрецедентный указ о том, что после него шейх-уль-исламом станет его сын Фетхуллах-эфенди, и расставил родственников в юном возрасте на высокие посты. Эти практики вызвали широкое недовольство среди сословия ильмийе, войска и жителей Стамбула; в сочетании со слухами о переносе столицы в Эдирне они подготовили почву для Эдирнийского инцидента 1703 года.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["Начало Эдирнийского инцидента", "5a106458"], "d": ["По статье «Эдирнийский инцидент» в TDV, движение, начавшееся с мятежа солдат, не получивших жалованья, вскоре превратилось в широкое восстание, в котором участвовали янычары, студенты медресе, ремесленники и народ. Главной целью восстания был шейх-уль-ислам Фейзуллах-эфенди, которого обвиняли в чрезмерном вмешательстве в государственные дела. Толпа примерно в 60 000 человек двинулась из Стамбула в Эдирне.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["Великое визирство Невшехирли Дамад Ибрахим-паши", "8d627a6f"], "d": ["По статье «Дамад Ибрахим-паша, Невшехирли» в TDV, он был назначен на пост великого визиря 8 джумада ас-сани 1130 года (9 мая 1718) во время продолжавшихся мирных переговоров с Австрией и, едва получив назначение, обратился к переговорам, которые должны были закончить войну; через два месяца был подписан Пожаревацкий мир (21 июля 1718). По выражению TDV, «он хотел заниматься общественными и финансовыми вопросами и тосковал по мирной эпохе, которая заставила бы забыть войны, много лет заканчивавшиеся поражениями». Он провёл реформы в финансах, снизил жалованье войску и создал в государственной казне значительный профицит. Его двенадцатилетнее великое визирство составило политические рамки эпохи, носящей его имя (Эпоха тюльпанов).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["Основание Tulumbacı Ocağı (пожарного оджака)", "f58b0d97"], "d": ["По статье «Tulumbacı» в TDV, после успеха Gerçek Dâvud, вернувшегося из Морейского похода 1715 года, в борьбе с пожарами в Стамбуле с помощью насоса (tulumba), великий визирь Невшехирли Дамад Ибрахим-паша поручил ему создать официальный пожарный оджак. Оджак, основанный в казарме ачеми-огланов (Acemi Oğlanları Kışlası) с шестью офицерами и пятьюдесятью рядовыми, достиг в 1724 году 150, а в 1755 году 461 человека. Дауд оставался во главе оджака до своей смерти в 1733 году.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["Приём Мехмед-эфенди Людовиком XV", "0ff5b174"], "d": ["По статье «Йирмисекиз Челеби Мехмед-эфенди» в TDV, посол был официально принят королём Франции Людовиком XV во дворце Тюильри и вручил подарки и письмо Ахмеда III. Во время визита он осмотрел дворцы Версаль, Трианон и Марли, больницы, обсерватории и мастерские и записал увиденное в рисунках.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["Возвращение Мехмед-эфенди в Стамбул", "a09a8bba"], "d": ["По статье «Йирмисекиз Челеби Мехмед-эфенди» в TDV, наблюдения посла, вернувшегося из годичного парижского посольства, повлияли на архитектурный вкус Эпохи тюльпанов. Последующая совместная работа его сына с Ибрахимом Мютеферрикой подготовила почву для основания первой турецкой типографии, самого прочного наследия посольства.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["Строительство дворца Sâdâbâd", "aec9c65e"], "d": ["По статье «Sâdâbâd» в TDV, на берегу реки Kâğıthane был возведён обширный увеселительный и прогулочный комплекс из дворцов, каналов, фонтанов и кёшков, вдохновлённых французской дворцовой архитектурой. Sâdâbâd, ставший излюбленным местом развлечений эпохи, был увековечен в стихах поэта Недима. Комплекс был в значительной мере разрушен во время восстания Патрона Халиля в 1730 году.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["Взятие Дербента русскими войсками: Каспийский поход Петра I", "c2b269f9"], "d": ["В то время как государство Сефевидов было ввергнуто в междоусобицу афганским нашествием, русский царь Пётр I выступил в поход, чтобы овладеть иранскими землями на берегу Каспия; приморский город Дербент сдался русским войскам без заметного сопротивления. По статье «Дербент» в TDV İslâm Ansiklopedisi, эта оккупация стала началом временного русского господства, которое продлится тринадцать лет; Османское государство также, воспользовавшись той же смутой, обратилось на западную часть Кавказа. Армия из Астрахани морем высадилась в Аграханском заливе, оттуда по берегу через Тарки шла сушей; шамхал Тарков принял Петра и перешёл в русское подданство.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["Упразднение Тарковского шамхальства: прямое русское управление", "b0f029c6"], "d": ["Шамхал Тарков Адиль-Гирей, принявший Петра в 1722 году и перешедший в русское подданство, в 1725 году восстал; Еропкин осенью 1725 года разрушил Тарки, шамхал в середине мая 1726 года был арестован и сослан, и шамхальство было упразднено. Тарки и его окрестности оставались под прямым русским управлением до Гянджинского договора 1735 года.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["Разрешение Ибрахиму Мютеферрике основать типографию", "0659dd0a"], "d": ["По статье «Ибрахим Мютеферрика» в TDV, указом Ахмеда III и фетвой шейх-уль-ислама Йенишехирли Абдуллах-эфенди было разрешено основание первой турецкой типографии. Типография начала работу в стамбульском районе Yavuzselim. До своей смерти в 1747 году Мютеферрика напечатал семнадцать трудов в двадцати трёх томах.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["Завершение первой печатной книги — Vankulu Lügati", "684700e8"], "d": ["По статье «Ибрахим Мютеферрика» в TDV, турецкий перевод Sıhâhu'l-Cevherî (Vankulu Lügati), первого труда типографии, был завершён в начале 1729 года. Это была первая книга, напечатанная арабским шрифтом на османских землях, и она считается началом истории турецкого книгопечатания.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["Казнь Невшехирли Дамад Ибрахим-паши", "50c64341"], "d": ["По статье «Дамад Ибрахим-паша, Невшехирли» в TDV, тело великого визиря, убитого во дворце во время восстания Патрона Халиля, было протащено по улицам Стамбула и брошено близ фонтана Ахмеда III на площади Султанахмет. Так кровавым образом закончились его двенадцатилетнее великое визирство и Эпоха тюльпанов.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["Отречение Ахмеда III, воцарение Махмуда I", "a43f5d40"], "d": ["По статье «Махмуд I» в TDV, перед давлением мятежников Ахмед III отрёкся от престола, получив гарантии для себя и своих детей, и сам возвёл на трон племянника шехзаде Махмуда. Взошедший на престол по совету дяди «возьми государственные дела в собственные руки, никому не доверяй» Махмуд I первым делом принялся сокрушать влияние группы мятежников, возведшей его на трон.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["Реформа артиллерийского оджака Хумбараджи Ахмед-паши", "ea3a7c64"], "d": ["По статье «Humbaracı» в TDV, офицер французского происхождения, принявший ислам, Ахмед-паша при великом визире Хекимоглу Али-паше приступил к реформе оплачиваемой организации humbaracı (бомбардиров) на европейский лад. Он создал новую структуру из 601 человека — 300 получавших жалованье и 301 тимариота, — подчинённую непосредственно великому визирю. По технологии эпохи он велел изготовить 100 мортир и 50 000 ядер.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["Основание Hendesehâne (первого образца инженерной школы)", "a77ed1f3"], "d": ["По статье «Махмуд I» в TDV, Хумбараджи Ахмед-паша основал в Ускюдаре Hendesehâne, называвшуюся также Humbarahâne, и давал военное образование на основе математики и геометрии ученикам, отобранным из дворцовой прислуги и бостанджи. Это учреждение считается первым образцом инженерных школ, которые разовьются в последующую эпоху.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["Гянджинский договор: возвращение Дербента и Баку Ирану", "ff19d531"], "d": ["Россия, искавшая союза с Ираном против османской угрозы, по Гянджинскому договору вернула тринадцать лет удерживаемые ею города каспийского побережья Ирану под командованием Надир-хана (ещё не принявшего титул шаха). По статье «Дербент» в TDV İslâm Ansiklopedisi, это отступление было следствием нежелания России вести борьбу на юге сразу на два фронта (против Османской империи и Ирана) и укрепило военный авторитет Надира, открывший ему путь к воцарению через несколько лет. Находившиеся под русским управлением Тарки (Tarku) также этим отступлением вернулись на сторону Ирана (на карте используется дата Гянджи).", "94b6c31b"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["Воцарение Надир-шаха в Муганской степи: фактический конец династии Сефевидов", "4f640979"], "d": ["По статье «Надир-шах» в TDV İslâm Ansiklopedisi, курултай примерно в двадцать тысяч человек, собравшийся в Муганской степи, настойчиво просил его возглавить Иран; Надир принял это предложение при условии отказа от крайнего шиизма, ставшего причиной войн между Сефевидами и османами, и принятия умеренного джафаритского мазхаба, и 24 шавваля 1148 года (8 марта 1736) взошёл на престол под именем Надир-шаха. Это означало фактический конец двухвековой династии Сефевидов и основание династии Афшаридов.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["Начало эпидемии чумы в Стамбуле", "9fa82b56"], "d": ["По статье «Чума» в TDV, эпидемия чумы, действовавшая в исламском мире в 1739–1743 годах, в этот период поразила и Стамбул. Статья отмечает, что эпидемии XVIII века протекали относительно легче, чем в предыдущие века. К периодам эпидемий относят также 1713, 1719, 1728–1729 и 1759–1765 годы.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["Пожар Hocapaşa", "321c7d0d"], "d": ["По статье «Мечеть Фатьмы Султан» в TDV, начавшийся ночью пожар Hocapaşa разорил Высокую Порту и её окрестности; предполагается, что от этого пожара пострадала и расположенная в этом районе мечеть Фатьмы Султан. Эта катастрофа, одна из больших пожаров, поразивших Стамбул в эпоху Османа III, нанесла тяжёлый ущерб торговому и административному центру города.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["Великое визирство Коджа Рагыб Мехмед-паши", "a1846910"], "d": ["Рагыб-паша, известный как поэт и дипломат, был назначен Османом III на пост великого визиря (в октябре 1757 года после смерти Османа III он продолжил службу и получил новую печать от Мустафы III). Пока шла Семилетняя война, он проводил взвешенную внешнюю политику, державшую Османское государство вне европейских конфликтов. За шесть лет великого визирства он придавал значение и культурной деятельности, такой как основание библиотеки.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["Смерть Рагыб-паши", "6bc19323"], "d": ["Рагыб-паша скончался после шестилетнего великого визирства. С его смертью закончилось самое долгое и взвешенное великое визирство эпохи Мустафы III.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["Большое стамбульское землетрясение и разрушение мечети Фатих", "2475b4dc"], "d": ["По статье «Мечеть и комплекс Фатих» в TDV, во время большого землетрясения 1766 года главный купол мечети полностью обрушился, стены были повреждены до степени, не подлежащей ремонту. Перестройка, начатая в 1767 году по приказу Мустафы III под руководством архитекторов Сарым Ибрахим-эфенди и Иззет Мехмед-бея, была завершена в 1771 году по новому проекту, отличавшемуся от прежнего плана.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["Недолговечная попытка артиллерийской школы под руководством барона де Тотта", "4192260c"], "d": ["По статье «Mühendishâne-i Bahrî-i Hümâyun» в TDV, неудачи в османско-русской войне 1768 года обнажили потребность в технической военной подготовке; недолговечная артиллерийская школа, открытая при содействии французского офицера барона де Тотта, начала работу в октябре 1772 года, но осталась малоэффективной. Эта попытка считается предшественницей Mühendishâne-i Bahrî-i Hümâyun (Императорской морской инженерной школы), которая будет основана в 1775 году.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["Селим III взошёл на престол", "00d046d9"], "d": ["После смерти Абдулхамида I на престол взошёл его племянник Селим III. По статье «Селим III» в TDV İslâm Ansiklopedisi, новый падишах, со времён шехзаде интересовавшийся реформой по образцу европейских армий, вскоре после воцарения начал готовить программу коренного обновления. Эта программа через несколько лет получит название Nizâm-ı Cedîd (Новый порядок).", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["Началась подготовка реформаторской программы Nizâm-ı Cedîd", "eff78a68"], "d": ["Селим III велел подготовить всестороннюю программу обновления на основе проектов, запрошенных у государственных мужей и иностранных специалистов. По статье «Nizâm-ı Cedîd» в TDV İslâm Ansiklopedisi, эта программа не ограничилась созданием новой армии, а превратилась в широкое реформаторское движение, охватывавшее финансы, провинциальное управление и дипломатию. В последующие пятнадцать лет программа найдёт и сторонников, и противников.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["Учреждены постоянные посольства в европейских столицах", "2e9dc8a1"], "d": ["Селим III впервые в истории Османского государства направил в крупные европейские центры постоянных послов, которые должны были служить там непрерывно. По статье «Посол» в TDV İslâm Ansiklopedisi, этот шаг придал османской дипломатии, до тех пор осуществлявшейся лишь временными разовыми миссиями, постоянную организацию. Главной задачей новых посольств было регулярно сообщать в Стамбул о политических и военных событиях в Европе.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["Учреждена казна İrad-ı Cedîd", "ae5c8ce2"], "d": ["Для покрытия расходов армии Nizâm-ı Cedîd и реформаторской программы была учреждена отдельная казна. По статье «Эсхам» в TDV İslâm Ansiklopedisi, к доходам новой казны относились непосредственная эксплуатация государством некоторых мукатаа и взятие под контроль продажи эсхама. Эта мера была попыткой создать новый источник вне традиционной финансовой системы.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["Начало мятежа Кабакчи Мустафы", "b98eee17"], "d": ["Накопившееся недовольство против Nizâm-ı Cedîd прорвалось восстанием ямаков под предводительством Кабакчи Мустафы. По статье «Мятеж Кабакчи» в TDV İslâm Ansiklopedisi, мятежники вскоре взяли под контроль Стамбул и потребовали головы государственных деятелей, сторонников Nizâm-ı Cedîd. Восстание в течение нескольких дней закончилось низложением Селима III.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["Селим III низложен", "ff2c30ec"], "d": ["Под давлением мятежа Кабакчи Мустафы Селим III был низложен по фетве, полученной от шейх-уль-ислама. По статье «Селим III» в TDV İslâm Ansiklopedisi, это решение стало моментом фактического конца периода реформ, длившегося восемнадцать лет; армия Nizâm-ı Cedîd также вскоре была распущена. Селим был взят под стражу в дворце Топкапы.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["Мустафа IV взошёл на престол", "8f1ac86c"], "d": ["Сразу после низложения Селима III его племянник Мустафа IV был провозглашён падишахом. По статье «Мустафа IV» в TDV İslâm Ansiklopedisi, новый падишах начал правление под влиянием кругов, поддержавших мятеж и противостоявших Nizâm-ı Cedîd. Этот недолгий период стал этапом нестабильности, в котором центральная власть ослабела окончательно.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["Алемдар Мустафа-паша вошёл в Стамбул со своей армией", "0cad3dea"], "d": ["Аян Русе Алемдар Мустафа-паша подошёл со своей армией к Стамбулу, чтобы вновь возвести на престол Селима III. По статье «Алемдар Мустафа-паша» в TDV İslâm Ansiklopedisi, его вход в город встретил лично Мустафа IV; однако в течение нескольких дней баланс сил во дворце полностью изменится. Этот вход положил начало цепи событий, закончившейся и смертью Селима, и новым воцарением.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["Селим III убит", "e452f5f6"], "d": ["В тот день, когда Алемдар Мустафа-паша овладел Высокой Портой, по приказу Мустафы IV Селим III был убит во дворце. По статье «Селим III» в TDV İslâm Ansiklopedisi, это было решение, принятое с целью предотвратить попытку вновь возвести на престол низложенного падишаха. Смерть Селима в тот же день закончилась воцарением Махмуда.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["Махмуд II взошёл на престол", "661c1974"], "d": ["После убийства Селима III Махмуд, оставшийся единственным мужчиной в династии, взошёл на престол при поддержке Алемдар Мустафа-паши. По статье «Махмуд II» в TDV İslâm Ansiklopedisi, первые месяцы своего султанства новый падишах провёл под опекой Алемдара, возведшего его на трон, и в усилиях вновь установить баланс между аянами и центром. Этот период стал началом последующего двадцатилетнего процесса коренных реформ.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["Создана армия Sekbân-ı Cedîd", "6f9eb5e4"], "d": ["Алемдар Мустафа-паша велел создать вместо упразднённой Nizâm-ı Cedîd новую армию, оснащённую по европейскому образцу. По статье «Sekbân-ı Cedîd» в TDV İslâm Ansiklopedisi, эта сила, состоявшая из трёх полков, воспринималась янычарами как прямая угроза и была уничтожена в янычарском восстании всего через несколько месяцев после создания.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["Падение Брэилы — первая крупная брешь в линии Дуная", "ee519321"], "d": ["В русской войне, начавшейся в 1806 году, крепость Брэила на северном берегу Дуная была осаждена и обстреляна русскими силами под командованием графа Каменского. Внутри находились 4100 пехотинцев, 1100 всадников и 260 орудий; крепость сдалась генералу Эссену из-за недостатка продовольствия. Северный конец дунайской оборонительной линии тем самым был открыт.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["Сдача Русе — потеряны и южный берег Дуная", "084062e8"], "d": ["Русе выдержал долгую и кровавую осаду русской армии под командованием графа Каменского; он сдался на условии, что гарнизон и гражданское население покинут город в безопасности. Падение сильнейшего крепостного города на южном берегу Дуная повернуло ход войны в пользу России.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["Основан Eşkinci Ocağı", "67c56759"], "d": ["Махмуд II велел создать новое подразделение из солдат, отобранных из янычарского оджака, для обучения по европейскому образцу. По статье «Eşkinci Ocağı» в TDV İslâm Ansiklopedisi, подразделение приступило к обучению 12 июня 1826 года, но янычары увидели в этом конец своего оджака. Восстание, вспыхнувшее три дня спустя, положило конец и недолгому существованию Eşkinci Ocağı.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["Основана Asâkir-i Mansûre-i Muhammediyye", "14b84a7e"], "d": ["Сразу после упразднения Янычарского оджака Махмуд II велел создать вместо него новую регулярную армию с европейским обучением. По статье «Asâkir-i Mansûre-i Muhammediyye» в TDV İslâm Ansiklopedisi, эта армия, в отличие от прежних попыток, стала постоянным учреждением благодаря системе чинов, программе обучения и системе жалованья. В последующие годы армия превратится в армию Низамие эпохи Танзимата.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["Орден бекташи закрыт", "f7d9a367"], "d": ["Одновременно с упразднением Янычарского оджака был запрещён и орден бекташи, известный религиозными связями с оджаком. По статье «Бекташизм» в TDV İslâm Ansiklopedisi, одни шейхи малых текке были казнены, шейх обители Хаджи Бекташа был сослан в Амасью, а текке были переданы в ведение накшбандийя. Несмотря на этот тяжёлый удар, орден продолжил свою организацию тайно.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["Инцидент с опахалом — предлог для вторжения", "e949001e"], "d": ["Во время переговоров, обострившихся из-за неуплаченного старого зернового долга Франции перед Алжиром, дей Хусейн ударил опахалом, бывшим у него в руке, французского консула Деваля. Этот инцидент, порождённый спором о долге, был сделан официальным предлогом для вторжения, которое начнётся три года спустя.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["Французская блокада алжирского побережья — трёхлетняя осада", "d0ba97a5"], "d": ["После инцидента с опахалом Франция блокировала алжирское побережье. Блокада длилась три года; морская торговля и источники доходов оджака были иссушены, способность к сопротивлению была подточена ещё до начала вторжения.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["Туркманчайский договор: Эривань и Талыш перешли к России", "abffcfdb"], "d": ["Когда русско-иранская война 1826–1828 годов закончилась тяжёлым поражением Ирана, по подписанному в Туркманчае договору Эриванское и Нахичеванское ханства и каспийская область Талыш (Ленкорань, Астара) были уступлены России; кроме того, была наложена тяжёлая военная контрибуция. По статье «Эривань» в TDV İslâm Ansiklopedisi, эта потеря — момент, когда была проведена русско-иранская граница на Кавказе, во многом остающаяся действительной по сей день, и она вызвала переселение армянского населения в Эривань.", "f6438d89"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["Второе падение Брэилы — царь Николай перед крепостью", "eb6a8741"], "d": ["Брэила, возвращённая османам в 1812 году и вновь укреплённая в 1817–1818 годах, была осаждена в апреле, имея внутри 4000 защитников и 278 орудий. Её начальник Абу-Бекр-паша создал новую оборонительную линию; царь Николай I в конце мая лично прибыл к крепости. Город подвергся русской оккупации, но по Адрианопольскому миру был возвращён и оставлен Валашскому княжеству.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["Феска объявлена официальным головным убором", "f55be4eb"], "d": ["Махмуд II, пойдя на коренное изменение в одежде чиновников и военных, объявил феску официальным головным убором вместо чалмы. По статье «Феска» в TDV İslâm Ansiklopedisi, это решение было объявлено хатт-ы хумаюном и введено в действие вместе с реформами Asâkir-i Mansûre-i Muhammediyye в западном духе. Перемена означала и конец традиционной иерархии одежды.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["Уступка Ахалцихе России — потерян центр эялета Çıldır", "e2e00b2a"], "d": ["Ахалцихе, находившийся под османским управлением со времён битвы при Çıldır 1578 года и бывший центром эялета Çıldır, был уступлен России по Адрианопольскому миру, подписанному по окончании войны 1828–1829 годов. Потеря города вызвала глубокую скорбь в народе и стала предметом многих плачей.", "9ad8078a"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["Высадка у Sidi Ferruc — французская армия на земле Алжира", "33327553"], "d": ["После трёхлетней блокады французская десантная армия под командованием графа де Бурмона высадила войска в бухте Sidi Ferruc на западе Алжира. Продвигавшиеся к городу силы за три недели прорвали оборонительную линию; 4 июля пал форт Император, господствовавший над городом, а на следующий день сдался дей Хусейн.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["Изгнание дея Хусейна — фактический конец Алжирского оджака", "e122403b"], "d": ["Согласно условиям капитуляции, последний алжирский дей Хусейн был вместе с семьёй и казной выведен из города и отправлен в Неаполь. Так закончилось управление оджаком, который был присоединён к Селиму II в 1519 году и триста лет оставался сильнейшей османской военно-морской базой в Средиземном море.", "54846340"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["Вывод русской армии из Валахии и Молдавии — конец шестилетней оккупации", "efdb0275"], "d": ["В османско-русской войне 1828–1829 годов русские заняли Валахию и Молдавию и после Адрианопольского мира не вывели войска, пока не была выплачена военная контрибуция. Когда в январе 1834 года контрибуция была снижена до пяти миллионов, русские войска очистили Memleketeyn (Дунайские княжества), и в оба княжества были назначены новые воеводы. Османский сюзеренитет формально вернулся, но Россия сохранила влияние, установленное Органическим регламентом (Reglement Organique).", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["Создана организация Redif-i Asâkir-i Mansûre", "15947493"], "d": ["Организация Redif как резервная сила, призванная поддерживать Asâkir-i Mansûre-i Muhammediyye, была создана уставом от 8 июля 1834 года. По статье «Redif» в TDV İslâm Ansiklopedisi, под руководством сераскера Коджа Хюсрев-паши в провинциальных кадылыках были сформированы батальоны примерно по тысяче четыреста человек. Организация была задумана так, чтобы поддерживать и местную безопасность, не призываясь на постоянную службу.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["Учреждено Министерство иностранных дел (Hariciye Nezareti)", "750c6c7d"], "d": ["Махмуд II упразднил должность Reisülküttâb, ведавшую внешними делами, и учредил вместо неё Hariciye Nezareti (Министерство иностранных дел). По статье «Hariciye Nezâreti» в TDV İslâm Ansiklopedisi, первым министром нового ведомства был назначен Мехмед Акиф-паша, и организация начала работу в доме венского посла Рыфат-бея. Эта мера стала началом ведения османской внешней политики на основе современного министерства.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["Учреждён Meclis-i Vâlâ-yı Ahkâm-ı Adliyye (Верховный совет юридических постановлений)", "69db056e"], "d": ["Махмуд II учредил Meclis-i Vâlâ-yı Ahkâm-ı Adliyye как высший совет, в котором должны были обсуждаться готовящиеся законы и уставы. По статье «Meclis-i Vâlâ-yı Ahkâm-ı Adliyye» в TDV İslâm Ansiklopedisi, совет фактически начал работу 31 марта 1838 года, и почти все последующие реформы Танзимата готовились и контролировались через этот орган. Учреждение стало одним из важнейших центров современной османской бюрократии.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["Синопское сражение", "5947e93f"], "d": ["Русский Черноморский флот под командованием адмирала Нахимова без объявления войны совершил нападение на османский флот, стоявший на якоре в порту Синоп; двенадцать кораблей затонули, более двух тысяч солдат пали шехидами, а командующий флотом Осман-паша был взят в плен. По статье «Синоп» в TDV İslâm Ansiklopedisi, во время нападения в городе также сгорели семь мечетей, две школы, 247 домов и 170 лавок, погибли пять мусульман и шестнадцать христиан из числа гражданских лиц. Событие, прозвучавшее в европейском общественном мнении как «Синопская катастрофа», стало прямым поводом для вступления Англии и Франции в войну на стороне Османского государства через несколько месяцев.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["Вышла газета Tasvir-i Efkâr", "506c98e2"], "d": ["Tasvir-i Efkâr, выпускавшаяся Шинаси, начала выходить как четвёртая турецкая газета после Takvîm-i Vekāyi', Cerîde-i Havâdis и Tercüman-ı Ahvâl. По статье «Tasvîr-i Efkâr» в TDV, при Намык Кемале, принявшем на себя впоследствии должность главного редактора, газета стала рупором движения Новых османов.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["Основано Общество новых османов (Yeni Osmanlılar Cemiyeti)", "335fb02d"], "d": ["Османские интеллектуалы, бежавшие в Европу под предводительством Мустафы Фазыл-паши, организовались под названием «Молодая Турция» на основе устава из тринадцати статей. По статье «Yeni Osmanlılar Cemiyeti» в TDV, группа распространяла требование конституционного правления, выпуская в Париже, Лондоне и Женеве газеты Muhbir и Hürriyet.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["Учреждён Şûrâ-yı Devlet (Государственный совет)", "b863b306"], "d": ["Meclis-i Ahkâm-ı Adliyye был разделён на два органа: Şûrâ-yı Devlet, ведавший административными делами, и Dîvân-ı Ahkâm-ı Adliyye, занимавшийся судебными. По статье «Şûrâ-yı Devlet» в TDV, первым председателем учреждения, взявшего за образец французский Conseil d'État, был назначен Мидхат-паша; целью было разделение законодательной, исполнительной и судебной власти.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["Издан указ об основании Darülfünun", "513704bf"], "d": ["Указом, подготовленным великим визирем Али-пашой и министром просвещения Саффет-пашой, Darülfünun был официально основан; первые лекции начались ещё в 1863 году. По статье «Darülfünun» в TDV, учреждение фактически приступило к обучению в феврале 1870 года под руководством Ходжа Тахсин-эфенди с отделениями философии и литературы, естественных наук и права.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["Начались работы над Mecelle-i Ahkâm-ı Adliyye", "8abdcbee"], "d": ["Mecelle Cemiyeti (Комиссия Меджелле), учреждённая под председательством главы Dîvân-ı Ahkâm-ı Adliyye Ахмеда Джевдет-паши, приступила к подготовке гражданского кодекса на основе ханафитского фикха. По статье «Mecelle-i Ahkâm-ı Adliyye» в TDV, последняя часть труда, состоявшего из шестнадцати книг и 1851 статьи, была завершена 15 сентября 1876 года и вступила в силу; он считается первой кодификацией исламского права.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["Поставлена пьеса «Родина, или Силистрия», Намык Кемаль отправлен в ссылку", "3861284c"], "d": ["Когда патриотическая пьеса Намыка Кемаля была поставлена в театре Gedikpaşa, зрители высыпали на улицы с криками «Да здравствует родина, да здравствует Кемаль». По статье «Намык Кемаль» в TDV, правительство, испугавшись этой демонстрации, закрыло газету İbret и 6 апреля 1873 года без суда отправило Намыка Кемаля в ссылку на Кипр (в Фамагусту).", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["Подозрительная смерть Абдулазиза", "85816692"], "d": ["Абдулазиз, после низложения по собственному желанию перевезённый во дворец Fer‘iye (1 июня 1876), был 4 июня найден в своей комнате с перерезанными венами на запястьях. Комиссия из девятнадцати врачей, в которую входили и врачи посольств, составила заключение с неопределённой формулировкой; 6 июня в газетах смерть была объявлена самоубийством. Расследование же, открытое Абдулхамидом II, пришло к убеждению, что смерть была не самоубийством, а убийством, и обвиняемые в 1881 году были судимы в Yıldız Mahkemesi (суде Йылдыз); вопрос и сегодня остаётся спорным в историографии.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["Смещение Мидхат-паши с поста великого визиря и ссылка", "b5247b06"], "d": ["Великий визирь Мидхат-паша, архитектор Kanûn-ı Esâsî (Османской конституции 1876 г.), через шесть недель после её провозглашения был смещён Абдулхамидом II и за одну ночь отправлен в ссылку за границу. По статье «Мидхат-паша» в TDV İslâm Ansiklopedisi, смещение связывается с недовольством падишаха положениями конституции, ограничивавшими его полномочия. Паша отправился сначала в Неаполь, затем в различные города Европы.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["Возвращение Эр-Рияда Абдул-Азизом ибн Саудом у Рашидидов", "75eb8830"], "d": ["Юный Абдул-Азиз из династии Саудов, десять лет назад отправившийся в изгнание в Кувейт, с небольшим отрядом совершил налёт на Эр-Рияд, убил наместника Аль-Рашид (Шаммар) и овладел городом. По статье «Эр-Рияд» в TDV İslâm Ansiklopedisi, успеху налёта способствовало постепенное ослабление Рашидидов и их неспособность послать в город подкрепление; событие считается моментом основания Второго Саудовского государства, которое в последующие тридцать лет станет ядром нынешней Саудовской Аравии.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["Вступление Армии действия в Стамбул", "41c8304c"], "d": ["Армия действия, выступившая из Салоник и состоявшая в большинстве из частей, преданных «Единению и прогрессу», вошла в Стамбул, чтобы подавить Инцидент 31 марта. По статье «Армия действия» в TDV İslâm Ansiklopedisi, командование принял Махмуд Шевкет-паша, а начальником штаба был колагасы Мустафа Кемаль. После коротких столкновений в городе был вновь обеспечен порядок.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["Роспуск последнего османского Meclis-i Mebusan", "2b709269"], "d": ["После официальной оккупации Стамбула силами Антанты и ареста многих депутатов Meclis-i Mebusan (Палата депутатов) оказалась неспособной работать и была официально распущена волей Мехмеда VI. По статье «Meclis-i Mebusan» в TDV İslâm Ansiklopedisi, этот роспуск символизировал фактический конец османской конституционной парламентской традиции. Закрытие усилило потребность в созыве нового национального собрания в Анкаре.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["Открытие Великого национального собрания Турции", "6eab539d"], "d": ["После роспуска Meclis-i Mebusan в Стамбуле депутаты собрались в Анкаре и открыли Великое национальное собрание Турции, а Мустафа Кемаль-паша был избран его председателем. По статье «Великое национальное собрание Турции» в TDV İslâm Ansiklopedisi, собрание носило чрезвычайный характер, сосредоточив в своих руках и законодательную, и исполнительную власть. Это открытие стало поворотным моментом, когда политический и институциональный центр национальной борьбы переместился в Анкару.", "805871d7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["Завоевание крепости Зворник", "657c465a"], "d": ["Крепость Зворник на берегу Дрины была завоёвана османами в 1460 году. По TDV İslâm Ansiklopedisi, из-за удобного в административном и военном отношении положения она была сначала сделана центром кааза, в 1480 году превращена в центр одноимённого санджака, а в 1491 году укреплена каменными стенами и с шестью мечетями, восемью текке и банями превратилась в важный административно-торговый центр.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["Смерть Касим-хана, воцарение Даньял-хана (Касимовское ханство)", "522fd0fd"], "d": ["После смерти основателя ханства Касим-хана в 873/1468 году его место занял сын Даньял; Даньял правил до 1486 года.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["Морская битва при Диу — господство Португалии в Индийском океане", "1778d347"], "d": ["Флот Малика Аяза, управлявшего регионом от имени Гуджаратского султаната и поддерживавшегося мамлюками, потерпел у Диу тяжёлое поражение от флота португальского генерал-губернатора Франсишку де Алмейды, пытавшегося создать на этих берегах базу снабжения. Это поражение дало Португалии прочное морское господство в Индийском океане и сломило мамлюкско-гуджаратскую морскую силу; оно считается началом того неравенства сил, которое составило фон борьбы за Красное море и Индийский океан, унаследованной османами после 1517 года (оборона Джидды, осада Диу 1538 года).", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["Восстание Календер-шаха", "f60f6ca4"], "d": ["Из-за финансовых затруднений в Анатолии, недовольства новыми административными распоряжениями и влияния сефевидской пропаганды крупные туркменские племена, такие как Çiçekli, Akça Koyunlu, Masadlı и Bozoklu, и группы, оставшиеся от прежнего восстания Баба Зуннуна, собрались вокруг Календер-шаха и достигли силы примерно в тридцать тысяч человек. Мятежники сначала разбили бейлербея Рума; когда великий визирь Ибрахим-паша Макбул собрал войско и пообещал им права, поддержка Календера растаяла, и восстание было подавлено в окрестностях Эльбистана, а Календер-шах и Вели Дундар были убиты в июне 1527 года.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["Завоевание Шахризора — взятие крепости Zalm", "4320d9b8"], "d": ["Во время Нахичеванского похода Кануни бейлербей Багдада Осман-паша был послан овладеть областью Шахризор; после его смерти ставший бейлербеем Багдада Балтаджи Мехмед-паша осадил центральную крепость области Zalm и взял её 22 августа 1554 года (23 рамадана 961). Так бассейн Шахризора на западном склоне Загроса перешёл под османское управление, и связь между Багдадом и Курдистаном была обеспечена; область сначала была превращена в санджак и отдана Мурад-бею. В 1563 году бейлербей Музаффер-паша построил крепость Gülanber как центр нового эялета; крепость в 1623 году будет разрушена по приказу шаха Аббаса, в 1638 году при Хюсрев-паше будет отстроена заново.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["Переход правителя Касимовского ханства в христианство и лишение его ханства", "a1a8eeb9"], "d": ["Правитель, стоявший во главе ханства, принял имя «Семён (Симеон)» и стал христианином; русские, учитывая реакцию мусульманских подданных, сняли его с ханства. Этот человек вскоре был объявлен Иваном Грозным в Москве номинальным правителем с титулом «великий князь царя и всея Руси» (1575) — самое яркое пересечение Касимовского ханства с московским престолом.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["Присоединение санджака Феццан к Триполи — Мурзук и караванный узел Сахары", "2e6554a4"], "d": ["Под давлением бейлербейства Триполи Феццан, караванный узел Сахары, с центром в Мурзуке принял османское подданство. По статье «Феццан» в TDV İslâm Ansiklopedisi, управлявшая областью династия Evlâd-ı Muhammed была оставлена свободной во внутренних делах при условии регулярной уплаты налога; Феццан был организован как санджак, подчинённый взятому в 1551 году эялету Триполи. Так торговля рабами, золотом и верблюдами на линии Триполи — Мурзук — Борну перешла под османский контроль. Это косвенное управление перейдёт в 1711 году в руки Караманлы, а в 1842 году — в руки непосредственной организации кааза.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["Переход Нахичевани и Ордубада под османское управление", "24d939b3"], "d": ["После взятия Эривани в 1583 году и превращения её в центр бейлербейства силы, спустившиеся на юго-восток вдоль долины Аракса, подчинили османскому управлению Нахичевань и Ордубад; оба города стали санджаками вновь созданного эялета Эривань. По статье «Нахичевань» в TDV İslâm Ansiklopedisi, постоянное османское управление в городе было впервые установлено во время этой войны — в Нахичеванском походе 1553 года город был взят, но лишь разграблен и оставлен. Так открылась армейская дорога между Эриванью и Тебризом, и в сентябре того же года удалось войти в Тебриз. Шах Аббас в 1603 году вернёт Нахичевань.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["Восстание Дели Хасан-паши и его умиротворение бейлербейством Боснии", "144f3f2d"], "d": ["После смерти предводителя джелали Карайазиджи Абдулхалима в 1602 году его брат Дели Хасан, возглавивший движение, воспользовавшись свободой действий, которую давали группам джелали продолжавшиеся австрийские войны, вторгся в Кютахью и двинулся на Афьонкарахисар. В это время, когда государство одновременно занималось австрийским и иранским фронтами, вопрос был решён «миром»: Дели Хасану были даны чин паши и бейлербейство Боснии, и повстанческое движение в 1603 году было официально прекращено.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["Взятие русскими войсками города Касимов, Ураз-Мухаммед-хан", "b3f0bd34"], "d": ["Как отражение Смутного времени в России русские войска осадили и взяли город Касимов, перебив большую часть его жителей. Стоявший во главе ханства Ураз-Мухаммед был взят на прицел за поддержку Лжедмитрия II; на следующий год (1610) он сам был убит в результате заговора.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["Потеря крепости Азов в пользу донских казаков", "ba068b2f"], "d": ["Донские казаки, осаждавшие с 21 апреля 1637 года крепость Азов, взяли её два месяца спустя; крепость, бывшая северо-восточными воротами Чёрного моря и замком донской торговли, впервые вышла из османских рук. По статье «Азов» в TDV İslâm Ansiklopedisi, казаки взяли крепость в 1637 году, в 1641 году выдержали трёхмесячную крупную осаду под командованием Дели Хусейн-паши и оставили крепость лишь в 1642 году с приходом крымского хана Мехмеда Гирея. Государство в то время было занято багдадским фронтом; невозможность удержать крепость пять лет — первая трещина в качестве Чёрного моря как «османского озера».", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["Возвращение Лемноса и Самофракии", "c445553b"], "d": ["После освобождения Тенедоса 31 августа 1657 года Кёпрюлю Мехмед-паша направил флот на север и вернул Лемнос и Самофракию, шестнадцать месяцев удерживавшиеся Венецией. По статье «Лемнос» в TDV İslâm Ansiklopedisi, остров перешёл в руки Венеции в июле 1656 года и был возвращён в ноябре 1657 года. Так венецианская блокада у входа в пролив Дарданеллы была полностью прорвана, и хлебный путь Стамбула был вновь обеспечен; это самое конкретное достижение первого года, когда великий визирь пришёл к власти с чрезвычайными полномочиями.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["Потеря Книна в пользу Венеции — пала 166-летняя пограничная крепость Далмации", "252406b7"], "d": ["В войне, открытой на многих фронтах после венского разгрома 1683 года, венецианские войска продвинулись во внутренние области Далмации. Книн, осаждённый далматинским генералом Джероламо Корнаро, после двенадцатидневной осады был сдан бейлербеем Мехмед-пашой. Книн был ключевой крепостью пограничной линии Далмации, завоёванной в 1522 году Гази Хюсрев-беем и 166 лет остававшейся в османских руках; его потеря в значительной мере открыла регион Венеции.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["Возвращение Басры после иранской оккупации", "5b10c5c1"], "d": ["Басра, взятая в 1776 году Садык-ханом, братом Керим-хана Зенда, была оставлена после того, как в Иране после смерти Керим-хана 2 марта 1779 года началась борьба за престол; Садык-хан вернулся в Иран с притязанием на престол. Недолго побыв в руках племени мунтафик, город вновь перешёл под османское управление. Бывший мютеселлим Сулейман-ага, вернувшийся из Шираза, потребовал правления Басрой и под именем Бююк Сулейман-паши стал правителем Басры, Багдада и Шахризора. Торговля в Персидском заливе вернулась под османский контроль; в годы оккупации часть торговли сместилась в Кувейт, а с 1778 года пустынная почта также отправлялась из Кувейта.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["Смерть Тимур-шаха, воцарение Земан-шаха (Дурранийское государство)", "c3effdb2"], "d": ["После смерти Тимур-шаха, более двадцати лет укреплявшего страну изнутри, три брата — правители Кандагара, Герата и Кабула — боролись за престол; правитель Кабула Земан-шах, державший столицу в своих руках, стал шахом 20 мая 1793 года. Этот кризис наследования — фактическое начало процесса распада династии.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["ʻAi Noa — прекращение традиционной системы капу на Гавайях", "0b10e1d8"], "d": ["Через шесть месяцев после смерти Камеамеа I новый король Лихолихо при поддержке матери Каʻахуману сознательно нарушил запрет на раздельное принятие пищи мужчинами и женщинами (ʻaikapu). Это действие, называемое «ʻAi Noa» (свободная трапеза), официально положило конец традиционной религиозно-правовой системе капу; старые храмы (heiau) на островах вскоре были разрушены. Это самый крупный религиозно-политический перелом до прихода западных миссионеров (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["Лондонский протокол — признание независимости Греции", "4c7b4b72"], "d": ["Протокол, подписанный в Лондоне Англией, Францией и Россией, превзойдя предусмотренную Адрианопольским миром автономию, признал Грецию НЕЗАВИСИМЫМ государством. Положения: полуостров Морея, Аттика и Негропонт с островами Киклады были уступлены новому государству; граница была проведена по линии Арта — Волос; было решено выплатить компенсацию Османскому государству; форма правления государства была определена как «независимая монархия». Это ПЕРВОЕ независимое государство, отделившееся от империи, и оно создало правовой образец для последующих балканских независимостей.", "e8fc6290"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["Абдаллах ибн Рашид овладел эмиратом Хаиль — основание династии Шаммар (Рашидидов)", "fb513b8a"], "d": ["С падением Дирии в 1818 году силами Мухаммеда Али область Джебель-Шаммар вышла из-под саудовского господства, и эмират остался в руках семьи ибн Али. Абдаллах ибн Рашид, поддерживавший восстановление османского господства, вместе с братом Убейдом выиграл в 1835 году борьбу против семьи ибн Али, овладел эмиратом Хаиль и установил власть династии Рашидидов.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["Провозглашена первая письменная конституция Гавайев", "401a8a1d"], "d": ["Была провозглашена первая полностью письменная конституция королевства; этот документ, ограничивший власть короля и учредивший представительное собрание, превратил Гавайи в конституционную монархию.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["Штыковая конституция — полномочия короля Калакауа урезаны", "4953363b"], "d": ["Вооружённая милиция, угрожая королю Калакауа, заставила его подписать новую конституцию, в значительной мере урезавшую полномочия королевства; документ называется «Штыковая конституция» (Bayonet Constitution) и фактически передал трон под контроль элиты белых поселенцев.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["Смерть Георга Тупоу I, воцарение Георга Тупоу II (Тонга)", "b56e2b32"], "d": ["После смерти короля-основателя Георга Тупоу I на престол взошёл внук его внука Георг Тупоу II; коронация состоялась 17 марта 1893 года в Нукуалофа.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["Новая Зеландия стала первой самоуправляющейся страной, давшей женщинам право голоса", "0d277cde"], "d": ["Благодаря новому избирательному закону, подписанному губернатором лордом Гласгоу, Новая Зеландия стала первой в мире самоуправляющейся страной, предоставившей женщинам право голоса на парламентских выборах.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["Провозглашена Республика Гавайи", "4346bd5d"], "d": ["Заговорщики, свергнувшие в 1893 году королеву Лилиуокалани, превратили временное правительство в официальную республику; президентом был провозглашён Сэнфорд Доул. Этот переходный режим продержался до американской аннексии 1898 года.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["Границы Новой Зеландии расширены и включили острова Кука и Ниуэ", "d0370a33"], "d": ["Границы Новой Зеландии были расширены и включили острова Кука (Раротонга, Айтутаки и южные острова, а также северные острова Кука) и Ниуэ; эти острова стали подчинённой Новой Зеландии территорией.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["Смерть Георга Тупоу II, воцарение Салоте Тупоу III (Тонга)", "a3084f3b"], "d": ["Георг Тупоу II умер от туберкулёза; его восемнадцатилетняя дочь Салоте на следующий день была провозглашена королевой, коронация состоялась 11 октября 1918 года.", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["Провозглашена Хорезмская Народная Республика", "0a6b79f9"], "d": ["После свержения хана Хивы вслед за Октябрьской революцией 1917 года была провозглашена Хорезмская Народная Республика.", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["Севрский договор — текст раздела империи", "64980d7b"], "d": ["Текст, подписанный османским правительством с державами Антанты и фактически ликвидировавший империю. Положения: Восточная Фракия и область Измира — Греции; в Восточной Анатолии предусматривались независимая Армения и автономный Курдистан; Сирия оставлена Франции, Ирак и Палестина — Англии в качестве мандатов; Проливы переданы международной комиссии; армия сокращена до 50 700 человек, возвращены капитуляции, финансы переданы под контроль Антанты. Великое национальное собрание в Анкаре договор ВОВСЕ НЕ ПРИЗНАЛО и объявило подписавших изменниками родины; текст не вступил в силу, вместо него в 1923 году пришёл Лозаннский договор. Вот причина, по которой на карте нет его отображения — Севрский договор юридически никогда не применялся.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["Красная армия вошла в город Бухара — последний эмир Алим-хан смещён с престола", "f8f5bfcf"], "d": ["Красная армия 2 сентября 1920 года вошла в город Бухару, и последний мангытский эмир Алим-хан был смещён с престола. Эмир отступил в восточную часть страны, в Душанбе, и полгода руководил оттуда борьбой с Советами; Красная армия взяла Душанбе 21 февраля 1921 года, эмир ушёл дальше на восток и оттуда в Афганистан. Ханство было официально упразднено 6 октября 1920 года (см. Бухарская Народная Советская Республика).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["Провозглашена Бухарская Народная Советская Республика", "ef579627"], "d": ["После того как Красная армия 28–31 августа 1920 года разрушила Бухарский эмират и заставила эмира Алим-хана бежать в Восточную Бухару, под председательством Файзуллы Ходжаева была провозглашена Бухарская Народная Советская Республика.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["Тувинская Народная Республика (Танну-Тува) провозгласила независимость", "8710ea3d"], "d": ["Под руководством Тувинской народно-революционной партии была провозглашена независимость; первая статья первой конституции указывала, что государство действует «в международных отношениях под покровительством Советской России».", "3c6cec2c"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["Принята новая конституция Бухарской Народной Советской Республики", "fb17bf39"], "d": ["Была принята новая конституция, которая, в отличие от российской конституции 1918 года, допускала частную собственность на землю и средства производства и давала избирательное право и непролетарским слоям (за исключением родственников свергнутого эмира и крупных землевладельцев).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["Преобразование в Хорезмскую Советскую Социалистическую Республику", "14a1d26f"], "d": ["Страна, изменив название и статус, стала Хорезмской Советской Социалистической Республикой; административно-правовая структура была перестроена по советской системе.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["Правительство Танну-Тувы фактически приступило к работе", "22ea1516"], "d": ["Правительство, созданное после первого партийного собрания в феврале 1922 года, фактически приступило к работе.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["Собрался первый Великий хурал Танну-Тувы", "80fe15f2"], "d": ["Собрался первый Великий хурал (Народное собрание) страны; это первое крупное представительное собрание в процессе институционализации государства.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["Прекращение существования Хорезмской ССР и Бухарской Народной Советской Республики в результате национального размежевания — образование Узбекской и Туркменской ССР", "e8c8ab4f"], "d": ["Решением о советском «национально-территориальном размежевании» (национально-территориальное размежевание) Хорезмская Советская Социалистическая Республика и Бухарская Народная Советская Республика были упразднены; их территории были разделены между вновь созданными Узбекской и Туркменской Советскими Социалистическими Республиками (восток Хивы — Узбекистану, запад — Туркменистану). Статья TDV `harizm`: «В 1924 году восточные части Хивинского ханства были отданы Узбекской Советской Социалистической Республике, а западная сторона — Туркменской Советской Социалистической Республике.» — даёт только год.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["Продажа Аланьи мамлюкскому султану Барсбею", "c8bd35f2"], "d": ["Аланья, захваченная в 1293 году Меджд ад-дином Махмуд-беем из Караманидов, превратилась в отдельный бейлик, управлявшийся одной из ветвей Караманидов; Ибн Баттута в 1333 году отмечает, что управление находилось у Юсуф-бея из Караманидов. Караман, сын Савджи-бея, в 1427 году продал город мамлюкскому султану Барсбею за пять тысяч золотых, и Аланья перешла под мамлюкское управление. Этот ключевой порт Средиземного моря стал в руках мамлюков препятствием на открытом на юг пути османов; когда в 1471 году Гедик Ахмед-паша осадил его, последний бей Кылыч-Арслан сдал город.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["Взятие Табарки у генуэзцев — конец коралловой концессии Ломеллини", "b1f33eb5"], "d": ["После договора Карла V с тунисским беем в 1544 году генуэзская семья Ломеллини поселилась на острове Табарка и двести лет удерживала концессию на добычу кораллов; остров оставался христианским торговым пунктом посреди османского Туниса. Али-паша из династии Хусейнидов, узнав о попытке семьи избавиться от острова, послал силы и 12 июня 1741 года овладел островом; около тысячи пятисот христиан были переселены в Тунис. С этой даты Табарка перешла под управление Тунисского оджака.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["Битва при пирамидах и взятие Каира французами", "3ddd6b96"], "d": ["Наполеон прошёл от Александрии на юг вдоль Нила и 21 июля 1798 года в Имбабе напротив Гизы встретил мамлюкскую (Kölemen) конницу Мурад-бея. Французская пехота в каре сломила кавалерийские атаки; армия мамлюков рассеялась, и Каир через два дня сдался без сопротивления. Мурад-бей отступил в Верхний Египет, Ибрахим-бей — в Сирию. Французы создали в Каире диван и пытались вести управление руками улемов; в октябре 1798 года и в марте 1800 года произошли два крупных каирских восстания.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["Осада Акры Наполеоном — остановка Сирийского похода", "d2a947ad"], "d": ["Наполеон, желая рассеять силы, готовившиеся османами для возвращения Египта, в начале 1799 года двинулся в Сирию; взял Эль-Ариш 18 февраля, Яффу — в марте и 18 марта 1799 года осадил Акру. Оборона Джаззар Ахмед-паши и поддержка с моря английского адмирала Сидни Смита два месяца ломали осаду; поскольку осадные орудия были захвачены на море, стены не удалось преодолеть. Наполеон в мае отступил, и это поражение стало высшей точкой французской оккупации.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["Основание государства эмира Абд аль-Кадира — централизация сопротивления в западном Алжире", "9e482383"], "d": ["Сопротивление, распавшееся после падения Алжира, собралось вокруг юного Абд аль-Кадира, сына кадирийского шейха Мухиддина; 22 ноября 1832 года близ Маскары вожди племён принесли ему присягу с титулом «эмир верующих». Созданная им структура была не племенным союзом, а регулярным государством: у него были монетный двор, пороховая мастерская, налоговый порядок и столица в Тагдемте. Франция договором в Тафне 1837 года официально признала его власть. Абд аль-Кадир нашёл прибежище не у османов, а под сюзеренитетом марокканского султана Абд ар-Рахмана; то есть эти земли после 1832 года не находятся в османском подданстве. 23 декабря 1847 года он сдался, и Османское государство в том же году объявило, что его права на Алжир закончились.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["Падение Константины — конец восточного алжирского бейлика", "159fed36"], "d": ["После падения Алжира в 1830 году восточное бейлербейство не распалось: последний бей Ахмед продолжал своё управление в Константине и объявлял, что действует от имени османов. Первый поход французов в 1836 году закончился разгромом; второй поход 6 октября 1837 года осадил город, командующий Дамремон 12 октября был убит артиллерийским огнём, а 13 октября стены были преодолены, и город был взят улица за улицей. Ахмед-бей отступил в горы и сдался лишь в 1848 году. Эта дата — фактический конец трёхсотлетнего османо-турецкого управления на востоке Алжира.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["Завоевание области Така и основание Кассалы", "cc3e0631"], "d": ["Правитель Судана Ахмед-паша Абу Уддан в 1840 году присоединил к египетскому управлению область Така между реками Атбара и Гаш и основал город Кассалу как военную ставку. Город стал центром мудирии, контролировавшей караванный путь между Сеннаром и Суакином и пограничную полосу Абиссинии.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["Французская оккупация Маскары — потеря столицы Абд аль-Кадира", "bd363c05"], "d": ["С приходом Бюжо на пост губернатора в 1841 году французская стратегия изменилась: вместо того чтобы держаться на побережье — занимать внутренние города один за другим. Подвижные колонны, выходившие из Орана, Мостаганема и Медеа, взяли центры регулярного государства Абд аль-Кадира; важнейшей из них была Маскара — настоящая столица с монетным двором, пороховой мастерской и зернохранилищами. После этого эмир отказался от создания постоянного центра и превратил свою армию в кочевой лагерь, называемый «смала».", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["Оккупация долины Шелифа и Тенеса — основание Орлеанвиля", "e1eeeb68"], "d": ["Чтобы иметь возможность преследовать Абд аль-Кадира, французы в апреле 1843 года основали в середине долины Шелифа новый город Орлеанвиль; в том же году был занят и прибрежный порт Тенес. Так внутренний коридор между Алжиром и Ораном перешёл под французский контроль, и сопротивление в горах Дахра было окружено. 16 мая того же года кочевой лагерь Абд аль-Кадира «смала» был случайно найден и рассеян.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["Основание укреплённого лагеря Сиди-Бель-Аббес", "fb33ec29"], "d": ["Бюжо 12 июня 1843 года отдал генералу Бедо приказ устроить в Сиди-Бель-Аббесе укреплённый лагерь с рвом и стенами; строительство началось 18 июня, а в ноябре того же года в нём разместился батальон Иностранного легиона. Лагерь стал постоянной базой, контролировавшей внутреннюю равнину между Мостаганемом и Тлемсеном.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["Переход Недромы и марокканской пограничной полосы под французский контроль", "61d821f3"], "d": ["После отступления Абд аль-Кадира в Марокко в 1843 году Недрома к северо-западу от Тлемсена и побережье Трара перешли под французский контроль. Сражение при Исли 14 августа 1844 года разгромило марокканскую армию, и граница между двумя странами была проведена конвенцией Лалла-Марния 18 марта 1845 года; Недрома осталась по алжирскую сторону этой линии.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["Падение Лагуата — открытие ворот Сахары", "b161b32c"], "d": ["Генерал Пелисье с шеститысячным отрядом 21 ноября 1852 года осадил Лагуат, и 4 декабря город пал после кровавого штурма. Лагуат был оазисным городом, державшим проход между Теллем и Сахарой; его падение открыло французскому продвижению пустынные караванные пути и подготовило обложение конфедерации Мзаб налогом в течение года.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["Аннексия области Богос (Керен) Египтом", "b2ab83ce"], "d": ["Правитель вилайета «Восточный Судан и Красноморское побережье», основанного хедивом Исмаилом на западном берегу Красного моря, Вернер Мунцингер-паша в 1872 году присоединил к Египту область Богос, населённую народом билен, с центром в Керен. Это было самое прочное продвижение Египта к краю Абиссинского нагорья, и оно положило начало двенадцатилетнему пограничному спору с Абиссинией.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["Аннексия Султаната Дарфур Египтом — Зубейр-паша вошёл в Эль-Фашир", "f41268ed"], "d": ["Окрепший на торговле слоновой костью и рабами Зубейр Рахма-паша вооружёнными ружьями Ремингтона силами 25 октября 1874 года разгромил при Menevâşî армию фур; султан Ибрахим погиб в сражении. Зубейр 2 ноября без боя вошёл в Эль-Фашир, и власть династии Кейра, длившаяся с 1603 года, фактически закончилась. Дарфур тем самым был присоединён к суданским провинциям Египта Мухаммеда Али; но сопротивление семьи Кейра в горах продолжалось до 1891 года.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["Аннексия оазисов Мзаба (Гардая)", "9372959f"], "d": ["Ибадитские города Мзаба в 1852 году согласились платить налог Франции, но сохранили внутреннее управление; тридцать лет спустя, в 1882 году, область была непосредственно присоединена к французской территории, а Гардая была подчинена военному управлению. Так юридически прекратил существование и последний автономный пояс северной Сахары.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["Бомбардировка Александрии и английская высадка", "18d57bf8"], "d": ["Когда офицерское движение под руководством Ураби-паши взяло хедива под контроль, Англия под предлогом безопасности Суэцкого пути вмешалась. Флот адмирала Сеймура 11–12 июля 1882 года обстрелял прибрежные батареи Александрии; после пожара и грабежа в городе 15 июля английские войска высадились на берег. Османское государство не смогло помешать этой операции в юридически подчинённом ему вилайете и оставило без ответа призыв участвовать во вмешательстве. Так был сделан первый шаг оккупации, которой предстояло продлиться тридцать два года.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["Сражение при Тель-эль-Кебире — разгром армии Ураби", "8e38fecf"], "d": ["Уолсли, высадив свои силы через Суэцкий канал в Исмаилии и пройдя пустыней, на рассвете 13 сентября 1882 года внезапно атаковал египетские окопы при Тель-эль-Кебире; сражение закончилось за один час. Ураби на следующий день сдался, и английская кавалерия в тот же день вошла в Каир. После этой даты финансы, армия и внешние дела Египта фактически перешли под английский контроль; османский сюзеренитет юридически продолжался до 1914 года.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["Конвенция Ла-Марса — завершение протектората над Тунисом", "71338640"], "d": ["Договор Бардо (Касс-эс-Саид) от 12 мая 1881 года оставил внешние дела Туниса Франции, но внутреннее управление — бею; через два года, 8 июня 1883 года, подписанная конвенция Ла-Марса передала французскому контролю также финансовые и административные реформы и завершила протекторат. Османское государство продолжало настаивать на своём сюзеренитете над Тунисом и никогда не признавало оккупацию, но не смогло сделать реального ответного шага. Так Тунис, с 1574 года бывший османским оджаком, официально перешёл под французский протекторат.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["Разгром при Шейкане — уничтожение армии Хикс-паши", "a0e08986"], "d": ["Отставной английский офицер Хикс-паша, командовавший отправленным из Каира египетским войском примерно в десять тысяч человек, продвигаясь по кордофанской пустыне без воды и проводников, 5 ноября 1883 года был окружён у Шейкана силами Махди, и армия была почти полностью уничтожена. Этот разгром сломал хребет египетского управления в Судане: в течение месяца сдались Дарфур и Бахр-эль-Газаль, весь Кордофан перешёл к Махди. Отсюда начинается путь к падению Хартума.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["Переход Дарфура к силам Махди — сдача Слатин-паши", "6d8992d4"], "d": ["Генерал-губернатор Дарфура Слатин-паша с 1882 года воевал с махдистским восстанием племени ризейгат; полагая, что поражения его солдат вызваны тем, что он христианин, в 1883 году он открыто принял ислам и взял имя Абдулькадир. После того как армия Хикс-паши в ноябре 1883 года была уничтожена в Кордофане, сопротивление потеряло смысл, и 23 декабря 1883 года он сдался эмиру Мадибо. Небольшие египетские посты в Дарфуре вскоре последовали тем же путём; десятилетнее турецко-египетское управление закончилось.", "85dcfe97"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["Переход Зейлы и сомалийского побережья под английское управление", "1d649502"], "d": ["Когда восстание Махди разрушило египетские гарнизоны в Судане и на Красном море, Каир был вынужден оставить удалённые посты на абиссинском побережье. Английская администрация в Адене в 1884 году высадила войска в Зейле и Бербере; в следующем году были подписаны договоры о покровительстве с сомалийскими вождями племён, и был основан Британский Сомалиленд. Зейла, с 1559 года зависевшая от эялета Хабеш, таким образом была потеряна.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["Сдача гарнизона Фашира махдистам", "68f0760d"], "d": ["И после капитуляции Слатина 23 декабря 1883 года египетский гарнизон в крепости Фашир продолжал сопротивляться. Лишившись колодцев в семидневной осаде, гарнизон 15 января 1884 года сдался; оружие было сложено, и крепость перешла к махдистам.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["Договор Хьюитта (Адуа) — передача Богоса Абиссинии", "0de1b701"], "d": ["Когда восстание Махди окружило египетские гарнизоны в Судане, Англия, чтобы получить помощь Абиссинии, 3 июня 1884 года подписала в Адуа договор с Иоанном IV. Вторая статья договора возвращала Богос Абиссинии, взамен Абиссиния должна была содействовать эвакуации осаждённых гарнизонов через Массауа. Керен тем самым вышел из-под двенадцатилетнего египетского управления; пять лет спустя область будет присоединена к итальянской Эритрее.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["Возвращение Донголы — начало похода вдоль Нила", "f63aa14f"], "d": ["После поражения итальянцев при Адуа Англия повела египетскую армию под командованием Китченера на юг вдоль Нила. По мере продвижения железной дороги по пустыне вопрос снабжения был решён, и вилайет Донгола 23 сентября 1896 года был возвращён. Здесь закончилось одиннадцатилетнее управление Махди; поход продлится ещё два года, достигнув Омдурмана.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["Сражение при Омдурмане — крушение государства Махди", "28dff7b2"], "d": ["Англо-египетская армия Китченера, оснащённая артиллерией и пулемётами, 2 сентября 1898 года за несколько часов рассеяла перед Омдурманом силы халифа Абдаллаха ат-Таайши. На следующий день был занят Хартум, и во дворце, где тринадцать лет назад был убит Гордон, подняли флаг. Столица государства Махди пала; халиф был убит в конце 1899 года при преследовании. Фактическая власть сменяется в эту дату, а 19 января 1899 года — соглашение, создавшее правовые рамки управления.", "ae944d9d"]}
});
